window.STORY_CATEGORIES = window.STORY_CATEGORIES || {}; window.STORY_CATEGORIES[7] = [{"id":831,"category_id":7,"category_code":"s7","source_id":1,"title":"موضوع انشاء: حیوانات","content":"ما حیوانات را خیلی‌ دوست داریم، بابایمان هم همینطور\r\nما هر روز در مورد حیوانات حرف می‌زنیم، بابایمان هم همینطور.\r\nبابایمان همیشه وقتی ‌با ما حرف می‌زند از حیوانات هم یاد می‌کند. مثلا امروز بابایمان دوبار به ما گفت:\r\n\"توله سگ مگه تو مشق نداری که نشستی پای تلوزیون؟\"\r\nوهر وقت ما پول میخواهیم می گوید:\r\n\"کره خر مگه من نشستم سر گنج؟\"\r\nچند روز پیش وقتی‌ ما با مامانمان و بابایمان رفتیم خونه عمه زهرا اینا یک تاکسی داشت می زد به پیکان بابایمان \r\nبابایمان هم که آن روی سگش آمده بود بالا به آقاهه گفت:\r\n: \"مگه کوری گوساله؟\" \r\nآقاهه هم گفت:\r\n\"کور باباته یابو، پیاده می‌شم همچین می‌زنمت که به خر بگی‌ زن دایی\" \r\nبابایمان هم گفت:\r\n\"برو بینیم بابا، جوجه\" \r\nو عین قرقی پرید پایین ولی‌ آقاهه از بابایمان خیلی ‌گنده تر بود و بابایمان را مثل\r\nسگ کتک زد. بعدش مامانمان به بابایمان گفت:\r\n\"مگه کرم داری آخه خرس گنده؟ مجبوری عین خروس جنگی بپری به مردم؟\"\r\nما تلوزیون را هم که خیلی‌ حیوان نشان می‌دهد دوست می‌داریم. البته علی‌آقا شوهر خاله مان می‌گوید که تلوزیون فقط شده راز بقا! \r\nفامیل های ما هم خیلی‌ حیوانات را دوست دارند. پارسال در عروسی‌ منوچهر پسر خاله مان که رفت قاطی‌ مرغ ها، شوهر خاله مان دو تا گوسفند آورد که ما با آن ها خیلی‌ بازی کردیم ولی‌ بعدش شوهر خاله مان همان وسط سرشان را برید! ما اولش خیلی‌ ترسیدیم ولی‌ بابایمان گفت چند تا عروسی‌ برویم عادت می‌کنیم. البته گوسفندها هم چیزی نگفتند و گذاشتند شوهر خاله‌مان سرشان را ببرد. حتما دردشان نیامد!\r\nما نفهمیدیم چطور دردشان نیامده چون یکبار در کامپیوتر داداشمان یک فیلم دیدیم که دوتا آقا که هی‌ می گفتند الله اکبر سر یک آقا رو که نمی‌گفت الله اکبر بریدند و اون آقاهه خیلی‌ دردش اومد و ما تصمیم گرفتیم که همیشه بگیم الله اکبر که یک وقت کسی‌ سرما را نبرد.\r\nما نتیجه می گیریم که خیلی‌ خوب شد که ما در ایران به دنیا آمدیم تا بتوانیم هر روز از اسم حیوانات که نعمت خداوند هستند استفاده کنیم و آنها را در تلوزیون ببینیم در موردشان حرف بزنیم و عکس‌های آن ها را به دیوار بچسبانیم و به آن ها مهرورزی کنیم و نمی دانیم اگر در ایران به دنیا نیامده بودیم چه غلطی باید می‌کردیم!\r\n"},{"id":832,"category_id":7,"category_code":"s7","source_id":2,"title":"زنگ موبایل","content":"تعدادي مرد در رخت كن يك باشگاه گلف هستند موبايل يكي از آنها زنگ مي زند مردي گوشي را بر ميدارد و روي اسپيكر مي گذارد و شروع به صحبت مي كند همه ساكت مي شوند و به گفتگوي او با طرف مقابل گوش مي دهند \r\nمرد: بله بفرماييد.\r\nزن: سلام عزيزم باشگاه هستي؟\r\nمرد: سلام بله باشگاه هستم.\r\nزن: من الان توي فروشگاهم يك كت چرمي خيلي شيك ديدم فقط هزار دلاره ميشه بخرم؟\r\nمرد: آره اگه خيلي خوشت اومده بخر.\r\nزن: مي دوني از كنار نمايشگاه ماشين هم كه رد مي شدم ديدم اون مرسدس بنزي كه خيلي دوست داشتم رو واسه فروش آوردن خيلي دلم ميخواد يكي از اون ها رو داشته باشم.\r\nمرد: چنده؟\r\nزن: شصت هزار دلار.\r\nمرد: باشه اما با اين قيمتي كه داره بايد مطمئن بشي كه همه چيزش رو به راهه.\r\nزن: آخ مرسي يه چيز ديگه هم مونده اون خونه اي كه پارسال ازش خوشم ميومد رو هم واسه فروش گذاشتن 950000 دلاره.\r\nمرد: خوب برو بگو 900000 تا اگه ميتوني بخرش.\r\nزن: باشه بعدا مي بينمت خيلي دوستت دارم.\r\nمرد: خداحافظ\r\nمرد گوشي را قطع مي كند مرد هاي ديگر با تعجب مات و مبهوت به او خيره مي شوند.\r\nبعد مرد مي پرسد: اين گوشي مال كيه؟؟؟\r\n"},{"id":833,"category_id":7,"category_code":"s7","source_id":3,"title":"کار سخت","content":"بنده در دوران كودكي علاقه اي به خلبان شدن نداشتم!اما از بد روزگار در دوران دانشجويي كمي تا قسمتي چتر باز از آب در امدم وبعد از ترم اول كمتر درسي بود كه با تقلب يا به اميد تقلب سر جلسه امتحان نرفته باشم!پس اگر قرار به انتخاب خاطره از تقلب باشد انتخاب يكي از بين اون همه خاطره بايد كار سختي باشه!\r\nمثلا ميشه از امتحان پايان ترم استاتيك شروع كنم كه تقلب رو به صورت كاملا حرفه اي در دستشويي جاسازي كرده بودم واز بد شانسي درست همون روز آب قطع شد واميدمون ازتقلب قطع شد وافتادم!\r\nيا ميشه ازامتحان فيزيك 2بگم كه امتحان تستي بودومن ودوتا از دوستام از رو دست يكي از دختراي كلاس نوشتيم اما بعدش فهميديم كه چه فايده كه ترتيب سوالات يكي نبوده وجمع نمرات سه نفرمون به نمره قبولي نميرسه واز همه بدتر اينكه اون دختره از همه كمتر گرفته!\r\nيا از يه استاد ديگه كه از لحاظ سني چيزي از عمو جغدشاخدار كم نداشت حتي وقتي تقلبمون رو گرفت هم از رو نرفتيم واونم با اون صدايي كه انگار از ته چاه ميومد بهمون گفت:حالا درسته... ما... چيزي نميگيم... ولي خب شمام رعايت ....كنيد.!\r\nيا اشاره كنم به امتحان ميان ترم درس مقاومت مصالح كه جزوه رو با دوستم نصف كرديم وهركسي نصف خودشو تو يه كاغذ مچاله نوشتيم وبه هم ديگه داديم تا بهترين افتخار دوران دانشجوييم(البته تا امروز) كسب بشه ونمره دوم كلاس رو كسب كنم!گرچه وقتي تو پايان ترم با نمره 12از دستش خلاص شدم استاد بهم گفت:با اون ميان ترم درخشان ازت انتظار زيادي داشتم!\r\nاما جاي داره ياد كنم از استاد(ن)كه حسرت تقلب تو كلاسش تو دلم موند! كسي كه صاحب كرامات متعدد بود مثلا علاوه بر اون كنترل هاي معمول ماشين حساب هاي همه بچه هارو يكي يكي چك ميكرد تا كاري جز چهار عمل اصلي ازشون بر نياد!وبرا امتحان كلاس بزرگي رو انتخاب ميكرد وكروكي كلاس رو ميكشيد واز بچه ها ميخواست كه شماره دانشجويي خودشون روبنويسن ومدعي بود كه تو خونه تمام ورقه هاي همسايه رو با هم تطبيق ميده تا در حق كسي اجحاف نشه! يه بار هم با افتخار اعتراف كرد اسم تموم كسايي رو كه برا دستشويي ميرن بيرون رو مينويسه تا مو رو از ماست بكشه بيرون!\r\nحالا بگذريم از اينكه يه باربه يكي از بچه ها كه راه حلش تقريبا با جزوه يكي بود صفر داد وازش خواست كه اگه اعتراضي داره به (آموزش دانشكده) منعكس كنه!\r\n"},{"id":834,"category_id":7,"category_code":"s7","source_id":4,"title":"بهشت یا جهنم","content":"دختر کوچکى با معلمش درباره نهنگ‌ها بحث مى‌کرد.\r\nمعلم گفت: از نظر فيزيکى غيرممکن است که نهنگ بتواند يک آدم را ببلعد زيرا با وجود اینکه پستاندار عظيم‌الجثه‌اى است امّا حلق بسيار کوچکى دارد.\r\nدختر کوچک پرسيد: پس چطور حضرت يونس به وسيله يک نهنگ بلعيده شد؟\r\nمعلم که عصبانى شده بود تکرار کرد که نهنگ نمى‌تواند آدم را ببلعد. اين از نظر فيزيکى غيرممکن است.\r\nدختر کوچک گفت: وقتى به بهشت رفتم از حضرت يونس مى‌پرسم.\r\nمعلم گفت: اگر حضرت يونس به جهنم رفته بود چى؟\r\nدختر کوچک گفت: اونوقت شما ازش بپرسيد!!!\r\n"},{"id":835,"category_id":7,"category_code":"s7","source_id":5,"title":"کاربد","content":"يک روز يک دختر کوچک در آشپزخانه نشسته بود و به مادرش که داشت آشپزى مى‌کرد نگاه مى‌کرد. ناگهان متوجه چند تار موى سفيد در بين موهاى مادرش شد.\r\nاز مادرش پرسيد: مامان! چرا بعضى از موهاى شما سفيده؟\r\nمادرش گفت: هر وقت تو يک کار بد مى‌کنى و باعث ناراحتى من مى‌شوی، يکى از موهايم سفيد مى‌شود.\r\nدختر کوچولو کمى فکر کرد و گفت: حالا فهميدم چرا همه موهاى مامان بزرگ سفيد شده!\r\n"},{"id":836,"category_id":7,"category_code":"s7","source_id":6,"title":"آقا معلم ","content":"عکاس سر کلاس درس آمده بود تا از بچه‌هاى کلاس عکس يادگارى بگيرد.معلم هم داشت همه بچه‌ها را تشويق مي‌کرد که دور هم جمع شوند.\r\nمعلم گفت: ببينيد چقدر قشنگه که سال‌ها بعد وقتى همه‌تون بزرگ شديد به اين عکس نگاه کنيد و بگوئيد : اين احمده، الان دکتره. يا اون مهرداده، الان وکيله. يکى از بچه‌ها از ته کلاس گفت: اين هم آقا معلمه، الان مرده!\r\n"},{"id":837,"category_id":7,"category_code":"s7","source_id":7,"title":"ستاره ی دنباله دار ","content":"رییس یک کارخانه بزرگ معاون خود را احضار و به او می گوید:\r\nروز دوشنبه، حدود ساعت 7 غروب، ستاره دنباله دار هالی دیده خواهد شد. نظر به اینکه چنین پدیده ای هر 78 سال یکبار تکرار می شود، به همه کارگران ابلاغ کنید که قبل از ساعت 7، با به سر داشتن کلاه ایمنی، در حیاط کارخانه حضور یابند تا توضیحات لازم داده شود. در صورت بارندگی مشاهده هالی با چشم عریان (غیر مسلح) ممکن نیست وبه همین خاطر کارگران را به سالن نهارخوری هدایت کنید تا از طریق نمایش فیلم با این پدیده شگفت آشنا شوند.\r\nمعاون خطاب به مدیر تولید: \r\nبنا به دستور جناب آقای رییس، ستاره دنباله دار هالو روز دوشنبه بالای کارخانه طلوع خواهد کرد. در صورت ریزش باران، کلیه کارگران را با کلاه ایمنی به سالن نهار خوری ببرید تا فیلم مستندی را درباره این نمایش عجیب که هر 78 سال یکبار در برابر چشمان عریان اتفاق می افتد، تماشا کنند. \r\nمدیر تولید خطاب به سرپرست:\r\n\"بنا به درخواست آقای معاون، قرار است یک آدم 78 ساله هالو با کلاه ایمنی و بدن عریان در نهارخوری کارخانه فیلم مستندی درباره امنیت در روزهای بارانی نمایش دهد.\"\r\nسرپرست خطاب به سرکارگر:\r\n\"طبق دستور و با اجرای هالو 78 ساله ، همه کارگران بایستی روز دوشنبه ساعت 7 لخت و عریان در حیاط کارخانه جمع شوند و به آهنگ بارون بارونه گوش کنن.\" \r\nسرکارگر خطاب به کارگران: \r\nآقای رییس روز دوشنبه 78 سالش می شود و قرار است در حیاط کارخانه و سالن نهار خوری بزن و بکوب راه بیفته و گروه هالو پشمالو برنامه اجرا کنه. هرکس مایل بود میتونه برهنه بیاد ولی کلاه ایمنی لازمه!!\r\n"},{"id":838,"category_id":7,"category_code":"s7","source_id":8,"title":" حاضر جواب","content":"ﯾﻪ ﺭﻭﺯ ﯾﻪ ﺩﺍﻧﺸﺠﻮﯾﯽ برای ﺧﻮﺭﺩﻥ ﻏﺬﺍ می ره به ﺳﻠﻒ ﺩﺍﻧﺸﮕﺎﻩ. ﻭﻟﯽ اشتباها می ره ﺳﺮ ﻣﯿﺰ ﺍﺳﺎﺗﯿﺪ، ﺭﻭ ﺑﻪ ﺭﻭﯼ ﺍﺳﺘﺎﺩ ﺩﺍﻧﺸﮕﺎﻩ می نشینه ﻭ ﺷﺮﻭﻉ می کنه ﺑﻪ ﻏﺬﺍ ﺧﻮﺭﺩﻥ. ﺍﺳﺘﺎﺩ ﺗﺎ ﺍﯾﻦ ﺻﺤﻨﻪ ﺭﻭ می بینه ﻋﺼﺒﺎﻧﯽ می شه ﻭ می گه: ﮔﺎﻭﻫﺎ ﺑﺎ ﭘﺮﻧﺪﻩ ﻫﺎ ﺗﻮ ﯾﻪ ﺟﺎ ﻏﺬﺍ نمی خوﺭﻥ. ﺩﺍﻧﺸﺠﻮ ﺧﯿﻠﯽ ﺧﻮﻧﺴﺮﺩ می گه: ﺑﻠﻪ، ﺩﺭﺳﺘﻪ. پس من ﭘﺮﻭﺍﺯ می کنم ﻭ می رم ﯾﻪ ﺟﺎی ﺩﯾﮕﻪ می نشینم! ﺍﺳﺘﺎﺩ ﮐﻪ ﺷﺪﯾﺪﺍ ﺍﺯ ﺩﺳﺖ ﺩﺍﻧﺸﺠﻮﯼ ﺣﺎﺿﺮ ﺟﻮﺍﺏ ﻋﺼﺒﺎﻧﯽ می شه، ﺗﺼﻤﯿﻢ می گیرﻩ ﻣﻮﻗﻊ ﺍﻣﺘﺤﺎﻥ تلافی کنه! بعد از ﺍﻣﺘﺤﺎﻥ، بعد از این که ﺍﺳﺘﺎﺩ ﻭﺭﻗﻪ ﺩﺍﻧﺸﺠﻮ ﺭﻭ ﺗﺼﺤﯿﺢ می کنه، ﻣﺘﻮﺟﻪ می شه ﺩﺍﻧﺸﺠﻮ می تونه ﺑﻪ ﺭﺍﺣﺘﯽ درس رو ﭘﺎﺱ ﮐﻨﻪ. به همین دلیل به دانشجو می گه: ﯾﻪ ﺳﻮﺍﻝ می پرسم، اگر ﺟﻮﺍﺏ ﻣﻨﻄﻘﯽ ﺑﺪهی ﻧﻤﺮﻩ ﺗﻮ رو می دهم. ﻭ ﺳﻮﺍﻝ ﺍﯾﻨﻪ: ﺗﻮی ﯾﻪ ﮐﯿﺴﻪ ﭘﻮﻝ ﻭ ﺗﻮی ﯾﻪ ﮐﯿﺴﻪ ﺩﯾﮕﻪ ﻋﻘﻞ ﻭ ﺷﻌﻮﺭ ﻭﺟﻮﺩ ﺩﺍﺭﻩ، ﺗﻮ ﮐﺪﻭم رو ﺍﻧﺘﺨﺎﺏ می کنی؟ ﺩﺍﻧﺸﺠﻮ: ﮐﯿﺴﻪ ﭘﺮ از ﭘﻮﻝ رو! ﺍﺳﺘﺎﺩ: ﻭﻟﯽ اگر من بودم، ﻋﻘﻞ ﻭ ﺷﻌﻮﺭ رﻭ ﺍﻧﺘﺨﺎﺏ می کرﺩﻡ ﮐﻪ ﺧﯿﻠﯽ مهم تر از ﭘﻮﻟﻪ. ﺩﺍﻧﺸﺠﻮ: ﺑﻠﻪ ﺩﻗﯿﻘﺎ! ﭼﻮﻥ ﻫﺮ ﮐﺴﯽ ﭼﯿﺰی رو برمی دﺍﺭﻩ ﮐﻪ ﻧﺪﺍﺭﻩ!\r\nﺍﺳﺘﺎﺩ ﮐﻪ ﺩﯾﮕﻪ ﺧﻮﻧﺶ ﺑﻪ ﺟﻮﺵ ﺍﻭﻣﺪﻩ ﺑﻮﺩ ﭘﺎﯼ ﺑﺮﮔﻪ ﺩﺍﻧﺸﺠﻮ می نویسه: \"ﮔﺎﻭ\" ﻭ ﺑﺮﮔﻪ ﺭﻭ می ده ﺑﻪ ﺩﺍﻧﺸﺠﻮ. ﺩﺍﻧﺸﺠﻮ ﺑﺪﻭﻥ این که ﺑﻪ ﺑﺮﮔﻪ ﻧﮕﺎﻩ ﮐﻨﻪ ﺍﺯ ﮐﻼﺱ می ره ﺑﯿﺮﻭﻥ. ﻭﻟﯽ ﭼﻨﺪ ﻟﺤﻈﻪ ﺑﻌﺪ بر می گرده ﻣﯿﺎﺩ ﺗﻮ ﻭ ﺑﻪ ﺍﺳﺘﺎﺩ می گه: ﺧﯿﻠﯽ ﺑﺒﺨﺸﯿﺪ، ﺷﻤﺎ ﭘﺎﯼ ﺑﺮﮔﻪ ﻣﻦ ﺍﻣﻀﺎﺗﻮن رو ﺯﺩید ﻭﻟﯽ ﻧﻤﺮﻩ من رو ﯾﺎﺩﺗﻮﻥ ﺭﻓﺖ ﺑﻨﻮیسید!\r\n"},{"id":839,"category_id":7,"category_code":"s7","source_id":9,"title":"هم کلاسی","content":"تاکنون پيش آمده که به فردى هم سن و سال خود نگاه کرده باشيد و پيش خود گفته باشيد: نه، من مطمئناً اين قدر پير و شکسته نشده‌ام؟ اگر جوابتان مثبت است از داستان زير خوشتان خواهد آمد: من يک روز در اتاق انتظار يک دندانپزشک نشسته بودم. بار اولى بود که پيش او مى‌رفتم.به مدارکش که در اتاق انتظار قاب کرده بود و به ديوار زده بود، نگاه کردم و اسم کاملش را ديدم. ناگهان به يادم آمد که ٣٠ سال پيش، در دوران دبيرستان، پسر بلندقد، مو مشکى و مهربانى به همين اسم در کلاس ما بود. وقتى که نوبتم شد و وارد اتاق او شدم به سرعت متوجه شدم که اشتباه کرده‌ام. اين آدم خميده، مو خاکسترى و با صورت پر چين و چروک نمى‌توانست همکلاسى من باشد. بعد از اين که کارش بر روى دندان هايم تمام شد و آماده ترک مطب بودم از او پرسيدم که آيا به مدرسه البرز مى ‌رفته است؟  او گفت: بله، بله. من البرزى هستم.  پرسيدم: چه سالى فارغ‌ التحصيل شديد؟ گفت: ١٣٥٩. چرا اين سوال را مى‌پرسيد؟ گفتم: براى اين که شما در همان کلاسى بوديد که من بودم. او چشمانش را تنگ کرد و کمى به من خيره شد و بعد گفت: شما چى درس مى‌داديد؟"},{"id":840,"category_id":7,"category_code":"s7","source_id":10,"title":"مقصد نامعلوم","content":"معروف است که یک بار اینشتین در امریکا با قطار در حال مسافرت بوده که مامور قطار برای دیدن بلیط سر می رسد اما اینشتین هر چه که می گردد بلیط را پیدا نمی کند. مامور که این وضع را می بیند، می گوید \"حضرت استاد! کیست که شما را نشناسد و یا شک کند شما بلیط نگرفته اید. نیازی به نشان دادن بلیط نیست\" و از کوپه او دور می شود. اینشتین سری به نشانه تشکر تکان می دهد. مامور بعد از تمام کردن کوپه های دیگر این واگن، نگاهی به عقب می اندازد و متوجه می شود اینشتین همچنان در حال گشتن است. برمی گردد و می گوید : \"پروفسور اینشتین! گفتم که شما را می شناسم و نیازی به بلیط نیست، چرا باز هم نگرانید؟\" اینشتین جواب می دهد: \"این هائی که گفتی خودم هم می دانم، دنبال بلیط هستم ببینم به کجا دارم می روم!\""},{"id":841,"category_id":7,"category_code":"s7","source_id":11,"title":"بهانه جو","content":"مرد تازه به خانه رسیده بود و هنوز پیراهن از تن خارج نکرده بود که با صدای جیغ و کوبیده شدن کت و شلوارش به صورت اش هاج و واج ماند و همسرش را دید که با گریه می گفت: این چیه؟ ها نامرد! این چیه؟ یه تار موی بلوند بلند روی کت تو بود! من همیشه می دونستم که تو یه زن مو بلند بلوند رو به من ترجیح می دهی!به هر قائله اون روز گذشت و روز بعد... مرد تازه به خانه رسیده بود و هنوز پیراهن از تن خارج نکرده بود که با صدای جیغ و کوبیده شدن کت و شلوارش به صورت اش هاج و واج ماند و همسرش را دید که با گریه می گفت:\r\nاین چیه؟ ها نامرد! این چیه؟ یه تار موی مشکی بلند روی کت تو بود! من همیشه می دونستم که تو یه زن مو بلند و مشکی رو به من ترجیح می دهی!آن روز هم به هر قائله ای بود، گذشت و روز بعد مرد پیش از بازگشت به خانه، به خشکشویی محل رفت با پرداخت انعام اضافه دستور داد کتش را به خوبی برس بزنند و حتی بخار بدهند و مجدد برس بزنند و به او اطمینان دهند که حتی یک سبیل مرد هم روی کت او نیست! و سپس عازم خانه شد مرد تازه به خانه رسیده بود و به آرامی و اطمینان با لبخند پیروزمندانه پیراهن از تن خارج می کرد که با صدای جیغ و کوبیده شدن کت و شلوارش به صورت اش هاج و واج ماند و همسرش را دید که با گریه می گفت: بی صفت پست! نامرد! این یعنی چی؟ من هیچ وقت فکرش رو هم نمی کردم که تو یه زن کچل رو به من ترجیح بدهی!\r\n"},{"id":842,"category_id":7,"category_code":"s7","source_id":12,"title":"رییس جمهور آینده","content":"از دختر یکی از دوستانم پرسیدم که وقتی بزرگ شدی می خواهی چه کاره بشی؟ نگاهم کرد و گفت که می خواد رئیس جمهور بشه.\r\nپرسیدم که اگه رئیس جمهور بشی، اولین کاری که دوست داری انجام بدی چیه؟ جواب داد: به مردم گرسنه و بی خانمان کمک می کنم.\r\nبهش گفتم: نمی تونی منتظر بمونی که وقتی رئیس جمهور شدی این کار رو انجام بدی، می تونی از فردا به خانه ی من بیایی و چمن ها رو بزنی، درخت ها رو وجین کنی و پارکینگ رو جارو کنی. اون وقت من به تو 50 دلار می دهم و تو رو می برم جاهایی که بچه های فقیر هستن و تو می تونی این پول رو بدی بهشون تا برای غذا و خونه ی جدید خرج کنن. مستقیم توی چشمام نگاه کرد و گفت: چرا همون بچه های فقیر رو نمی بری خونه ات، تا این کارها رو انجام بدن و همون پول رو به خودشون بدی؟ نگاهی بهش کردم و گفتم: به دنیای سیاست خوش اومدی!\r\n"},{"id":843,"category_id":7,"category_code":"s7","source_id":13,"title":"گمشده ","content":"در یک ﺭﻭﺯ ﺁﻓﺘﺎﺑﯽ، یک ﺧﺎﻧﻢِ ﺍﻧﮕﻠﯿﺴﯽ ﺭﻭﯼ ﻋﺮﺷﻪ ﮐﺸﺘﯽ ﺩﺭ ﺳﻮﺍﺣﻞ ﻣﮑﺰﯾﮏ ﺑﻪ ﺩﺭﯾﺎ ﻧﮕﺎﻩ می کرد ﮐﻪ ﻧﺎﮔﻬﺎﻥ ﺍﻧﮕﺸﺘﺮ ﺍﻟﻤﺎﺱ ﮔﺮﺍﻧﺒﻬﺎﯾﺶ ﺍﺯ ﺍﻧﮕﺸﺘﺶ ﺳﺮ ﺧﻮﺭﺩ ﻭ ﺍﻓﺘﺎﺩ ﺗﻮی ﺁﺏ ﻭ ﺯﻥ ﺑﺎ ﻧﺎﺭﺍﺣﺘﯽ ﺍﯾﻦ ﺳﻔﺮ ﺭﺍ ﺳﭙﺮی کرد.\r\nﭘﺲ ﺍﺯ ۱۵ﺳﺎﻝ ﮐﻪ ﺑﻪ ﺷﻬﺮ ﻣﮑﺰﯾﮑﻮ ﺳﯿﺘﯽ ﺭﻓﺘﻪ ﺑﻮﺩ، ﺩﺭ ﯾﮏ ﺭﺳﺘﻮﺭﺍﻥ ﺩﺭ ﮐﻨﺎﺭ ﺳﺎﺣﻞ ﺳﻔﺎﺭﺵ ﺧﻮﺭﺍﮎ ﻣﺎﻫﯽ ﺩﺍﺩ، ﻭﻗﺘﯽ ﺩﺍﺷﺖ ﻣﺎﻫﯽ ﺭﻭ می خوﺭﺩ،\r\nﯾﻪ ﺟﺴﻢ ﺳﻔﺖ ﻭ ﺳﺨﺖ ﺯﯾﺮ ﺩﻧﺪﻭﻧﺶ ﺣﺲ ﮐﺮﺩ ﻭ ﻭﻗﺘﯽ ﺩﺭ ﺁﻭﺭﺩ ﺩﯾﺪ\r\n .\r\n.\r\n.\r\n.\r\n.\r\n.\r\n.\r\n.\r\n.\r\nﺍﺳﺘﺨﻮﺍﻥ ﻣﺎﻫﯿﻪ!\r\nﻧﮑﻨﻪ ﻓﮑﺮ ﮐﺮﺩﯼ ﺍﻧﮕﺸﺘﺮﻩ؟ ﺑﺎﺑﺎ ﺗﻮ ﺩﯾﮕﻪ ﺧﯿﻠﯽ ﺗﺨﯿﻠﺖ ﻗﻮﯾﻪ!\r\n"},{"id":844,"category_id":7,"category_code":"s7","source_id":14,"title":"توفیق اجباری ","content":"یه میلیاردری بود که توی خونه اش تمساح نگه می داشت و اون ها رو گذاشته بود توی استخر پشت خونه اش، اون یه دختر خیلی زیبا هم داشت... یه روز یه مهمونی خیلی مجلل گرفت. وسط های مجلس، پسرهای توی مهمونی رو جمع کرد و گفت می خوام براتون یه مسابقه بذارم. هر کدوم از شما بتونه این استخر پر از تمساح رو تا ته شنا کنه من یه میلیارد تومن بهش جایزه می دم یا این که دخترم رو به عقدش در میارم. \r\nهنوز جمله آخرش تموم نشده بود که یکی پرید توی آب و تمساح ها همه رفتن طرفش. اون هم با هر بدبختی ای بود فرار کرد و تا ته طرف دیگر استخر رو شنا کرد. وقتی بیرون اومد، فقط چند خراش کوچک برداشته بود. \r\nمیلیاردر که خیلی کف کرده بود، گفت: آفرین! خیلی خوشم اومد، حالا دخترم رو می خوای یا یک میلیارد تومن رو؟  \r\nپسره گفت: هیچ کدوم، اون فلان فلان شده ای رو که منو هول داد توی آب می خوام!\r\n"},{"id":845,"category_id":7,"category_code":"s7","source_id":15,"title":"مشروطه ","content":"بهاء الواعظین می نویسد: در ابتدای مشروطه؛ به خانه ای رفتم؛ پیر زن و دختر جوانی آن جا بودند. پیر زن پرسید: منظور از مشروطه چیست؟ گفتم: قوانین جدید. گفت: مثلا چه؟ به شوخی گفتم: مثلا دختران جوان را به پیر مردان دهند و زنان پیر را به جوانان! دخترش گفت: این چه فایده دارد؟ پیر زن بلافاصله به دخترش گفت: ای بی حیا! حالا کار تو به جایی رسیده که بر قانون مشروطه ایراد می گیری؟"},{"id":846,"category_id":7,"category_code":"s7","source_id":16,"title":"راننده تاکسی","content":"سه تا مرد مست سوار تاکسی شدن. در رو که بستن، راننده دید خیلی مستن، سریع ماشین رو روشن کرد، بعد زود خاموش کرد و گفت: \"مسافران عزیز! رسیدیم به مقصد!\"مرد اولی پول می ده پیاده می شه... مرد دومی نه تنها پول می ده، بلکه تشکر هم می کنه!مرد سوم اما با عصبانیت تمام یه دونه محکم می زنه پس گردن راننده! راننده می گه چرا می زنی؟می گه: اینو زدم که درس عبرتی بشه واست، از این به بعد تند نری! داشتی هممون رو به کشتن می دادی مردیکه!"},{"id":847,"category_id":7,"category_code":"s7","source_id":17,"title":"نابینایان","content":"دو خلبان نابینا که هر دو عینک های تیره به چشم داشتند، در کنار سایر خدمه پرواز به سمت هواپیما آمدند، در حالی که یکی از آنها عصایی سفید در دست داشت و دیگری به کمک یک سگ راهنما حرکت می کرد. زمانی که دو خلبان وارد هواپیما شدند، صدای خنده ناگهانی مسافران فضا را پر کرد. اما در کمال تعجب دو خلبان به سمت کابین پرواز رفته و پس از معرفی خود و خدمه پرواز، اعلام مسیر و ساعت فرود هواپیما، از مسافران خواستند کمربندهای خود را ببندند در همین حال، زمزمه های توام با ترس و خنده در میان مسافران شروع شده و همه منتظر بودند یک نفر از راه برسد و اعلام کند این ماجرا فقط یک شوخی یا چیزی شبیه دوربین مخفی بوده است! اما در کمال تعجب و ترس آنها، هواپیما شروع به حرکت روی باند کرده و کم کم سرعت گرفت. هر لحظه بر ترس مسافران افزوده می شد چرا که می دیدند هواپیما با سرعت به سوی دریاچه کوچکی که در انتهای باند قرار دارد می رود. هواپیما همچنان به مسیر خود ادامه می داد و چرخ های آن به لبه دریاچه رسیده بود که مسافران از ترس شروع به جیغ و فریاد کردند. اما در این لحظه هواپیما ناگهان از زمین برخاست و سپس همه چیز آرام آرام به حالت عادی بازگشته و آرامش در میان مسافران برقرار شد. در همین هنگام در کابین خلبان، یکی از خلبانان به دیگری می گوید:باب، یکی از همین روزها بالاخره مسافرها چند ثانیه دیرتر شروع به جیغ زدن می کنن و اون وقت کار همه مون تمومه!"},{"id":848,"category_id":7,"category_code":"s7","source_id":18,"title":"نق نقو","content":"مرد کشاورزی یک زن نق نقو داشت که از صبح تا نصف شب در مورد هر چیزی شکایت می کرد. تنها زمان آسایش مرد زمانی بود که با قاطر پیرش در مزرعه شخم می زد. یک روز، وقتی که همسرش برایش ناهار آورد، کشاورز قاطر پیر را به زیر سایه ای راند و شروع به خوردن ناهار خود کرد. بلافاصله همسر نق نقو مثل همیشه شکایت را آغاز کرد. ناگهان قاطر پیر با هر دو پای عقبی لگدی به پشت سر زن زد و او در دم کشته شد. در مراسم تشییع جنازه چند روز بعد، کشیش متوجه چیز عجیبی شد. هر وقت یک زن عزادار برای تسلیت گویی به مرد کشاورز نزدیک می شد، مرد گوش می داد و به نشانه تصدیق سر خود را بالا و پایین می کرد، اما هنگامی که یک مرد عزادار به او نزدیک می شد، او بعد از یک دقیقه گوش کردن سر خود را به نشانه مخالفت تکان می داد. پس از مراسم تدفین، کشیش از کشاورز قضیه را پرسید.کشاورز گفت: خوب، این زنان می آمدند چیز خوبی در مورد همسر من می گفتند، که چقدر خوب بود، یا چه قدر خوشگل یا خوش لباس بود، بنابر این من هم تصدیق می کردم.کشیش پرسید، پس مردها چه می گفتند؟ کشاورز گفت: آنها می خواستند بدانند که آیا حاضرم قاطر را بفروشم یا نه؟"},{"id":849,"category_id":7,"category_code":"s7","source_id":19,"title":"درهم برهم","content":"مینی بوس پر از مسافر به سوی مقصد در حرکت بود که مردی رو می بینن که تلو تلو می خورده و منتظر تاکسی بوده. فکر می کنن حالش بده، توقف می کنند و مرد بی چاره رو سوار می کنند. همین که راه می افتند، مرد مست به دور و برش نگاهی می کنه و می گه: \"عقبی ها بی شرفن، جلویی ها بی شعورن، سمت راستی ها خرن و سمت چپی ها گاون!\" راننده مینی بوس شاکی می شه و چنان می کوبه روی ترمز که همه ی مسافرها روی همدیگه می افتند! راننده میاد مرد مست رو از زیر دست و پای مسافرها می کشه بیرون و می گه: مردک! اگر جرات داری یک بار دیگه بگو کی خر و گاو و بی شعوره! مرد مست با کمال خونسردی می گه: \"من از کجا بدونم؟ با اون ترمزی که تو کردی همه قاطی شدند!\""},{"id":850,"category_id":7,"category_code":"s7","source_id":20,"title":"راز بی شوهری!","content":"یکی از دوستام با یه پسر خیلی پولدار آشنا شده بود و تصمیم داشت هر طور شده باهاش عروسی کنه، تو یه مهمونی یه دفعه از دهنش پرید که 5 ساله دفتر خاطرات داره و همه چیزشو توش می نویسه، این آقا هم گیر داد که دفتر خاطراتت رو بده من بخونم!\r\nاز فردای اون روز مژگان و من نشستیم به نوشتن یه دفتر خاطرات تقلبی براش، من وظیفه قدیمی جلوه دادنش رو داشتم...، 10 جور خودکار واسش عوض کردم، پوست پرتقال مالیدم به بعضی برگه هاش...، چایی ریختم روش... مژی هم تا می تونست خودش رو خوب نشون داد و همش نوشت از تنهایی و من خیلی پاکم و اصلا دنبال مادیات نیستم و فقط انسانیت برام مهمه و... بعد از یک هفته کار مداوم، دفتر خاطرات رو بُرد تقدیم ایشون کرد. آقا پسر در ایکی ثانیه دفتر خاطرات رو بر فرق سر مژی کوبید و گفت: منو چی فرض کردی؟\r\nاین که سالنامه 1390 هست! تو 5 ساله داری توی این خاطره می نویسی؟ و این گونه بود که مژی هنوز مجرد است!\r\n"},{"id":851,"category_id":7,"category_code":"s7","source_id":21,"title":"فرزند پدر","content":"یه روز صبح روزنامه نگاری داشت می رفت سر کار ولی به خاطر تصادفی که شده بود توی ترافیک گیر افتاده بود.\r\nوقتی دید ترافیکه و سر ساعت به محل کارش نمی رسه، تصمیم گرفت همان جا کارش رو انجام بده و از تصادف یک خبر داغ تهیه کنه.\r\nجمعیت زیادی دور محوطه تصادف جمع شده بودن و این نشون می داد که اتفاق خیلی بدی افتاده! بنابراین خبرنگار برای رسوندن خودش به محل تصادف فکری کرد و بعد فریاد زد: بگذارید رد شم... خواهش می کنم بذارید رد شم... من پسرشم! من پسرشم! \r\nولی وقتی به صحنه ی تصادف رسید فکر می کنید،چی دید؟\r\n.\r\n.\r\n.\r\n.\r\n.\r\n.\r\n.\r\n.\r\n. \r\nیه الاغ!\r\n"},{"id":852,"category_id":7,"category_code":"s7","source_id":22,"title":"سیاست مدار","content":"دختر کوچولو وارد بقالی شد و کاغذی به طرف بقال دراز کرد و گفت: مامانم گفته چیزهایی که در این لیست نوشته بهم بدی، این هم پولش.\r\nبقال کاغذ رو گرفت و لیست نوشته شده در کاغذ را فراهم کرد و به دست دختر بچه داد، بعد لبخندی زد و گفت: چون دختر خوبی هستی و به حرف مامانت گوش می دی، می تونی یک مشت شکلات به عنوان جایزه برداری. ولی دختر کوچولو از جای خودش تکون نخورد، مرد بقال که احساس کرد دختر بچه برای برداشتن شکلات ها خجالت می کشه گفت: \"دخترم! خجالت نکش، بیا جلو خودت شکلات هاتو بردار\"\r\nدخترک پاسخ داد: \"عمو! نمی خوام خودم شکلات ها رو بردارم، نمی شه شما بهم بدین؟\"بقال با تعجب پرسید:\r\nچرا دخترم؟ مگه چه فرقی می کنه؟و دخترک با خنده ای کودکانه گفت: آخه مشت شما از مشت من بزرگتره!\r\n"},{"id":853,"category_id":7,"category_code":"s7","source_id":23,"title":"چکمه هایم! ","content":"خانم جوانی که در کودکستان با بچه های 4 ساله کار می کرد می خواست چکمه های یه بچه ای رو پاش کنه ولی چکمه ها به پای بچه نمی رفت. بعد از کلی فشارو خم و راست شدن، بچه رو بغل مي کنه و مي ذاره روی میز، بعد روی زمین... و بالاخره با هزار جابجایی و فشار چکمه ها رو پای بچه می کنه و یه نفس راحت می کشه که... هنوز آخیش گفتنش تموم نشده که بچه مي گه این چکمه ها لنگه به لنگه است!\r\nخانم ناچار با هزار زور و اینور و اونور شدن و در حالی که مواظب هست که بچه نیافته هرچه می تونه می کشه تا بالاخره چکمه های تنگ رو یکی یکی از پای بچه درمیاره و باز با همان زحمت زیاد پوتین ها رو این بار دقیق و درست پای بچه می کنه که لنگه به لنگه نباشه.\r\nدر این لحظه بچه مي گه این چکمه ها مال من نیست!\r\nخانم جوان با یه بازدم طولانی و سر تکان دادن که انگار یک مصیبتی گریبان گیرش شده، با خستگی تمام نگاهی به بچه می اندازه و می گه آخه چی بهت بگم؟ دوباره با زحمت بیشتر این چکمه های بسیار تنگ رو در میاره. وقتی کار تمام می شه از بچه می پرسه: خوب، حالا چکمه های تو کدومه؟ بچه می گه: همین ها! این ها چکمه های برادرمه ولی مامانم گفته اشکالی نداره می تونم پام کنم... مربی که دیگه خون خونشو می خورد سعی می کنه خونسردی خودش رو حفظ کنه و دوباره این چکمه هایی رو که به پای بچه نمی رفت به پای اون بکنه... بعد از اتمام کار یک آه طولانی می کشه و می پرسه: خوب، حالا دستکش هات کجا هستند؟ توی جیبت که نیستن... بچه می گه: توی چکمه هام بودن دیگه!\r\n"},{"id":854,"category_id":7,"category_code":"s7","source_id":24,"title":"آینه ی خیس","content":"در یکی از دانشگاه‌های تورنتو (کانادا) مد شده بود دخترها وقتی می‌رفتند توی دستشویی، بعد از آرایش کردن آینه را می‌بوسیدن تا جای رژ لبشون روی آینه دستشویی بمونه. مستخدم بی چاره از بس جای رژ لب پاک کرده بود خسته شده بود. برای همین، موضوع را با رئیس دانشگاه در میان گذاشت. فردای آن روز رئیس دانشگاه تمام دخترها را جمع کرد جلوی دستشویی و گفت: کسانی که این کار را می‌کنند خیلی برای مستخدم ایجاد زحمت می‌کنند. حالا برای این که شما ببینید پاک کردن جای رژ لب چه قدر سخته، مستخدم یک بار جلوی شما آینه را پاک می‌کنه. مستخدم با آرامش کامل رفت دستمال رو فرو کرد توی آب توالت فرنگی، وقتی دستمال خیس شد، شروع کرد به پاک کردن آینه و از اون به بعد دیگه هیچ کس آینه‌ رو نبوسید!"},{"id":855,"category_id":7,"category_code":"s7","source_id":25,"title":"زبان الله اکبری","content":"یکی از دوستانم تعریف می کرد: مامانم موقع نماز خواندن عادت داره به زبون الله اکبری با ما مکالمه کنه! یعنی این که وسطِ نماز، هر الله اکبر بلندی که می گه، یه منظوری داره! اون موقع است که ما هی چک می کنیم ببینیم منظورش چیه! یه روز وسط نماز یه الله اکبر کشداری گفت!\r\nمنم مثل فشنگ از جام پریدم و زیر گاز رو چک کردم؛پشت در رو نگاه کردم که ببینم کسی در نزده باشه! چراغها رو چک کردم مبادا یکی روشن مونده باشه! چیزی پیدا نکردم به مامانم نگاه کردم دیدم داره هی با چشم و ابروش واسه من ناز می کنه! آخر که دید من نفهمیدم یه اخمی کرد و یه الله اکبر شدید و بی خیال شد! وقتی نمازش تموم شد با عصبانیت برگشت گفت: واقعا که خری! مگه کوری؟ نمی بینی گرممه؟ یه ساعته می گم کولر رو روشن کن؟!\r\n"},{"id":856,"category_id":7,"category_code":"s7","source_id":26,"title":"سوال و جواب ","content":"یکی از دوستان اصفهانی من پاسخ هیچ پرسشی را نمی‌دهد و در پاسخ هر پرسش شما، او پرسشی از شما دارد! مثال: وقتی از او آدرس یک خیاط را می‌پرسید... شما: خیاط خوب سراغ داری؟ دوست اصفهانی: چی‌چی می‌خَی بدوزی؟ شما: کت و شلوار دوست اصفهانی: پارچه داری؟شما: بله دوست اصفهانی: از کی اِسِدی؟ شما: از ... مغازه. دوست اصفهانی: پارچِد خُبِس؟ شما: بله.\r\nدوست اصفهانی: چه رنگیس؟ شما: چه فرقی می‌کنه؟ دوست اصفهانی: فرق می‌کونِد دادا! فرق می‌کونِد. شما: خب، سورمه‌ای. دوست اصفهانی: چرا سورمه ی؟ ارزونتر بود؟شما: نه.دوست اصفهانی: چیطو؟شما: خب می خواستم سورمه ای باشه.دوست اصفهانی: مبارکس، خَبِریه؟شما: نه بابا، بالاخره خیاط سراغ داری یا نه؟دوست اصفهانی: اگه خبری نیس، کتا شلواری سورمِی می‌خَی چی کار؟\r\n"},{"id":857,"category_id":7,"category_code":"s7","source_id":27,"title":"دوچرخه سوار ","content":"مردی با دوچرخه به خط مرزی می رسد، او دو کیسه بزرگ همراه خود دارد، مامور مرزی می پرسد: \"در کیسه ها چه داری؟\" او می گوید:\"شن\"مامور او را از دوچرخه پیاده می کند و چون به او مشکوک بود، یک شبانه روز او را بازداشت می کند، ولی پس از بازرسی فراوان، واقعاً جز شن چیز دیگری نمی یابد. بنابراین به او اجازه عبور می دهد. هفته بعد دوباره سر و کله همان شخص پیدا می شود و مشکوک بودن و بقیه ماجرا... این موضوع به مدت سه سال هر هفته یک بار تکرار می شود و پس از آن مرد دیگر در مرز دیده نمی شود.\r\nیک روز آن مامور در شهر او را می بیند و پس از سلام و احوال پرسی، به او می گوید: من هنوز هم به تو مشکوکم و می دانم که در کار قاچاق بودی، راستش را بگو چه چیزی را از مرز رد می کردی؟ قاچاقچی می گوید: دوچرخه! \r\nبعضی وقت ها موضوعات فرعی ما را به کلی از موضوعات اصلی غافل می کند!\r\n"},{"id":858,"category_id":7,"category_code":"s7","source_id":28,"title":"بلاد کفر ","content":"از هواپیما که پیاده شدند، مامان‌ رو نشوند کنار یکی از بوفه‌های تو سالن و رفت که ساکها رو تحویل بگیره. وقتی برمی‌گرده می‌بینه یه ظرف سالاد میوه رو میزه و مامان هم مشغول خوردن. مامان اصلا انگلیسی بلد نیست. قضیه رو که می‌پرسه مامان می‌گه: \"آقاهه اومد یه چیزهایی گفت، نفهمیدم، فکر کنم اسمم رو پرسید منم گفتم: فروغ‌ سادات\""},{"id":859,"category_id":7,"category_code":"s7","source_id":29,"title":"تصادف","content":"دوستی تعریف می کرد که صبح یک زمستان سرد که برف سنگینی هم آمده بود مجبور شدم به بروجرد بروم...\r\nهوا هنوز روشن نشده بود که به پل خرم آباد رسیدم... وسط پل به ناگاه به موتوری که چراغ موتورش هم روشن نبود برخوردم... به سمت راست گرفتم، موتوری هم به راست پیچید... چپ، موتوری هم چپ... خلاصه موتوری لیز خورد و به حفاظ پل خورد و خودش از روی موتور پرت شد توی رودخونه...  وحشت زده و ترسیده، ماشین رو نگه داشتم و با سرعت رفتم پایین ببینم چه بر سرش اومد ، دیدم گردن بیچاره ۱۸۰ درجه پیچیده... با محاسبات ساده پزشکی، با خودم گفتم حتما زنده نمونده...  مایوس و ناراحت، دستم را گذاشتم رو سرم و از گرفتاری پیش آماده اندوهگین بودم... در همین حال زیر چشمی هم نیگاش می کردم،...  باحیرت دیدم چشماش را باز کرد... گفتم این حقیقت نداره... رو کردم بهش و گفتم سالمی...؟  با عصبانیت گفت: \"په چونه مثل یابو رانندگی موکونی...؟ \" با خودم گفتم این دلنشین ترین فحشی بود که شنیده بودم... گفتم آقا تو رو خدا تکون نخور چون گردنت پیچیده.... یک دفعه بلند شد گفت: شی پیچیده؟ شی موی تو؟ هوا سرد بید کاپشنمه از جلو پوشیدم سینم سرما نخوره!\r\n"},{"id":860,"category_id":7,"category_code":"s7","source_id":30,"title":"ساعت چند است؟ ","content":"\r\nدر قطار مرد جوانی از همسفر سالمندش پرسید: ساعت چند است؟ از نگهبان بپرس؟\r\n می بخشید من قصد ناراحت کردن شما را نداشتم و... ببین جوان... اگر مودبانه جواب بدهم، سر صحبت را باز می کنی، از من می پرسی به کدام شهر می روم و خانه ام کجاست و چه کاره ام... وقتی بگویم چه کاره ام... خواهی گفت که هرگز محل زندگی مرا ندیده ای و من از روی ادب تو را به خانه ام دعوت می کنم در خانه ام دخترم را می بینی و عاشق او می شوی و از او خواستگاری می کنی... بگذار از همین حالا آب پاکی روی دستت بریزم وبگویم: من نمی گذارم دخترم با مردی ازدواج کند که از مال دنیا یک ساعت هم ندارد!\r\n"},{"id":861,"category_id":7,"category_code":"s7","source_id":31,"title":"شوهر فروشی","content":"یه استاد داشتیم هر سری می آمد سر کلاس به دخترا تیکه می انداخت. یه بار دخترا تصمیم می گیرن با اولین تیکه ای که انداخت از کلاس برن بیرون. قضیه به گوش استاد می رسه. جلسه بعد یه کم دیر میاد سر کلاس، می گه از انقلاب داشتم می آمدم دیدم یه صف طولانی از دخترا تشکیل شده رفتم جلو پرسیدم، گفتن با کارت دانشجویی شوهر می دن! دخترا پا می شن برن بیرون، استاده می گه کجا می رید؟ وقتش تموم شد، تا ساعت 10 بود!"},{"id":862,"category_id":7,"category_code":"s7","source_id":32,"title":"راننده ی انیشتین","content":"اینشتین برای رفتن به سخنرانی ها و تدریس در دانشگاه از راننده مورد اطمینان خود کمک می گرفت. راننده وی نه تنها ماشین او را هدایت می کرد بلکه همیشه در طول سخنرانی ها در میان شنوندگان حضور داشت بطوری که به مباحث اینشتین تسلط پیدا کرده بود! یک روز اینشتین در حالی که در راه دانشگاه بود با صدای بلند گفت که خیلی احساس خستگی می کند. راننده اش پیشنهاد داد که آنها جایشان را عوض کنند و او جای اینشتین سخنرانی کند چرا که اینشتین تنها در یک دانشگاه استاد بود و در دانشگاهی که سخنرانی داشت کسی او را نمی شناخت و طبعا نمی توانستند او را از راننده اصلی تشخیص دهند. اینشتین قبول کرد، اما در مورد این که اگر پس از سخنرانی سوالات سختی از وی بپرسند او چه می کند، کمی تردید داشت. به هر حال سخنرانی راننده به نحوی عالی انجام شد ولی تصور انیشتین درست از آب درآمد. دانشجویان در پایان سخنرانی شروع به مطرح کردن سوالات خود کردند. در این حین راننده باهوش گفت: سوالات به قدری ساده هستند که حتی راننده من نیز می تواند به آنها پاسخ دهد. سپس اینشتین از میان حضار برخاست و به راحتی به سوالات پاسخ داد به حدی که باعث شگفتی حضار شد!"},{"id":863,"category_id":7,"category_code":"s7","source_id":33,"title":"بی توجهی","content":"مردی از این که زنش به گربه خانه بیشتر از او توجه می کرد ناراحت بود، یک روز گربه را برد و چند تا خیابان آن طرف تر ول کر. ولی تا به خانه رسید، دید گربه زود تر از اون برگشته خونه، این کار چندین دفعه تکرار شد و مرد حسابی کلافه شده بود. بالاخره یک روز گربه را با ماشین گرداند، از چندین پل و رودخانه پارک و غیره گذشت و بالاخره گربه را در منطقه ای پرت و دور افتاده ول کرد. آن شب مرد به خانه بر نگشت... آخر شب زنگ زد و به زنش گفت: اون گربه کره خر خونه هست؟زنش گفت: آره. مرد گفت: گوشی رو بده بهش، من گم شدم!"},{"id":864,"category_id":7,"category_code":"s7","source_id":34,"title":"رماتیسم","content":"کشیشی در اتوبوس نشسته بود که یک ولگرد مست و لایعقل سوار شد و کنار او نشست. مردک روزنامه ای باز کرد و مشغول خواندن شد و بعد از مدتی هم از کشیش پرسید: \"پدر روحانی! روماتیسم از چی ایجاد می شود؟\"کشیش هم موعظه را شروع کرد و گفت: \"روماتیسم حاصل مستی و میگساری و بی بند و باری است.\"مردک با حالت منفعل دوباره سرش گرم روزنامه خودش شد. بعد کشیش از او پرسید تو حالا چند وقت است که روماتیسم داری؟ مردک گفت من روماتیسم ندارم. این جا نوشته است پاپ اعظم دچار روماتیسم بدی است!"},{"id":865,"category_id":7,"category_code":"s7","source_id":35,"title":"بسته ی بزرگ","content":"یک روز مردی در حال عبور از خیابان کودکی را مشغول جابجایی بسته ای دید که از خود کودک بزرگتر بود، پس به نزدیکش رفت و گفت: عزیزم بگذار تا کمکت کنم. مرد وقتی خواست بسته را بردارد دید که حتی حملش برای او مشکل است چه برسد به این بچّه.کمی که رفتند مرد از کودک پرسید چرا این بسته را حمل می کند؟کودک در پاسخ گفت: که پدرش از او خواسته است. مرد پرسید: چرا پدرت خودش این کار را انجام نداد؟ مگر نمی دانست که حمل این بسته برایت چقدر سخت است؟ کودک جواب داد: اتفاقا مادرم هم همین حرف را به پدرم زد ولی او گفت: \"خانم بالاخره یه خری پیدا می شه به این بچّه کمک کنه دیگه!\""},{"id":866,"category_id":7,"category_code":"s7","source_id":36,"title":"مسافر اتوبوس","content":"مایکل، راننده اتوبوس شهری، مثل همیشه اول صبح اتوبوسش را روشن کرد و در مسیر همیشگی شروع به کار کرد. در چند ایستگاه اول همه چیز مثل معمول بود و تعدادی مسافر پیاده می شدند و چند نفر هم سوار می شدند. در ایستگاه بعدی، یک مرد با هیکل بزرگ، قیافه ای خشن و رفتاری عجیب سوار شد او در حالی که به مایکل زل زده بود گفت: «تام هیکل پولی نمی ده!» و رفت و نشست.\r\nمایکل که تقریباً ریز جثه بود و اساساً آدم ملایمی بود چیزی نگفت اما راضی هم نبود.\r\n روز بعد هم دوباره همین اتفاق افتاد و مرد هیکلی سوار شد و با گفتن همان جمله، رفت و روی صندلی نشست و روز بعد و روز بعد...\r\nاین اتفاق که به کابوسی برای مایکل تبدیل شده بود خیلی او را آزار می داد. بعد از مدتی مایکل دیگر نمی تواست این موضوع را تحمل کند و باید با او برخورد می کرد. اما چطوری از پس آن هیکل بر می آمد؟ بنابراین در چند کلاس بدنسازی، کاراته و جودو و... ثبت نام کرد. در پایان تابستان، مایکل به اندازه کافی آماده شده بود و اعتماد به نفس لازم را هم پیدا کرده بود. بنابراین روز بعدی که مرد هیکلی سوار اتوبوس شد و گفت: «تام هیکل پولی نمی ده!» مایکل ایستاد، به او زل زد و فریاد زد: «برای چی؟» مرد هیکلی با چهره ای متعجب و ترسان گفت: تام هیکل کارت استفاده رایگان داره!\r\n"},{"id":867,"category_id":7,"category_code":"s7","source_id":37,"title":"آینده ی خطرناک","content":"کشیشى یک پسر نوجوان داشت و کم‌کم وقتش رسیده بود که فکرى در مورد شغل آینده‌اش بکند. پسر هم مثل تقریباً بقیه هم‌سن و سالانش واقعاً نمی‌دانست که چه چیزى از زندگى می‌خواهد و ظاهراً خیلى هم این موضوع برایش اهمیت نداشت. یک روز که پسر به مدرسه رفته بود، پدرش تصمیم گرفت آزمایشى براى او ترتیب دهد. به اتاق پسرش رفت و سه چیز را روى میز او قرار داد: یک کتاب مقدس، \r\nیک سکه طلا و یک بطرى مشروب.کشیش پیش خود گفت: «من پشت در پنهان می‌شوم تا پسرم از مدرسه برگردد و به اتاقش بیاید. آنگاه خواهم دید کدام یک از این سه چیز را از روى میز بر می‌دارد. اگر کتاب مقدس را بردارد معنیش این است که مثل خودم کشیش خواهد شد که این خیلى عالیست. اگر سکه را بردارد یعنى دنبال کسب و کار خواهد رفت که آن هم بد نیست. امّا اگر بطرى مشروب را بردارد، یعنى آدم دائم‌الخمر و به درد نخوری خواهد شد که جاى شرمسارى دارد.» مدتى نگذشت که پسر از مدرسه بازگشت. در خانه را باز کرد و در حالى که سوت می‌زد کاپشن و کفشش را به گوشه‌اى پرت کرد و یک راست راهى اتاقش شد. کیفش را روى تخت انداخت و در حالى که می‌خواست از اتاق خارج شود چشمش به اشیاء روى میز افتاد. با کنجکاوى به میز نزدیک شد و آن‌ها را از نظر گذراند.\r\nکارى که نهایتاً کرد این بود که کتاب مقدس را برداشت و آن را زیر بغل زد. سکه طلا را توى جیبش انداخت و در بطرى مشروب را باز کرد و یک جرعه بزرگ از آن خورد... کشیش که از پشت در ناظر این ماجرا بود زیر لب گفت:\r\n«! خداى من! چه فاجعه بزرگی! پسرم سیاستمدار خواهد شد »\r\n"},{"id":868,"category_id":7,"category_code":"s7","source_id":38,"title":"موسسه ی خیریه ","content":"مسئولین یک مؤسسه خیریه متوجه شدند که وکیل پولداری در شهرشان زندگی می‌کند و تاکنون حتی یک ریال هم به خیریه کمک نکرده است.پس یکی از افرادشان را نزد او فرستادند. مسئول خیریه: آقای وکیل ما در مورد شما تحقیق کردیم و متوجه شدیم که الحمدالله از درآمد بسیار خوبی برخوردارید ولی تا کنون هیچ کمکی به خیریه نکرده‌اید. نمی‌خواهید در این امر خیر شرکت کنید؟\r\nوکیل: آیا شما در تحقیقاتی که در مورد من کردید متوجه شدید که مادرم بعد از یک بیماری طولانی سه ساله، هفته پیش درگذشت و در طول آن سه سال، حقوق بازنشستگی‌اش کفاف مخارج سنگین درمانش را نمی‌کرد؟\r\nمسئول خیریه: (با کمی شرمندگی) نه، نمی‌دانستم. خیلی تسلیت می‌گویم.\r\nوکیل: آیا در تحقیقاتی که در مورد من کردید فهمیدید که برادرم در جنگ هر دو پایش را از دست داده و دیگر نمی‌تواند کار کند و زن و 5 بچه دارد و سالهاست که خانه نشین است و نمی‌تواند از پس مخارج زندگیش برآید؟\r\nمسئول خیریه: (با شرمندگی بیشتر) نه، نمی‌دانستم. چه گرفتاری بزرگی.\r\nوکیل: آیا در تحقیقاتتان متوجه شدید که خواهرم سال هاست که در یک بیمارستان روانی است و چون بیمه نیست در تنگنای شدیدی برای تأمین هزینه‌های درمانش قرار دارد؟\r\nمسئول خیریه که کاملاً شرمنده شده بود گفت: ببخشید. نمی‌دانستم این همه گرفتاری دارید...\r\nوکیل: خوب. حالا وقتی من به این ها یک ریال کمک نکرده‌ام، شما چه طور انتظار دارید به خیریه شما کمک کنم؟\r\n"},{"id":869,"category_id":7,"category_code":"s7","source_id":39,"title":"دو پرنده ی عاشق ","content":"زوج خوشبخت و موفقی را در این دنیای مجازی می‌شناسم که مدتهاست بدون کوچکترین مشکلی، زندگی‌شان ادامه دارد و هیچ‌ وقت هم با هم دعوا و بزن‌بزن نمی‌کنند! یک روز از این زوج موفق سوال کردم: دلیل موفقیت شما در چیست؟ چرا هیچ وقت با هم دعوا نمی‌کنید؟\r\nآقاهه پاسخ داد: ببین ‌جانم! من و خانمم از روز اول، حد و حدود خودمان را مشخص کردیم و قرار شد خانم بنده، فقط در مورد مسائل جزئی حق اظهار نظر داشته باشه و من هم به عنوان یک آقا، فقط در مورد مسائل کلی نظر بدهم!\r\nگفتم: چه خوب! آفرین! زنده‌باد رفیق! تو آبروی همه‌ی ما مردها را خریده‌ای! من بهت افتخار می‌کنم. حالا این مسائل جزئی که خانمت در مورد اون‌ها حق اظهار نظر داره، چی هست؟\r\nآقاهه گفت: از روز اول قرار شد خانم بنده فقط در مورد مسائل جزئی نظر بده و تصمیم بگیره، مسائل بی‌اهمیتی مثل این که ما چند تا بچه داشته باشیم، کجا زندگی کنیم، کی خانه بخریم، ماشین‌مان چه باشد، چی بخوریم، چی بپوشیم و با کی رفت‌و‌آمد کنیم...\r\nگفتم: اِ!!! من که رسما هنگ کردم رفیق! پس اون مسائل کلی که تو در موردش نظر می‌دی، چی‌ هست؟\r\nآقاهه گفت: من در مورد مسائل کلان بین المللی، نوسانات دلار، قیمت نفت و اوضاع جاری مملکت نظر می‌دهم!\r\n"},{"id":870,"category_id":7,"category_code":"s7","source_id":40,"title":"پرنده فروشی ","content":"مردی به یک مغازه فروش حیوانات رفت و درخواست یک طوطی کرد. صاحب فروشگاه به سه طوطی خوش چهره اشاره کرد و گفت: «طوطی سمت چپ ۵۰۰ دلار است.»مشتری: «چرا این طوطی این قدر گران است؟» صاحب فروشگاه: «این طوطی توانایی انجام تحقیقات علمی و فنی را دارد.» مشتری: قیمت طوطی وسطی چقدر است؟‌»\r\nصاحب فروشگاه: طوطی وسطی ۱۰۰۰ دلار است. برای این که این طوطی توانایی نوشتن مقاله ای که در هر مسابقه ای پیروز شود را دارد. \r\nو سرانجام مشتری از طوطی سوم پرسید و صاحب فروشگاه گفت: «‌ ۴۰۰۰ دلار.»مشتری: این طوطی چه کاری می تواند انجام دهد؟\r\nصاحب فروشگاه جواب داد: صادقانه بگویم، من چیز خاصی از این طوطی ندیدم، ولی دو طوطی دیگر او را مدیر صدا می زنند!\r\n"},{"id":871,"category_id":7,"category_code":"s7","source_id":41,"title":"مدیر لایق ","content":"روزی مدیر یکی از شرکت های بزرگ در حالی که به سمت دفتر کارش می رفت چشمش به جوانی افتاد که در راهرو ایستاده بود و به اطراف خود نگاه می کند.جلو رفت و از او پرسید: «شما ماهانه چقدر حقوق دریافت می‌کنی؟»جوان با تعجب جواب داد:‌ ماهی 2000 دلار.\r\nمدیر با نگاهی آشفته دست به جیب شد و از کیف پول خود 6000 دلار بیرون آورد و به جوان داد و به او گفت: «این حقوق سه ماه تو، برو و دیگر این جا پیدایت نشود، تو اخراجی! ما به کارمندان خود حقوق می‌دهیم که کار کنند، نه این که یک جا بایستند و بی کار به اطراف نگاه کنند.» جوان با خوشحالی از جا جهید و به سرعت دور شد. مدیر از کارمند دیگری که در نزدیکیش بود پرسید: «آن جوان کارمند کدام قسمت بود؟»کارمند با تعجب از رفتار مدیر، به او جواب داد: او پیک پیتزا فروشی بود که برای کارکنان پیتزا آورده بود.\r\n"},{"id":872,"category_id":7,"category_code":"s7","source_id":42,"title":"یادم نمی آید!","content":"از یک استاد سخنور دعوت به عمل آمد که در جمع مدیران ارشد یک سازمان ایراد سخن نماید. محور سخنرانی در خصوص مسائل انگیزشی و چگونگی ارتقاء سطح روحیه کارکنان دور می زد. استاد شروع به سخن نمود و پس از مدتی که توجه حضار کاملا به گفته هایش جلب شده بود، چنین گفت: \"آری دوستان، من بهترین سالهای زندگی را در آغوش زنی گذراندم که همسرم نبود!\" ناگهان سکوت شوک برانگیزی جمع حضار را فرا گرفت! استاد وقتی تعجب آنان را دید، پس از کمی مکث ادامه داد: \"آن زن، مادرم بود!\" حاضران شروع به خندیدن کردند و استاد سخنان خود را ادامه داد...تقریبا یک هفته از آن قضیه گذشت تا این که یکی از مدیران ارشد همان سازمان به همراه همسرش به یک میهمانی نیمه رسمی دعوت شد. آن مدیر از جمله افراد پرکار و تلاشگر سازمان بود که همیشه سرش شلوغ بود. او خواست که خودی نشان داده و در جمع دوستان و آشنایان با بازگو کردن همان لطیفه، محفل را بیشتر گرم کند. لذا با صدای بلند گفت: \"آری، من بهترین سالهای زندگی خود را در آغوش زنی گذرانده ام که همسرم نبود!\"همان طور که انتظار می رفت سکوت توام با شک همه را فرا گرفت و طبیعتا همسرش نیز در اوج خشم و حسادت به سر می برد. مدیر که وقت را مناسب دید،‌ خواست لطیفه را ادامه دهد، اما از بد حادثه، چیزی به خاطرش نیامد و هر چه زمان گذشت، سوءظن میهمانان نسبت به او بیشتر شد، تا اینکه به ناچار گفت: \"راستش دوستان، هر چه فکر می کنم، نمی تونم به خاطر بیارم آن خانم که بود!\""},{"id":873,"category_id":7,"category_code":"s7","source_id":43,"title":"اسکناس","content":"\r\n                 چرچيل (نخست وزير سابق بريتانيا) روزی سوار تاکسی شده بود و به دفتر بی بی سی برای مصاحبه میرفت. هنگامی که به آن جا رسيد به راننده تاکسی گفت آقا لطفاً نيم ساعت صبر کنيد تا من برگردم. راننده گفت: \"نه آقا! من می خواهم سريعاً به خانه بروم تا سخنرانی چرچيل را از راديو گوش دهم.\" چرچيل از علاقه ی اين فرد به خودش خوشحال و ذوق زده شد و يک اسکناس ده پوندی به او داد. راننده تاکسی با ديدن اسکناس گفت: \"گور بابای چرچيل! اگر بخواهيد، تا فردا هم اينجا منتظر می مانم!\"\r\n"},{"id":874,"category_id":7,"category_code":"s7","source_id":44,"title":"مشاوره","content":"\r\nجانی ساعت ۲ از محل کارش خارج شد و چون نیم ساعت وقت داشت تا به محل کار دوستش برود، تصمیم گرفت با همان یک دلاری که در جیب داشت ناهار ارزان قیمتی بخورد و راهی شرکت شود. چند رستوران گران قیمت را رد کرد تا به رستورانی رسید که روی در آن نوشته شده بود: ”ناهار همراه نوشیدنی فقط یک دلار”. جانی معطل نکرد، داخل رستوران شد و یک پرس اسپاگتی و یک نوشابه برداشت و سر میز نشست.گارسون برایش دو نوع سوپ، سالاد، سیب زمینی سرخ کرده، نوشابه اضافه، بستنی و دو نوع دسر آورد و به اعتراض جانی توجهی نکرد که گفت: ”ولی من این غذاها رو سفارش ندادم.” گارسون که رفت جانی شانه ای بالا انداخت و گفت: ”خودشان می فهمند که من نخوردم!\"\r\nاما جانی موقعی فهمید که این شیوه آن رستوران برای کلاهبرداری است که رفت جلو صندوق و متصدی رستوران پول همه غذاها رو حساب کرد و گفت ۱۵ دلار و ۱۰ سنت. جانی معترض شد: ”ولی من هیچ کدوم رو نخوردم!” و مرد پاسخ داد ”ما آوردیم، می خواستین بخورین!\"\r\nجانی که خودش ختم زرنگ های روزگار بود، سری تکان داد و یک سکه ۱۰ سنتی روی پیشخوان گذاشت و وقتی متصدی اعتراض کرد، گفت: ”من مشاوری هستم که بابت یک ساعت مشاوره ۱۵ دلار می گیرم.” متصدی گفت: ”ولی ما که مشاوره نخواستیم!” و جانی پاسخ داد: ”من که اینجا بودم! می خواستین مشاوره بگیرین!” و سپس به آرامی از آنجا خارج شد.\r\n"},{"id":875,"category_id":7,"category_code":"s7","source_id":45,"title":"استخدام ","content":"در پایان مصاحبه شغلی برای استخدام در شرکتی، مدیر منابع انسانی شرکت از مهندس جوان صفر کیلومتر ام آی تی پرسید: «برای شروع کار، حقوق مورد انتظار شما چیست؟» مهندس گفت: «حدود 75000 دلار در سال، بسته به اینکه چه مزایایی داده شود.» مدیر منابع انسانی گفت: «خوب، نظر شما درباره 5 هفته تعطیلی، 14 روز تعطیلی با حقوق، بیمه کامل درمانی و حقوق بازنشستگی ویژه و خودروی شیک و مدل بالا چیست؟» مهندس جوان از جا پرید و با تعجب پرسید: «شوخی می‌کنید؟» مدیر منابع انسانی گفت: بله، اما یادت باشه اول تو شروع کردی!"},{"id":876,"category_id":7,"category_code":"s7","source_id":46,"title":"چاق و لاغر","content":"روزی در یک میهمانی مرد خیلی چاقی سراغ برنارد شاو که بسیار لاغر بود رفت و گفت: آقای شاو! وقتی من شما را می بینم فکر می کنم در اروپا قحطی افتاده است! برنارد شاو هم سریع جواب می دهد: بله! من هم هر وقت شما را می بینم فکر می کنم عامل این قحطی شما هستید! روزی نویسنده جوانی از جرج برنارد شاو پرسید: «شما برای چه می نویسید استاد؟» برنارد شاو جواب داد: «برای یک لقمه نان»نویسنده جوان بر آشفت که: متاسفم! بر خلاف شما من برای فرهنگ می نویسم!\r\nو برنارد شاو گفت: عیبی نداره پسرم، هر کدام از ما برای چیزی می نویسیم که نداریم!\r\n"},{"id":877,"category_id":7,"category_code":"s7","source_id":47,"title":"پاسگاه مرزی","content":"می گویند در دوران قبل که پاسگاه های ژاندارمری در مناطق مرزی و روستایی و دور از شهرها وجود داشته و اکثرا ماموران مستقر در آنها از نقاط دیگر برای خدمت منتقل می شدند باید مدت زیادی را دور از اقوام و بستگان سپری می کردند. کما اینکه سفر و رفت و آمد به سهولت فعلی نبوده. شاید بعضی مواقع حتی در طول سال هم امکانی برای مسافرت ماموران به شهر موطن خود پیش نمی آمد و به همین خاطر تعداد معدودی خانه سازمانی در اختیار فرمانده پاسگاه و برخی ماموران دیگر قرار می گرفت. همسر یکی از فرماندهان پاسگاه که به تازگی هم ازدواج کرده و چندین ماه از زندگیشان دور از شهر و بستگان در منطقه خدمت همسرش می گذشت بدجوری دلتنگ خانواده پدری اش شده بود. چندین بار از شوهرش درخواست می کند که برای دیدن پدر و مادرش به شهرشان به اتفاق هم یا به تنهایی مسافرت کند ولی هر بار شوهرش به بهانه ای از زیر بار موضوع شانه خالی می کند. زن که در این مدت با چگونگی برخورد ماموران زیر دست شوهرش و بعضا مکاتبات آنها برای گرفتن مرخصی و غیره هم کم و بیش آشنا شده بود به فکر می افتد حالا که همسرش برای خواسته وی اهمیتی قائل نمی شود، او هم به صورت مکتوب و به مانند ماموران برای رفتن و دیدن خانواده اش درخواست مرخصی بکند، پس دست به کار شده و در کاغذی درخواست کتبی به این شرح می نویسد: \"جناب ..... فرمانده محترم ..... اینجانب ..... همسر حضرتعالی که مدت چندین ماه است پس از ازدواج با شما دور از خانواده و بستگان خود هستم، حال که شما به دلیل مشغله بیش از حد کاری فرصت سفر و دیدار بستگان را ندارید بدین وسیله درخواست دارم که با مرخصی اینجانب به مدت ..... برای مسافرت و دیدن پدر و مادر و اقوام موافقت فرمائید. با احترام، همسر شما .....\" و نامه را در پوشه مکاتبات همسرش می گذارد. چند روز بعد جواب نامه به این مضمون بدستش می رسد: \"سرکار خانم..... عطف به درخواست مرخصی سرکار عالی جهت سفر برای دیدار اقوام با درخواست شما به شرط تامین جانشین موافقت می شود.\r\nفرمانده...\"\r\n"},{"id":878,"category_id":7,"category_code":"s7","source_id":48,"title":"خوراک جگر ","content":"اولین باری که برای بچه ها خوراک جگر درست کردم هیچ وقت یادم نمی ره... غذا رو کشیدم و بچه ها و شوهرم را برای خوردن شام صدا زدم، پسر کوچکم غذا را بو کرد و اخم هایش رفت توی هم... دخترم هم با غذایش بازی بازی می کرد ولی حاضر نبود لب بزنه. به بچه ها گفتم: \"ممکنه بوی خوبی نده اما خیلی خوشمزه است، یه کوچولو امتحان کنید... اصلا می دونید اسم این غذا چیه؟ یه راهنمایی می کنم بهتون... باباتون گاهی منو به همین اسم صدا می زنه.\"  ناگهان چشمهای دخترم گشاد شد، به برادرش سقلمه زد و گفت: \r\n\"نخور! نخور! تاپاله است!\r\n"},{"id":879,"category_id":7,"category_code":"s7","source_id":49,"title":"اسب سخنگو ","content":"یه روزی یه مرده نشسته بوده و داشته روزنامه اش رو می خونده كه زنش یهو ماهی تابه رو می كوبه تو سرش!\r\nمرده می گه: برا چی این كار رو كردی؟ زنش جواب می ده: به خاطر این زدمت كه تو جیب شلوارت یه تكه كاغذ پیدا كردم كه توش اسم جنى (یه دختر) نوشته شده بود… مرده می گه: وقتی هفته پیش برای تماشای مسابقه اسب دوانی رفته بودم اسبی كه روش شرط بندی كردم اسمش جنی بود. زنش معذرت خواهی می کنه و می ره به کارای خونه برسه.\r\nسه روز بعد، مرد داشت تلویزین تماشا می كرد كه زنش این بار با یه قابلمه ی بزرگتر می كوبه تو سرش به طوری که مرده تقریبا بیهوش می شه. مرد وقتی به خودش میاد می پرسه این بار برای چی منو زدی؟ زنش جواب می ده: آخه اسبت زنگ زده بود!\r\n"},{"id":880,"category_id":7,"category_code":"s7","source_id":50,"title":"فلان کس","content":"چند شب پیش در میان مریض ها منشی ام وارد شد و گفت یک آقایی که ماهی بزرگی در دست دارد آمده است و می خواهد شما را ملاقات کند...\r\nمرد میانسالی با لهجه شدید رشتی وارد شد و در حالی که یک ماهی حدودا ده کیلویی در یک کیسه نایلون بزرگ در دست داشت، شروع کرد به تشکر کردن که من عموی فلان کس هستم و شما جان او را نجات دادی و خلاصه این ماهی تحفه ناقابلی است و...\r\nهر چه فکر کردم \"فلان کس\" را به یاد نیاوردم ولی ماهی را گرفتم و از او تشکر کردم. شب ماهی را به خانه بردم و زنم شروع به غرغر کرد که من ماهی پاک نمی کنم! خودم تا نصف شب نشستم و ماهی را تمیز کردم و قطعه قطعه نموده و در فریزر گذاشتم. فردا عصر وارد مطب که شدم دیدم همان مرد رشتی ایستاده است و بسیار مضطرب است. تا مرا دید به طرفم دوید و گفت آقای دکتر دستم به دامنت... ماهی را پس بده... من باید این ماهی را به فلان دکتر بدهم اشتباهی به شما دادم.... چرا شما به من نگفتی که آن دکتر نیستی و برادرزاده مرا نمی شناسی؟\r\nمن که در سالن و جلوی سایر بیماران یکه خورده بودم با دستپاچگی گفتم که ماهی ات الآن در فریزر خانه ماست.\r\nاو هم با ناراحتی گفت: پس پولش را بدهید تا برای دکترش یک ماهی دیگر بخرم و من با شرمساری هفتاد هزار تومان به او پرداختم.\r\nچند روز بعد متوجه شدم که ماجرای مشابهی برای تعدادی از همکارانم رخ داده است و ظاهرا آن مرد رشتی یک وانت ماهی به اصفهان آورده و به پزشکان اصفهانی انداخته است!\r\n"},{"id":881,"category_id":7,"category_code":"s7","source_id":51,"title":"فرشته ی مهربانی","content":"مرد داشت در خیابان حرکت می کرد که ناگهان صدایی از پشت گفت:  اگر یک قدم دیگه جلو بری کشته می شی. \r\nمرد ایستاد و در همان لجظه اجری از بالا افتاد جلوی پاش.مرد نفس راحتی کشید و با تعجب دوروبرشو نگاه کرد اما کسی رو ندید.بهر حال نجات پیدا کرده بود. به راهش ادامه داد.به محض اینکه می خواست از خیابان رد بشه باز همان صدا گفت: ایست!\r\nمرد ایستاد و در همان لحظه ماشینی با سرعت عجیبی از جلویش رد شد.بازم نجات پیدا کرد.مرد پرسید تو کی هستی و صدا جواب داد م فرشته نگهبان ت هستم. مرد فکری کرد و گفت: پس اون موقعی که من داشتم ازدواج می کردم تو کدوم گوری بودی؟\r\n"},{"id":882,"category_id":7,"category_code":"s7","source_id":52,"title":" بازاریابی","content":"در دانشگاه استنفورد، استاد در حال شرح دادن مفهموم بازاریابی به دانشجویان خود بود \r\nشما در یک مهمانی، یک دختر بسیار زیبا رو می بینین و ازش خوشتون میاد، بلافاصله میرین پیشش و می گین: \"من پسر ثروتمندی هستم، با من ازدواج کن\"، به این میگن بازاریابی مستقیم شما در یک مهمانی به همراه دوستانتون\r\nیک دختر بسیار زیبا رو می بینین و ازش خوشتون میاد، بلافاصله یکی از دوستاتون میره پیش دختره،به شما اشاره می کنه و می گه: “اون پسر ثروتمندیه، باهاش ازدواج کن\"، به این می گن تبلیغات شما در یک مهمانی، یک دختر بسیار زیبا رو می بینین و ازش خوشتون میاد، بلافاصله میرین پیشش و شماره تلفنش رو می گیرین، فردا باهاش تماس می گیرین و می گین: \"من پسر ثروتمندی هستم، با من ازدواج کن\"، به این میگن بازاریابی تلفنی \r\nشما در یک مهمانی، یک دختر بسیار زیبا رو می بینین و ازش خوشتون میاد، بلافاصله کراواتتون رو مرتب می کنین و میرین پیشش ، اون رو به یک نوشیدنی دعوت می کنیین، وقتی کیفش می افته براش از روی زمین بلند می کنین، در آخر هم براش درب ماشین رو باز می کنین و اون رو به یک سواری کوتاه دعوت می کنین و میگین: “در هر حال،من پسر ثروتمندی هستم، با من ازدواج می کنی؟”، به این میگن روابط عمومی\r\nشما در یک مهمانی، یک دختر بسیار زیبا رو می بینین که داره به سمت شما میاد و میگه: \"شما پسر ثروتمندی هستی، با من ازدواج می کنی؟”، به این می گن شناسایی علامت تجاری شما توسط مشتری\r\nشما در یک مهمانی، یک دختر بسیار زیبا رو می بینین و ازش خوشتون میاد، بلافاصله میرین پیشش و می گین: \"من پسر ثروتمندی هستم، با من ازدواج کن\"، بلافاصله اون هم یک سیلی جانانه نثار شما می کنه، به این میگن پس زدگی توسط مشتری\r\nشما در یک مهمانی، یک دختر بسیار زیبا رو می بینین و ازش خوشتون میاد، بلافاصله میرین پیشش و می گین: \"من پسر ثروتمندی هستم، با من ازدواج کن”و اون بلافاصله شما رو به همسرش معرفی می کنه، به این می گن شکاف بین عرضه و تقاضا\r\nشما در یک مهمانی، یک دختر بسیار زیبا رو می بینین و ازش خوشتون میاد، ولی قبل از این که حرفی بزنین، شخص دیگه ای پیدا می شه و به دختره میگه: \"من پسر ثروتمندی هستم، با من ازدواج کن”به این میگن از بین رفتن سهم توسط رقبا\r\nشما در یک مهمانی، یک دختر بسیار زیبا رو می بینین و ازش خوشتون میاد، ولی قبل از این که بگین: \"من پسر ثروتمندی هستم، با من ازدواج کن \"، همسرتون پیداش میشه، به این میگن منع ورود به بازار\r\n"},{"id":883,"category_id":7,"category_code":"s7","source_id":53,"title":"مشک ","content":"در کتاب انسان بی خود دکتر شریعتی آمده است: چند نفر به کره مریخ رفتند و دیدند که علمای کره مریخ کنفرانسی دارند که در آن یک نفر راجع به آخرین فضانوردانشان که از زمین برگشته بودند کنفرانس می دهد که در زمین چه خبر است. بعد، آن آقای فضاشناس می گفت که آخرین تحقیقات به این نتیجه رسیده است که در کره زمین حیات وجود دارد و موجوداتی که شعور و درک دارند، به نام انسان، در آن وجود دارند؛ اما شما تصوری از انسان ندارید و بنده برایتان توضیح می دهم: یک خیک یا مشک است و چهار دستک دارد. این خیک یا مشک، با این دستک هایش روی زمین حرکت می کند و تلاش می کند و پیوسته تکثیر هم می شود! مشاهده شده که همیشه به جان هم می پرند، همدیگر را آتش می زنند، پوست می کنند، می زنند، می کشند... تمام این کارها را هم برای این است که بیشتر بخورند و پیوسته این مشک را پر می کنند. اما کار عجیبی که ما هنوز نفهمیده ایم چیست، این است که این ها غذاهای سالم و میوه های شاداب و گل های بسیار لطیف و همه ادویه طبیعی را که طبیعت در اختیارشان گذاشته، و این همه تلاش، آدم کشی و جنایت را برای به دست آوردن آن ها می کنند، نمی خورند! بلکه آن ها را به خانه می آورند، بعد آن ها را توی آب می ریزند و همه را به هم مخلوط می کنند، بعد آن ها را نمک می زنند، بعد فلفل، بعد روغن؛ بعد مواد دیگری به آن می زنند، بعد می جوشانند، بعد می سو زانند! بعد می خورند. بعد مریض می شوند. بعد به عده ای دکتر پول می دهند و التماس می کنند تا به زور با دوا و تنِقیه و گریه و زاری آن ها را از توی مشک بیرون بیاورد و جان مشک را نجات دهد!"},{"id":884,"category_id":7,"category_code":"s7","source_id":54,"title":"انتخاب نهایی","content":"سازمان بهداشت جهانی برای آزمایش یک واکسن خطرناک وجدید احتیاج یه داوطلب داشت. از میان مراجعین فقط سه نفر واجد شرایط اعلام شدند: یک آلمانی ،یک فرانسوی و یک ایرانی قرار شد با تک تک آنان مصاحبه شود برای انتخاب نهایی مصاحبه از آلمانی پرسید: برای این کار چقدر پول میخواهید؟\r\nاو گفت من صد هزار دلار، این را میدهم به زنم که اگر از این واکسن مردم یا فلج شدم، زنم بی پول نماند. مصاحبه گر او را مرخص کرد وهمین سوال را از فرانسوی نمود. او گفت من دویست هزار دلار میگیرم، صدهزار تا برای زنم و صد هزار تا برای معشوقه ام. وفتی او هم رفت، ایرانی گفت من سیصد هزار دلار می خواهم.صد هزار برای خودم صد هزار تا هم حق حساب شما صد هزار تاش هم میدیم به آلمانی که واکسن را بهش بزنیم!!\r\n"},{"id":885,"category_id":7,"category_code":"s7","source_id":55,"title":"هیزم شکن ","content":"روزی، وقتی هیزم شکنی مشغول قطع کردن یه شاخه درخت بالای رودخونه بود، تبرش افتاد تو رودخونه. وقتی در حال گریه کردن بود، یه فرشته اومد و ازش پرسید: چرا گریه می کنی؟ هیزم شکن گفت که تبرم توی رودخونه افتاده. فرشته رفت و با یه تبر طلایی برگشت.\r\n\"آیا این تبر توست؟\" هیزم شکن جواب داد: \" نه\" فرشته دوباره به زیر آب رفت و این بار با یه تبر نقره ای برگشت و پرسید که آیا این تبر توست؟ دوباره، هیزم شکن جواب داد : نه. فرشته باز هم به زیر آب رفت و این بار با یه تبر آهنی برگشت و پرسید آیا این تبر توست؟ جواب داد: آره\r\nفرشته از صداقت مرد خوشحال شد و هر سه تبر را به اوداد و هیزم شکن خوشحال روانه خونه شد. یه روز وقتی داشت با زنش کنار رودخونه راه می رفت زنش افتاد توی آب. هیزم شکن داشت گریه می کرد که فرشته باز هم اومد و پرسید که چرا گریه می کنی؟ اوه فرشته، زنم افتاده توی آب.\r\nفرشته رفت زیر آب و با جنیفر لوپز برگشت و پرسید : زنت اینه؟ هیزم شکن فریاد زد: آره! فرشته عصبانی شد. \" تو تقلب کردی، این نامردیه\" \r\nهیزم شکن جواب داد : اوه، فرشته من منو ببخش. سوء تفاهم شده. می دونی، اگه به جنیفر لوپز \"نه\" می گفتم تو می رفتی و با کاترین زتاجونز می اومدی. و باز هم اگه به کاترین زتاجونز \"نه\" میگفتم، تو می رفتی و با زن خودم می اومدی و من هم می گفتم آره. اونوقت تو هر سه تا رو به من می دادی. اما فرشته، من یه آدم فقیرم و توانایی نگهداری سه تا زنرو ندارم، و به همین دلیل بود که این بار گفتم آره.\r\n"},{"id":886,"category_id":7,"category_code":"s7","source_id":56,"title":"دوستان قدیمی ","content":"دو پیرمرد 90\r\nساله، به نامهاى بهمن و خسرو، دوستان بسیار قدیمى بودند.\r\nهنگامى که بهمن در بستر مرگ بود، خسرو هر روز به دیدار او می رفت. یک روز خسرو گفت: «بهمن جان، ما هر دو عاشق فوتبال بودیم و سالهاى سال با هم فوتبال بازى می کردیم. لطفاً وقتى به بهشت رفتى، یک جورى به من خبر بوده که در آن جا هم می شود فوتبال بازى کرد یا نه؟» بهمن گفت: «خسرو جان، تو بهترین دوست زندگى من هستى. مطمئن باش اگر امکانش بود حتماً بهت خبر می دهم.» چند روز بعد بهمن از دنیا رفت. یک شب، نیمه هاى شب، خسرو با صدایى از خواب پرید. یک شیء نورانى چشمک زن را دید که نام او را صدا می زد: خسرو، خسرو... \r\nخسرو گفت: کیه؟ منم، بهمن. تو بهمن نیستى، بهمن مرده! باور کن من خود بهمنم...تو الان کجایی؟  بهمن گفت: در بهشت! و چند خبر خوب و یک خبر بد برات دارم. خسرو گفت: اول خبرهاى خوب را بگو. \r\nبهمن گفت: اول این که در بهشت هم فوتبال برقرار است. و از آن بهتر این که تمام دوستان و هم تیمی هایمان که مرده اند نیز اینجا هستند. حتى مربى سابقمان هم اینجاست. و باز هم از آن بهتر این که همه ما دوباره جوان هستیم و هوا هم همیشه بهار است و از برف و باران خبرى نیست. و از همه بهتر این که می توانیم هر چقدر دلمان می خواهد فوتبال بازى کنیم و هرگز خسته نمی شویم. در حین بازى هم هیچ کس آسیب نمی بیند. \r\nخسرو گفت: عالیه! حتى خوابش را هم نمی دیدم! راستى آن خبر بدى که گفتى چیه؟  بهمن گفت: مربیمون براى بازى جمعه اسم تو را هم توى تیم گذاشته!\r\n"},{"id":887,"category_id":7,"category_code":"s7","source_id":57,"title":"هدیه ی مادر ","content":"چهاربرادر خانه شان را به قصد تحصیل ترک کردند و آدمهای موفقی شدند. چند سال بعد، بعد از شامی که با هم داشتند در مورد هدایایی که برای مادر پیرشون که دور از اونها در شهر دیگه ای زندگی می کرد فرستادن صحبت کردن.  اولی گفت: من خونه بزرگی برای مادرم ساختم ... دومی گفت: من یک سالن سینمای یکصد هزار دلاری در خانه ساختم. سومی گفت: من ماشین مرسدسی با راننده تهیه کردم که مادرم به سفر بره...  چهارمی گفت: همه تون می دونید که مادر چه قدر خوندن کتاب مقدس را دوست داشت و می دونین که دیگه هیچ وقت نمی تونه بخونه، چون چشماش خوب نمی بینه. من راهبی رو دیدم که به من گفت یه طوطی هست که می تونه تمام کتاب مقدس رو از حفظ بخونه. این طوطی با کمک بیست راهب و در طول دوازده سال اینو یاد گرفته. من تعهد کردم برای این طوطی به مدت بیست سال، هر سال صد هزار دلار به کلیسا بپردازم. مادر فقط باید اسم فصل ها و آیه ها رو بگه و طوطی از حفظ براش می خونه. برادرای دیگه تحت تاثیر قرار گرفتن.  پس از تعطیلات، مادر یادداشت تشکری فرستاد. اون نوشت: میلتون عزیز، خونه ای که برام ساختی خیلی بزرگه... من فقط تو یک اتاق زندگی می کنم ولی مجبورم تمام خونه رو تمیز کنم. به هر حال ممنونم.  مایک عزیز، تو برای من یک سینمای گرونقیمت با صدای دالبی ساختی که گنجایش 50 نفر رو داره. ولی من همه دوستامو از دست داده ام، همچنین شنواییم رو از دست دادم و تقریبا ناشنوام. هیچ وقت از اون استفاده نمی کنم، ولی از این کارت ممنونم.  ماروین عزیز، من خیلی پیرم که به سفر برم. من تو خونه می مونم، مغازه بقالی ام رو دارم پس هیچ وقت از مرسدس استفاده نمی کنم. این ماشین خیلی تند تکون می خوره. اما فکرت خوب بود ممنونم. ملوین عزیز ترینم، تو تنها پسری هستی که با فکر کوچیکت بعنوان هدیه ات منو خوشحال کردی. جوجه خیلی خوشمزه بود! ممنونم!"},{"id":888,"category_id":7,"category_code":"s7","source_id":58,"title":"تصادف","content":"یک روز زن و مردی ماشینشون با هم تصادف می کنه، به طوری که ماشین هردو به شدت آسیب می بینه، ولی هردو نفرشون به طرز معجزه آسایی جون سالم به در می برند. بعد از اینکه هر دو از ماشینشون که حالا تبدیل به آهن قراضه شده بیرون اومدن، خانم رو به آقا کرد و گفت: آه! چه جالب! شما مرد هستید! ببینید چه به روز ماشین هامون اومده! همه چیز داغون شده، ولی ما سالم هستیم! این باید یک نشانه از طرف خدا باشه که این طوری با هم ملاقات کنیم و زندگی مشترکی رو با صلح و صفا آغاز کنیم! مرد هم با هیجان پاسخ داد: بله، کاملا با شما موافقم، این باید نشانه ای از طرف خدا باشه! بعد اون زن ادامه داد و گفت: وای خدای من! اینجا رو ببین! یک معجزه دیگه! ماشین من کاملا داغون شده ولی این شیشه مشروب سالم مونده! مطمئنا خدا خواسته که این شیشه مشروب سالم بمونه تا ما این تصادف خوش یمن رو جشن بگیریم!زن مشروب رو به مرد داد و مرد سرش رو به علامت تصدیق تکان داد، در بطری رو باز کرد و نصف شیشه رو با ولع سر کشید! بعد بطری رو برگردوند به زن که او هم بنوشه... اما زن در بطری رو بست و شیشه رو با خونسردی برگردوند به مرد!\r\nمرد با تعجب گفت: شما نمی نوشید؟ و زن در جواب گفت: \"نه، فکر می کنم باید منتظر پلیس بشم!\"\r\n"},{"id":889,"category_id":7,"category_code":"s7","source_id":59,"title":"ماموریت طولانی","content":"در قرون وسطی دو شوالیه عازم ماموریت طولانی و خطرناکی بودند. پس از گذشت یک ساعت از حرکت‌شان یکی به دیگری گفت: من زن جوانی دارم و امروز قبل از حرکت خودم کمربند عفت او را بستم ولی کلیدش را دادم به یک دوست بسیار مطمئن که اگر سالی گذشت و من نیامدم او با آن کلید بتواند زنم را آزاد کند. شوالیه دیگر پرسید: حالا به این دوست خودت اعتماد کافی داری؟ قبل از آن که دیگری جواب دهد ناگهان گرد و خاکی برخاست و سواری به تاخت نزدیک شد ،که همان دوست نازنین بود! شوالیه پرسید: چه شده؟ آیا زنم طوری شده؟ سوار جواب داد: نه زنت کاملا سالم و سر حال است، ولی این کلیدی که دادی اشتباه است!"},{"id":890,"category_id":7,"category_code":"s7","source_id":60,"title":"گزارشگر","content":"\r\nگزارشگر کنار فردی که داره چایی پخش میکنه توی شبهای محرم\r\nگزارشگر : آقا من الان چند دقیقست که دارم از اون دور نگاهت میکنم که لباس مشکی به تن کردی و توی حال قشنگ خودت هستی و توی سرمای هوا با خوش رویی به عاشق های امام حسین چایی میدی . میخوام بدونم با این حالت دوست داری توی یکی از همین ماشینا کی باشه یا اصلا کی از دستت بیاد چایی بگیره و خسته نباشید بگه که حالت رو دگرگون کنه ؟ \r\nفردی که داره چایی میده بعد از چند ثانیه مکث و نگاهی خنگ ( :| ) : والا زیاد برای ما فرقی نمیکنه و تبعیض نمیذاریم که کی با ماشین میاد و کی پیاده . در هر صورت چایی میدیم.\r\nگزارشگر : نه , منظورم اینه که چه کسی باشه , یه آدم خاص. \r\nفرد چایی پخش کن : یعنی دوست آشنا ؟ یا یه کسی که خیلی دوسش داریم ؟\r\nگزارشگر : آره , آره . یه کسی که خیلی برات عزیزه یا اینطوری بگم خیلی برای همه عزیزه. \r\nفرد چایی پخش کن : والا مادر برای همه ی ما عزیز , ولی من مادرم هم باشه به همون اندازه ای چایی میدم که به بقیه میدم , میگم که ما تبغیض نمیذاریم اینجا.\r\n \r\nیعنی من خودم رو میزدم که این گزارشگر چهار ساعت حس گرفت که یارو بگه امام حسین ولی بنده خدا طرف کلا نبود چه برسه به اینکه توی باغ نباشه\r\n"},{"id":891,"category_id":7,"category_code":"s7","source_id":61,"title":"پیشنهادات دانشجویی","content":"باسلام و عرض خسته نباشيد خدمت شما چند پيشنهاد داشتم كه اميدوارم مفيد واقع شود.درابتدا از روش زيباي تدريس شما بسيار تشكر ميكنم.\r\n- استاد شما خيلي خميازه ميكشيد واين باعث ميشود ماهمه خوابمان بگيرد.بعضي از دانشجويان با اينكار شما خوابشون ميگيرد ودائم به دستشويي ميروند تا دست ورويشان را بشويند واينكار باعث ميشود كه نتوانند خوب درس بخوانند. \r\n- استاد شما خيلي به موهاي بلند وبلوندتان دست ميزنيد.بعضي از دانشجويان دختر كلاس با اينكار شما مات ومبهوت ميمانند ونميتوانند به درس تمركز داشته باشند. \r\nاستاد شما خيلي خوشگليد.و براي همين من نميتوانم به شما نگاه نكنم.پس خواهش ميكنم اينقدر به من نگوييد نگاهت به كتابت باشه. \r\nاستاد ديروز يكي از همكلاسيهام درباره شما خيلي بد صحبت ميكرد.راستش من خيلي بهم برخورد چون راستش شمارا خيلي دوست دارم وبراي همين با او به شدت دعوا كردم.اينكار باعث شد همه فكركنند من به شما علاقه دارم.اما خوب ميدونيد من فقط پسري را دوست خواهم داشت كه مثل شما قدبلند باشه وموهاي بلوند داشته باشه.\r\nاستاد ديروز پدرم به دانشگاه آمد و من شما را يواشكي به اونشان دادم.پدرم شما را پسنديد.نميدانيد چقدر خوشحال شدم. \r\nاستاد آخه چرا شما هفته پيش سركلاس نيامديد؟من خيلي دلم براتون تنگ شده بود.دلم هم خيلي شور افتاده بود.نميدونيد جلسه بعدكه شما را ديدم.چقدر خوشحال شدم. \r\nاميدوارم ناراحت نشده باشيد. بهرحال انتقاد هميشه باعث اعتلاي سطح آموزشي ميشه. راستش من هم دوست ندارم شما از دست من ناراحت بشيد.براي همين اگر احتمالا ناراحتتون كردم ازتون معذرت ميخوام.\r\n"},{"id":892,"category_id":7,"category_code":"s7","source_id":62,"title":"بابایی...","content":"بابا جون؟ \r\n- جونم بابا جون؟ \r\nاین خانمه چرا با مانتو خوابیده؟ \r\n- خب… خب… خب حتما اینجوری راحتتره دخترم \r\nیعنی با لباس راحتی سختشه؟ \r\n- آره دیگه، بعضیها با لباس راحتی سختشونه \r\nپس چرا اسمشو گذاشتن لباس راحتی؟ \r\n- …….هیس بابایی، دارم فیلم میبینم \r\nباباجون، کم آوردی؟ \r\n- نه عزیزم، من کم بیارم؟ اصلا هر سوالی داری بپرس تا جواب بدم \r\nخب راستشو بگو چرا این خانمه با مانتو خوابیده بود؟ \r\n- چون خانم خوبیه و حجابشو رعایت میکنه \r\nآهان، پس یعنی مامان من خانم بدیه؟ \r\n- نه دخترم، مامان تو هم خانم خوبیه \r\nپس چرا بدون مانتو میخوابه؟\r\n- خب مامانت اینجوری راحتتره \r\nاون آقاهه هم چون میخواسته حجابشو رعایت کنه با کت و شلوار خوابیده بود؟ \r\n- نه عزیزم، اون چون خسته بود با لباس خوابش برد \r\n-پس چرا خانمش که خیلی هم خانم خوبیه بهش کمک نکرد لباسشو در بیاره؟ \r\n- چون میخواست شوهرش روی پاهای خودش بایسته \r\n-واسه همینه که شما نمیتونید روی پاهای خودتون بایستید؟\r\n- عزیزم مگه تو فردا مدرسه نداری؟ \r\n-داری میپیچونی؟ \r\n- نه قربونت برم عزیزم،اما یه بچه خوب که وسط فیلم اینقدر سوال نمیپرسه؛باشه عسل بابا؟ \r\n-اما من هنوز قانع نشدم \r\n- توی این یک مورد به مامانت رفتی؛ خب بپرس عزیزم \r\n-چرا باباها توی تلویزیون همیشه روی مبل میخوابن؟ \r\n- واسه اینکه تختخوابشون کوچیکه، دو نفری جا نمیشن \r\n-خب چرا یه تخت بزرگتر نمیخرن؟ \r\n- لابد پول ندارن دیگه \r\n-پس چرا اینا دوتا ماشین دارن، ما ماشین نداریم؟ \r\n- چون ماشین باعث آلودگی هوا میشه، ما نخریدیم عزیزم \r\nآهان،یعنی آدما نمیتونن همزمان دوتا کار خوب رو با هم انجام بدن؛ \r\nاون آقاهه وخانومه که حجابشون رو رعایت میکنن،باعث آلودگی هوا میشن، \r\nشما و مامانکه باعث آلودگی هوا نمیشین حجابتون رو رعایت نمیکنین؛ درست گفتم بابایی؟ \r\n- آره دخترم، اصلا همین چیزیه که تو میگی، حالا میشه من فیلم ببینم؟ \r\nباشه،ببین بابایی اما تحت تاثیر این فیلمها قرار نگیری بری ماشین بخریها، \r\nبه جاش برو به مامان یاد بده حجابشو موقع خواب رعایت کنه که تو اینقدر موقع جواب دادن به سوالاتم خجالت نکشی! باشه ؟\r\n"},{"id":893,"category_id":7,"category_code":"s7","source_id":63,"title":"شلوار شوهر","content":"منوچهر تيمورتاش تعريف مي‌كند اين واقعه خنده‌آور مدتي مرا خندانيده است، چندي قبل در يك مجلس شب‌نشيني يكي از رجال با خانمش در رقص شركت كردند. خانم ضمن رقص پي‌برده كه شلوار شوهرش شكافي برداشته است. او را به اشاره به اطاق كوچك ديگري برد و دستور داد فورا آنرا بيرون آورد تا آنرا كوك بزند. اتفاقا در اين حين دو سه نفر خانم ديگر براي تجديد توالت وارد آن اطاق شدند و خانم ناگزير شد شوهر خود را پشت دري كه احتمال مي‌داد در كمد ديواري باشد پنهان كند و خودش پشت آن به ايستد. در اين موقع صداي موزيك قطع شد و خنده دسته ‌جمعي شديد شروع شد و صداي فرياد و استغاثه پشت در كمد بلند شد، آن خانم چون در را باز كرد ديد شوهرش را با آن وضع وارد سالن رقص كرده و در را پشت سر او بسته است!"},{"id":894,"category_id":7,"category_code":"s7","source_id":64,"title":"مدرسه","content":"\r\nصبحی مادری برای بیدار کردن پسرش رفت.\r\nمادر: پسرم بلند شو. وقت رفتن به مدرسه است\r\n…\r\nپسر: اما چرا مامان؟ من نمی خوام برم مدرسه\r\nمادر: دو دلیل به من بگو که نمی خوای بری مدرسه\r\nپسر: یک که همه بچه ها از من بدشون می یاد. دو همه معلم ها از من بدشون می یاد\r\nمادر: اُه خدای من! این که دلیل نمی شه. زود باش تو باید بری به مدرسه\r\nپسر: مامان دو دلیل برام بیار که من باید برم مدرسه؟مادر: یک تو الآن پنجاه و دو سالته. دوم اینکه تو مدیر مدرسه هستی!!\r\n"},{"id":895,"category_id":7,"category_code":"s7","source_id":65,"title":"حال گیری دختر مکزیکی از نامزدش","content":"\r\nلورا پس از دوماه، نامه ای از نامزد مکزیکی خود دریافت می کند به این مضمون:\r\nلورای عزیز، متأسفانه دیگر نمی توانم به این رابطه از راه دور ادامه بدهم و باید بگویم که دراین \r\nمدت ده بار به توخیانت کرده ام !!! و می دانم که نه تو و نه من شایسته این وضع نیستیم. من را ببخش و عکسی که به تو داده بودم برایم پس بفرست \r\nبا عشق : روبرت \r\nدختر جوان رنجیده خاطر از رفتار مرد، از همه همکاران و دوستانش می خواهد که عکسی از نامزد، برادر، پسرعمو، پسردایی ... خودشان به او قرض بدهند و همه آن عکس ها را که کلی بودند با عکس روبرت، نامزد بی وفایش، در یک پاکت گذاشته و همراه با یادداشتی برایش پست می کند، به این مضمون: \r\nروبرت عزیز، مرا ببخش، اما هر چه فکر کردم قیافه تو را به یاد نیاوردم، لطفاً عکس خودت را از میان عکسهای توی پاکت جدا کن و بقیه را به من برگردان...!!\r\n"},{"id":896,"category_id":7,"category_code":"s7","source_id":66,"title":"حقوقدان ","content":"\r\nدختر در کتابخانه دانشگاه مشغول مطالعه بود.\r\nپسر جوانی اومد کنارش و در گوشش گفت میتونم اینجا بشینم\r\nدختر با صدای بلند گفت: \"من امشب خونه ات نمیام\"\r\nهمه دانشجویان که در کتابخانه بودند با تعجب به پسر نگاه کردند و پسرک شرمنده شد رفت و در گوشه ای نشست مشغول مطالعه شد.\r\nپس از مدتی دختر وسایلش را جمع کرد وقتی داشت از کتابخانه خارج میشد رفت و در گوش پسر گفت من روانشناسی خوندم میدونم کاری کردم خجالت زده بشی\r\nپسر بلند داد زد :\"اوه یک شب 200 دلار زیاده\"\r\nهمه دانشجوها با نفرت به دختر نگاه کردند. \r\nپسرک چشمکی زد و گفت منم حقوق میخونم میدونم چطور بی گناه رو گناهکار کنم.\r\n"},{"id":897,"category_id":7,"category_code":"s7","source_id":67,"title":"عرعر خر ","content":"روزی یکی از همسایه‌ها خواست خر حیف نان را امانت بگیرد. به همین خاطر به در خانه او رفت.  حیف نان گفت: \"خیلی معذرت می‌خواهم خر ما در خانه نیست\". از بخت بد، همان موقع خر بنا کرد به عرعر کردن.  همسایه گفت: \"شما که فرمودید خرتان خانه نیست؛ اما صدای عرعرش دارد گوش فلک را کر می‌کند!\" حیف نان عصبانی شد و گفت: \"عجب آدم کج خیال و دیرباوری هستی! حرف مرا قبول نداری ولی عرعر خر را قبول داری.\""},{"id":898,"category_id":7,"category_code":"s7","source_id":68,"title":"پیغام تبریک","content":"مردی برای تولد همسرش به شیرینی فروشی محل تلفن زد تا کیک او را سفارش دهد... \r\nفروشنده پرسید که چه پیغام تبریکی روی کیک بنویسد ؟ \r\nمرد فکری کرد و گفت بنویسید : با اینکه داری پیرتر میشوی ولی هر روز بهتر میشوی \r\nفروشنده پرسید چه جوری این پیغام را بنویسد ؟!\r\nمرد گفت : خب، \"با اینکه داری پیرتر میشوی\" در بالا و \"ولی هر روز بهتر میشوی\" در پایین \r\nمهمانی شروع شد، پاسی از شب گذشته بود که کیک ارسال شد...\r\nدر جعبه کیک که باز شد مهمانها شوکه شدند ، چون روی کیک نوشته شده بود:  \r\n\"با اینکه داری پیرتر میشوی در بالا ، ولی هر روز بهتر میشوی درپایین \" \r\n"},{"id":899,"category_id":7,"category_code":"s7","source_id":69,"title":" پلیس راه","content":"اتفاق جالبی که در اتوبان اصفهان رخ داده: همشهری اصفهانی ما توی اتوبان با سرعت 180 کیلو متر در ساعت می رفته که پلیس با دوربینش شکارش می کند و ماشینش رو متوقف می کند. پلیس میاد کنار ماشین و میگه گواهینامه و کارت ماشین! \r\nاصفهانی با لهجه ی غلیظی میگه :من گواهینامه ندارم.این ماشینم مالی من نیست کارتا ایناشم پیشی من نیست. \r\nمن صاحب ماشینا کشتم و جنازاشم انداختم تو صندوق عقب.چاقوشم صندلی عقب گذاشتم.حالاوم داشتم میرفتم از مرز فرار کونم که شوما منو گیریفتین \r\nمامور پلیس که حسابی گیج شده بود بی سیم می زنه به فرماندش و عین قضیه رو گزارش میدهد و در خواست کمک فوری می کنه فرمانده اش هم به او می گه که کاری نکند تا او خودشو برسونه. \r\nفرمانده در اسرع وقت خودشو به محل می رسوند و به راننده اصفهانی می گوید\r\nاقا گواهینامه؟\r\nاصفهانی گواهینامه اش رو از تو جیبش در میاره و به فرمانده می دهد \r\nفرمانده می گه اقا کارت ماشین؟ \r\nاصفهانی کارت ماشین که به نام خودش بوده در میاره و می دهد به فرمانده \r\nفرمانده که روی صندوق عقب چاقویی پیدا نکرده عصبانی دستور می دهد تا راننده در صندوق عقب را باز کند. \r\nاصفهانی در صندوق رو باز می کند و فرمانده می بینه که صندوق هم خالیست \r\nفرمانده که حسابی گیج شده بود به اصفهانی میگه \"پس این مامور ما چی میگه؟ \r\nاصفهانی می گوید:چی میدونم والا جناب سرهنگ.لابد الانم می خواد بگه من 180 تا سرعت می رفتم.\r\n"},{"id":900,"category_id":7,"category_code":"s7","source_id":70,"title":"اس ام اس ","content":"چند وقت پیش یکی از دخترا برام یه اس ام اس فرستاد با این مضمون \r\nاس ام اس این بود: \r\nخیلی بی معرفتی ، خیلی نامردی ، خیلی بی معرفتی ، خیلی بی جنبه هستی ، آخه نامرد باید از رو چی توز بفهمم موتور خریدی ؟!!\r\nمنم بر اساس تجربه قبلی و تذکری که دوستان بهم داده بودن تصمیم گرفتن این سری قاطعانه تلافی کنم برای همین هم من هم براش یه اس ام اس فرستادم که: \r\nپنج روش آدم شدن 1...2...3...4...5...بی خود نگرد تو آدم بشو نیستی! \r\nدختره هم که نمی خواست کم بیاره یه اس ام اس فرستاد که \r\nخیلی ببخشید..شرمنده مثل اینکه موقع بدی مزاحم شدم..فقط می خواستم بپرسم آب خوردی آفتابه رو کجا گذاشتی؟!! \r\nمنم که دیدم نه بابا طرف روش کم نمی شه دوباره یه اس ام اس فرستادم با این متن \r\nبه جای آب دوست داشتم جیگرتو بخورم!\r\nولی حیف باید تا عید قربان سال دیگه صبر کنم. \r\nاونم نامردی نکرد دوباره فرستاد که: \r\nاسمت رو گذاشتم گل، گفتم پژمرده می شی\r\nاسمت رو گذاشتم خورشید، گفتم غروب می کنی\r\nاسمت رو گذاشتم خر، تا لااقل بارم رو ببری!!\r\nمنم که تازه موتورم گرم شده بود اومدم اس ام اس بعدی رو بفرستم که یهو دیدم همین دختره داره زنگ می زنه دستپاچه جواب دادم بله!یهو دیدم یه صدای کلفت نخراشیده ای بدون هیچ مقدمه ای شروع کرد به بد و بیراه گفتن که فلان فلان شده تو مگه خواهر مادر نداری می خوای جیگر دختر مردم رو بخوری می دم چوب تو .... بعدم شروع کرد به تهدید که بیا فلان جا کارت دارم !!! اگه .... داری بیا اگه نیای خودم شمارت رو دارم آدرست رو گیر میارم میام اونجا ....خلاصه خیلی گیر داده بود که من یه جا باهاش قرار بذارم برم پیشیش ! منم هر چی معذرت خواهی و اشتباه شده و از این جور حرفا فایده نداشت نمی دونستم برادرشه یا پدرش ولی هر کی بود صدای دلخراشی داشت خلاصه بعد چند دقیقه ارائه انواع فحشهای رکیک تلفن رو قطع کرد منم که فقط دست و پام می لرزید تا شب هزار جور فکرکردم .با خودم گفتم برم یه جا یه مدت خودم رو گم و گور کنم ولی دیدم فایده نداره خلاصه صبح روز بعد دوباره شمارهدختره زنگ زد با خودم گفتم این دفعه اگه راه داده معذرت خواهی وگرنه دیگه خدا رحم کنه خلاصه گوشی رو جواب دادم دیدم خود دختره بود و کلی معذرت خواهی و بعدم رک و راست گفت که دیروز منتظر دوست پسرش بوده می خواسته تا اون نیومده یکم وقت کشی کنه دیده کی بهتر از ما !!! بعدم که اون پسره سر می رسه! البته گفت که یه جور سر و ته قضیه رو هم آورده! \r\nبله !به قول یکی از دوستان مثل اینکه این دختر خانم ما رو زاپاس می خواسته ! منم برای خودم هزار تا فحش گذاشتم که فلانم و فلان اگه یه بار دیگه به اس ام اس یه دختر جواب بدم.\r\n"},{"id":901,"category_id":7,"category_code":"s7","source_id":71,"title":"صدای مخاطب خاص ","content":"چند سال پیش، که مخاطب خاص داشتم و دانشجو بودم یه روز تو خوابگاه با هم اتاقیام نشسته بودیم و حرف میزدیم که مخاطب خاصم زنگ زد.\r\nگوشی رو برداشتم بعد از جملاتی رمانتیک گفت یه شعر برات بخونم؟ گفتم بخون. گفت گوشی رو میذاری رو اسپیکر هم اتاقیات هم گوش کنن؟\r\nمنم که فکر میکردم میخواد یکی از ترانه های عشقولانه ی سیاوش رو بخونه(آخه همش سیاوش میخوند) با افتخار گوشی رو گذاشتم رو اسپیکر. مخاطب خاصمم صداشو صاف کرد و با لحن کودکانه خوند:\r\nجوجو زرده پشت پرده پی پی کرده پاک نکرده/بردنش کلانتری، گفت که من کار ندارم/ حال و احوال ندارم/ یه زن دارم چاقه آش میپزه داغه...\r\nهم اتاقیام داشتن در و دیوار اتاقو چنگ میزدن. منم با جزوه هام عرق شرممو پاک میکردم.\r\n"},{"id":902,"category_id":7,"category_code":"s7","source_id":72,"title":"کارت پخش کن ","content":"یک روز توی پیاده رو به طرف میدان تجریش می رفتم، از دور دیدم یک کارت پخش کن خیلی با کلاس، کاغذهای رنگی قشنگی دستشه، ولی به هر کسی نمی ده! خانم ها رو که کلا تحویل نمی گرفت و در مورد آقایون هم خیلی گزینشی رفتار می کرد و معلوم بود فقط به کسانی کاغذ رو می داد که مشخصات خاصی از نظر خودش داشته باشند، اهل حروم کردن تبلیغات نبود... احساس کردم فکر می کنه هر کسی لیاقت داشتن این تبلیغات تمام رنگی گرون قیمت رو نداره، لابد فقط به آدمهای باکلاس و شیک پوش و با شخصیت می ده! از کنجکاوی قلبم داشت می اومد توی دهنم...!!! خدایا، نظر این تبلیغاتچی خوش تیپ و با کلاس راجع به من چه خواهد بود؟! آیا منو تائید می کنه؟!کفشهامو با پشت شلوارم پاک کردم تا مختصر گرد و خاکی که روش نشسته بود پاک بشه و کفشم برق بزنه! شکم مبارک رو دادم تو و در عین حال سعی کردم خودم رو بی تفاوت نشون بدم! دل تو دلم نبود. یعنی منو می پسنده؟ یعنی به من هم از این کاغذهای خوشگلمی ده...؟\r\nهمین طور که سعی می کردم با بی تفاوتی از کنارش رد بشم با لبخند نگاهی بهم کرد و یک کاغذ رنگی به طرفم گرفت و گفت: \"آقای محترم! بفرمایید\" قند تو دلم آب شد! با لبخندی ظاهری و بدون دستپاچگی یا حالتی که بهش نشون بده گفتم: ا ِ، آهان، خوب چرا من؟ من که حواسم جای دیگه بود و به شما توجهی نداشتم! خیلی خوب، باشه، می گیرمش ولی الآن وقت خوندنش رو ندارم!\" کاغذ روگرفتم...\r\nچند قدم اونورتر پیچیدم توی قنادی و اونقدر هول بودم که داشتم با سر می رفتم توی کیک تولدی که دست یک آقای میانسال بود! وایسادم وبا ولع تمام به کاغذ نگاه کردم، نوشته بود:\r\n \r\n.\r\n.\r\n.\r\n.\r\n.\r\n.\r\n.\r\n.\r\n.\r\n.\r\nدیگر نگران طاسی سر خود نباشید، پیوند مو با جدیدترین متد روز اروپا و امریکا!\r\n"},{"id":903,"category_id":7,"category_code":"s7","source_id":73,"title":"مهریه","content":"پسر جوان، وقتى پاى سفره عقد نشست و حاضر شد مهريه همسرش را پانصد هزار شاخه گل سرخ و يك جلد ديوان شمس تبريز به خط خودش در نظر بگيرد، نمى‌دانست چند سال بعد بايد چند هزار بيت شعر ديوان شمس را بنويسد . به نوشته « ايران»، چندى پيش، زنى جوان به شعبه 264 دادگاه خانواده 121 مراجعه و با ارائه دادخواست طلاق به قاضى نحوى گفت: چند سال پيش بود كه جوان مهندسى به خواستگارى‌ام آمد. از همان اول تصميم گرفتم كه بناى زندگى‌مان را بر پايه تفاهم و عشق و عرفان بگذارم اين بود كه براى مهريه‌ام، پانصد هزار شاخه گل سرخ و ديوان شمس به خط شوهرم و چهارده سكه بهار آزادى تعيين كردم. فكر مى‌كردم اگر او حاضر شود چنين مهريه‌اى را بپذيرد، بايد از انديشه بالايى برخوردار باشد. وى گفت: او هم پذيرفت و ما بعد از ازدواج، زندگى مشتركمان را آغاز كرديم. در اين مدت با اينكه از نظر عقيدتى ميان من و شوهرم تفاوتهايى بود و گاهى مشكل پيدا مى‌كرديم ولى من سعى مى‌كردم با گذشت باعث حفظ زندگى مشتركم شوم. وى ادامه داد: تا اينكه بعد از چند سال، روز به روز بر اختلاف ميان من و اواضافه شد و شوهرم و من به اين نتيجه رسيده ايم كه ديگر امكان ادامه اين زندگى وجود ندارد و به همين علت من به دادگاه خانواده مراجعه كرده و تقاضاى دريافت مهريه و طلاق دارم . با درخواست اين زن جوان، قاضى دستور احضار اين مرد را به دادگاه داد. اين مرد جوان در برابر قاضى دادگاه خانواده گفت: آقاى قاضى! من و همسرم با اينكه از ابتدا سعى داشتيم تا پايه‌هاى زندگى مشتركمان را استحكام ببخشيم موفق نشديم و به همين علت من هم فكر مى‌كنم بهتر است تا از يكديگر جدا شويم . > وى گفت: طبق مهريه‌اى كه براى همسرم تعيين كرده‌ام، بايد ديوان شمس را به خط خودم براى او بنويسم و پانصدهزار شاخه گل به او بدهم .قاضى نحوى پس از استعلام از اتحاديه گل‌فروشان، قيمت پانصدهزار شاخه گل را كه بخشى از مهريه عروس جوان بود، 150ميليون تومان محاسبه كرده و در حكمى به داماد جوان اعلام شد كه وى موظف به پرداخت 150 ميليون تومان ـ قيمت پانصد هزار شاخه گل سرخ ـ چهارده سكه بهار آزادى و نوشتن از روى اشعار ديوان شمس تبريزى است. > اي خاك بر سر مهندست بكنن > معلوم شد که آقای مهندس نه اهل عرفان بوده نه اهل حساب وکتاب و ریاضی وباغبانی وبازار و بطور کلی چهار عمل اصلی را هم بلد نبوده ننه مرده"},{"id":904,"category_id":7,"category_code":"s7","source_id":74,"title":"مدیر منحرف","content":"\r\nیه پسر بچه کلاس اولی به معلمش میگه: خانوم معلم من باید برم کلاس سوم\r\nمعلمش با تعجب میپرسه برای چی؟\r\n...اونم میگه: آخه خواهر من کلاس سومه اما من از اون بیشتر میدونم و باهوش ترم\r\nتوی زنگ تفریح معلمه به مدیر مدرسه موضوع رو میگه اونم خوشش میاد میگه بچه رو بیار تو دفتر من چند تا تست ازش بگیریم ببینیم چی میگه\r\nمعلمه زنگ بعد پسره رو میبره تو دفتر بعد خانوم مدیره شروع میکنه به سوال کردن\r\nخب پسرم بگو ببینم سه سه تا چند تا میشه اونم میگه نه تا\r\nدوباره میپرسه نه هشت تا چند تا میشه اونم میگه هفتادو دو تا\r\nهمینجوری سوال میکنه و پسره همه رو جواب میده دیگه کف میکنه به معلمش میگه به نظر من این میتونه بره کلاس سوم\r\nخانوم معلم هم میگه بزار حالا چند تا من سوال کنم\r\nمیگه پسرم اون چیه که گاو چهار تا داره اما من دو تا دارم؟ مدیره ابروهاشو بالا میندازه که پسره جواب میده: پا\r\nدوباره خانوم معلمه میپرسه: پسرم اون چیه که تو توی شلوارت داری اما من تو شلوارم ندارم مدیره دهنش از تعجب باز میشه که پسره جواب میده: جیب\r\nدوباره خانوم معلمه سوال میکنه: اون چه کاریه که مردها ایستاده انجام میدن اما زن ها نشسته و سگ ها روی سه پا تا مدیره بیاد حرف بیاره وسط پسره جواب میده : دست دادن\r\nباز معلمه سوال میکنه : بگو ببینم اون چیه که وقتی میره تو سفت و قرمزه اما وفتی میاد بیرون شل و چسبناک مدیره با دهان باز از جاش بلند میشه که بگه این چه سوالیه که پسره میگه: آدامس بادکنکی\r\nدیگه مدیره طاقت نمیاره میگه بسه دیگه این بچه رو بزارید کلاس پنجم من خودم همه سوالهای شما رو غلط جواب دادم!\r\n"},{"id":905,"category_id":7,"category_code":"s7","source_id":75,"title":"درس زندگی","content":"داستان ما اینگونه آغاز میشود که: \r\nدر یک دزدی بانک یکی از ایالات آمریکا دزد فریاد کشید. \r\nهمه افراد حاظر در بانک ، حرکت نکنید ، پول مال دولت است و زندگی به شما تعلق دارد.\r\nهمه در بانک به آرامی روی زمین دراز کشیدند.\r\nاین «شیوه تغییر تفکر» نام دارد، تغییر شیوه معمولی فکر کردن \r\nهنگامیکه دزدان بانک به خانه رسیدند، جوانی که (مدرک لیسانس اداره کردن تجارت داشت)\r\nبه دزد پیرتر(که تنها شش کلاس سواد داشت) گفت :برادر بزرگتر، بیا تا بشماریم چقدر بدست آورده ایم.\r\nدزد پیرتر با تعجب گفت؛ تو چقدر احمق هستی، اینهمه پول شمردن زمان بسیار زیادی خواهد برد.\r\nامشب تلویزیون ها در خبرها خواهند گفت ما چقدر از بانک دزدیده ایم.\r\nاین را میگویند: «تجربه» اینروز ها، تجربه مهمتر از ورقه کاغذ هایی است که به رخ کشیده میشود!\r\nپس از آنکه دزدان بانک را ترک کردند ، مدیر بانک به رییس خودش گفت، فوری به پلیس خبر بدهید.\r\nاما رییس اش پاسخ داد: «تامل کن! بگذار ما خودان هم ۱۰ میلیون از بانک برای خودمان برداریم.\r\nو به آن ۷۰ میلیون میلیون که از بانک ناپدید کرده بودیم بیافزاییم.\r\nاینرا میگویند «با موج شنا کردن» پرده پوشی به وضعیت غیرقابل باوری به نفع خودت! \r\nرییس کل می گوید: بسیار خوب خواهد بود که هرماه در بانک دزدی بشود.\r\nاینرا میگویند «کشتن کسالت» شادی شخصی از انجام وظیفه مهمتر می شود.\r\nروز بعد، تلویزیون اعلام میکند ۱۰۰ میلیون دلار از بانک دزدیده شده است.\r\nدزد ها پولها را شمردند و دوباره شمردند اما نتوانستند ۲۰ میلیون بیشتر بدست آورند.\r\nدزدان بسیار عصبانی و شاکی بودند:\r\nما زندگی و جان خودرا گذاشتیم و تنها ۲۰ میلیون گیرمان آمد.\r\nاما روسای بانک ۸۰ میلیون را در یک بشکن بدست آوردند.\r\nانگار بهتر است انسان درس خوانده باشد تا اینکه دزد بشود.\r\nاینرا میگویند؛ \"دانش به اندازه طلا ارزش دارد.\"\r\nرییس بانک با خوشحالی میخندید زیرا او در ضرر خودش در سهام را در این بانک دزدی پوشش داده بود.\r\nاینرا میگویند؛ «موقعیت شناسی» جسارت را به خطر ترجیح دادن.\r\nدر اینجا کدامیک دزد راستین هستند؟\r\n"},{"id":906,"category_id":7,"category_code":"s7","source_id":76,"title":"امتحان ","content":"چند ﺳﺎﻝ ﭘﯿﺶ ﯾﻪ ﺩﻭﺳﺖ پسر ﺩﺍﺷﺘﻢ\r\nﺑﻬﺶ ﺷﮏ ﮐﺮﺩﻩ ﺑﻮﺩﻡ... \r\nﺷﻤـــﺎﺭﺷﻮ ﺩﺍﺩﻡ ﺑﻪ دوستم ﺗﺎ ﺍﻣﺘــــﺤﺎﻧﺶ ﮐﻨﻢ\r\nﺍﯾــــﻦ ﺟــــﺮﯾﺎﻥ ﮔـــــُـــﺬﺷﺖ ﻭ ﺑﻌــــﺪ ﺳﻪ ﺳـــــﺎﻝ\r\nﯾﻌﻨﯽ ﻫﻤﯿﻦ ﺩﻭ ﻫﻔﺘﻪ ﭘﯿﺶ ﺑﻪ ﺳﻼﻣﺘﯽ ﺑﺎ ﻫﻢ ﺍﺯﺩﻭﺍﺝ ﮐﺮﺩﻥ \r\nﻭ ﺗﻨﻬﺎ ﮐﺴﯽ ﻫﻢ ﮐﻪ ﺍﺯ ﺑﭽﻪ ﻣﺤﻼ ﺩﻋﻮﺕ ﻧﺸﺪﻩ ﺑﻮﺩ ﻣﻦ ﺑﻮﺩﻡ\r\nﺑﯿـــــﺨﯿﺎﻝ ..... ﺍﯾﺸــــﺎﻟﻠﻪ ﺑﻪ ﭘــــــﺎﯼ ﻫﻢ ﭘﯿــــﺮ بشن! \r\nﺍﻻﻧـــﻢ ﯾﻪ ﺩﻭﺳﺖ پسر ﺩﺍﺭﻡ کـــه بهش ﺷﮏ ﺩﺍﺭﻡ\r\nﻭﻟـــﯽ ﺩﯾﮕﻪ ﻏﻠﻂ ﺑﮑﻨﻢ ﺑﺨﻮﺍﻡ ﺍﻣﺘﺤﺎﻧﺶ ﮐﻨﻢ\r\n"},{"id":907,"category_id":7,"category_code":"s7","source_id":77,"title":"رفیق ناباب ","content":"یه روز یکی از بچه های دانشگاه زنگ زد بهم گفت برم خونشون براش نرم افزار کد ویژن رو نصب کنم تا بتونه برنامه نویسی روی میکروکنترلر رو شروع کنه.\r\nمنم قبول کردم و رفتم خونشون.در رو که باز کرد مادر این دوستمون سلام علیک خیلی گرمی با من کرد و کلی تحویلم گرفت.\r\nنرم افزار رو روی سیستمش نصب کردم و یکی دیگه از نرم افزارهاشم که تاریخ گذشته بود کرک کردم تا مشکلش رفع شه.بهشم گفتم کرک این نرم افزارو برات می ذارم \r\nاینجا هر وقت لازم شد دوباره ازش استفاده کن.\r\nموقع رفتن که شد دیدم مادره به دوستم میگه دیگه این پسره رو نیاری خونه ها!!‌ ایندفه اینجا ببینمش زنگ می زنم پلیس بیاد.\r\nمنم به روی خودم نیاوردم و از دوستم خداحافظی کردم و اومدم پایین دم در منتظرش وایسادم.\r\nدوستم اومد ,دیدم داره از زور خنده داره زمین رو گاز میزنه.\r\nبهش گفتم: زهر مار.نه به سلام علیک اول نه به خداحافظی آخر!!\r\nدوستم گفت مادرش از پشت در می شنیده که من میگم : “کرک برات گذاشتم” و اونم فکر کرده من مواد فروشم دارم به پسرش کراک می فروشم.خلاصه بنده خدا می خواسته پسرش رو از بند اعتیاد و رفیق ناباب برهاند که نزدیک بود ما در این راستا مورد عنایت قرار بگیریم.\r\n"},{"id":908,"category_id":7,"category_code":"s7","source_id":78,"title":"سوء تفاهم ","content":"یه روز صبح یه مریض به دكتر جراح مراجعه میكنه و از كمر درد شدید شكایت میكنه.\r\nدکتره بعد از معاینه ازش میپرسه : خب، بگو ببینم واسه چی كمر درد گرفتی؟\r\nمریض پاسخ میده: \"من برای یك كلوپ شبانه كار میكنم. امروز صبح زودتر به خونه ام رفتم و وقتی وارد آپارتمانم شدم، یه صداهایی از اتاق خواب شنیدم! وقتی وارد اتاق شدم، فهمیدم كه یكی با همسرم بوده!!\r\nدربالكن هم باز بود. من سریع دویدم طرف بالكن، ولی كسی را اونجا ندیدم. وقتی پایین را نگاه كردم،\r\nیه مرد را دیدم كه میدوید و در همان حال داشت لباس میپوشید. \r\nمن یخچال را كه روی بالكن بود گرفتم و پرتاب کردم به طرف اون!!\r\nدلیل كمر دردم هم همین بلند كردن یخچاله.\r\nمریض بعدی دكتر بهش میگه :، به نظر میرسید كه تصادف بدی با یك ماشین داشته.مریض قبلیِ من بد حال به نظر میرسید، ولی مثل اینكه حال شما خیلی بدتره!بگو ببینم چه اتفاقی برات افتاده؟ \r\nمریض پاسخ میده:\r\nباید بدونید كه من تا حالا بیكار بودم و امروز اولین روز كار جدیدم بود\r\nولی من فراموش كرده بودم كه ساعت را كوك كنم و برای همین هم نزدیك بود دیر كنم\r\nمن سریع از خونه زدم بیرون و در همون حال هم داشتم لباسهام را میپوشیدم،شما باور نمیكنید؛\r\nولی یهو یه یخچال از بالا افتاد روی سر من!\r\nوقتی مریض سوم میاد به نظر میرسه كه حا از دو مریض قبلی وخیمتره\r\nدكتره در حالی كه شوكه شده بوده دوباره میپرسه \"از كدوم جهنمی فرار كردی؟\"\r\nخب، راستش توی یه یخچال بودم كه یهو یه نفر اون را از طبقهء سوم پرتاب كرد!\r\n\r\n"},{"id":909,"category_id":7,"category_code":"s7","source_id":79,"title":"قول مادر ","content":"هر وقت من یک کار خوب می کنم مامانم به من می گوید بزرگ که شدی برایت یک زن خوب می گیرم.تا به حال من پنج تا کار خوب کرده ام و مامانم قول پنج تایش را به من داده است. \r\nحتمن ناسرادین شاه خیلی کارهای خوب می کرده که مامانش به اندازه استادیوم آزادی برایش زن گرفته بود. ولی من مؤتقدم که اصولن انسان باید زن بگیرد تا آدم بشود ، چون بابایمان همیشه می گوید مشکلات انسان را آدم می کند. \r\nدر عزدواج تواهم خیلی مهم است یعنی دو طرف باید به هم بخورند. مثلن من و ساناز دختر خاله مان خیلی به هم می خوریم. \r\nاز لهاز فکری هم دو طرف باید به هم بخورند، ساناز چون سه سالش است هنوز فکر ندارد که به من بخورد ولی مامانم می گوید این ساناز از تو بیشتر هالیش می شود.در عزدواج سن و سال اصلن مهم نیست چه بسیار آدم های بزرگی بوده اند که کارشان به تلاغ کشیده شده و چه بسیار آدم های کوچکی که نکشیده شده. مهم اشق است! \r\nاگر اشق باشد دیگر کسی از شوهرش سکه نمی خواهد و دایی مختار هم از زندان در می آید من تا حالا کلی سکه جم کرده ام و می خواهم همان اول قلکم را بشکنم و همه اش را به ساناز بدهم تا بعدن به زندان نروم.\r\nمهریه و شیر بلال هیچ کس را خوشبخت نمی کند. همین خرج های ازافی باعث می شود که زندگی سخت بشود و سر خرج عروسی داییمختار با پدر خانومش حرفش بشود دایی مختار می گفت پدر خانومش چتر باز بود.. خوب شاید حقوق چتر بازی خیلی کم بوده که نتوانسته خرج عروسی را بدهد. البته من و ساناز تفافق کرده ایم که بجای شام عروسی چیپس و خلالی نمکی بدهیم. هم ارزان تر است ، هم خوشمزه تراست تازه وقتی می خوری خش خش هم می کند!\r\nاگر آدم زن خانه دار بگیرد خیلی بهتر است و گرنه آدم مجبور می شود خودش خانه بگیرد. زن دایی مختار هم خانه دار نبود و دایی مختار مجبور شد یک زیر زمینی بگیرد. میگفت چون رهم و اجاره بالاست آنها رفته اند پایین! اما خانوم دایی مختار هم می خواست برود بالا! حتمن از زیر زمینی می ترسید. ساناز هم از زیر زمینی می ترسد برای همین هم برایش توی باغچه یک خانه درختی درست کردم. اما ساناز از آن بالا افتاد و دستش شکست.. از آن موقه خاله با من قهر است. \r\nقهر بهتر از دعواست. آدم وقتی قهر می کند بعد آشتی می کند ولی اگر دعوا کند بعد کتک کاری می کند بعد خانومش می رود دادگاه شکایت می کند بعد می آیند دایی مختار را می برند زندان!\r\nالبته زندان آدم را مرد می کند.عزدواج هم آدم را مرد می کند، اما آدم با عزدواج مرد بشود خیلی بهتر است!این بود انشای من\r\n"},{"id":910,"category_id":7,"category_code":"s7","source_id":80,"title":"نصیحت","content":"توی کافه‌ی فرودگاه یکی بود که پشت سر هم سیگار می‌کشید؛ یکی دیگه رفت جلو گفت:\r\n- بب...خشید آقا! شما روزی چند تا سیگار می‌کشین؟\r\nمنظور؟\r\n- منظور اینکه اگه پول این سیگارا رو جمع می‌کردین، به اضافه‌ی پولی که\r\nبه خاطر این لامصب خرج دوا و دکتر می‌کنین، الان اون هواپیمایی که اونجاست مال شما بود!\r\n- تو سیگار می‌کشی؟\r\n- نه\r\n- هواپیما داری؟\r\n- نه\r\nبه هر حال مرسی بابت نصیحتت؛ ضمناً اون هواپیما که نشون دادی مال منه!!\r\n"},{"id":911,"category_id":7,"category_code":"s7","source_id":81,"title":"حساب کتاب","content":"\r\nپسر بچه ای یک برگ کاغذ به مادرش داد\r\nمادر که در حال آشپزی بود ، دستهایش را با حوله تمیز کرد و نوشته را با صدای بلند خواند.\r\nاو نوشته بود: \r\nصورتحساب!! \r\nکوتاه کردن چمن باغچه 5.000 تومان\r\nمراقبت از برادر کوچکم 2.000 تومان\r\nنمره ریاضی خوبی که گرفتم 3.000 تومان\r\nبیرون بردن زباله 1000 تومان\r\nجمع بدهی شما به من :12.000 تومان! \r\nمادر نگاهی به چشمان منتظر پسرش کرد، چند لحظه خاطراتش را مرور کرد و سپس قلم را برداشت و پشت برگه صورتحساب این را نوشت:\r\nبابت 9 ماه بارداری که در وجودم رشد کردی هیچ\r\nبابت تمام شبهائی که به پایت نشستم و برایت دعا کردم هیچ\r\nبابت تمام زحماتی که در این چند سال کشیدم تا تو بزرگ شوی هیچ\r\nبابت غذا ، نظافت تو ، اسباب بازی هایت هیچ\r\nو اگر شما اینها را جمع بزنی خواهی دید که : هزینه عشق واقعی من به تو هیچ است\r\nوقتی پسر آن چه را که مادرش نوشته بود خواند چشمانش پر از اشک شد ودر حالی که به چشمان مادرش نگاه می کرد.\r\nگفت: مامان ... دوستت دارم\r\nآنگاه قلم را برداشت و زیر صورتحساب نوشت: قبلاً بطور کامل پرداخت شده!! \r\nنتیجه گیری اخلاقی: \r\nقابل توجه اونهائی که فکر میکنند مرور زمان آنها را بزرگ کرده و حالا که هیکل درشت کردند خدا را هم بنده نیستند.\r\nبعضی وقتها نیازه به این موارد فکر کنیم... \r\nکسانی که از خانواده دور هستند شاید بهتر درک کنند.\r\nنتیجه گیری منطقی:\r\nجایی که احساسات پا میذاره منطق کور میشه!!\r\nمادر متوجه نشد که پسرش داره سرش کلاه میذاره : جمع بدهی میشه 11.000 تومان نه 12.000 تومان!!\r\n"},{"id":912,"category_id":7,"category_code":"s7","source_id":82,"title":"نابغه ","content":"\r\nزن و مردی چند سال بعد از ازدواجشون صاحب پسری میشن و\r\nچند روز بعد از تولد بچه متوجه میشن که اون یه نابغه اس بچه در\r\nیک سالگی مثل یک آدم بزرگ شروع به حرف زدن میکنه و در\r\nدوسالگی به اکثر زبانها حرف میزنه در سه سالگی با اساتید\r\nدانشگاه به بحث و تبادل نظر میپردازه و در چهار سالگی پیش بینی\r\nهای باور نکردنی راجع به علم و پیشرفت اون میکنه در جشن تولد\r\nپنج سالیگش در حضور همه فامیل اعلام میکنه :من دقیقا یک سال\r\nدیگه میمیرم ، مادرم ۱۸ ماه بعد از من میمیره و پدرم یک سال بعد\r\nاز مرگ مادرم میمیره !! پسر بچه همون طور که گفته بود در شش\r\nسالگی میمیره و مرد بلافاصله در چندین شرکت بیمه همسرش رو\r\nبیمه عمر میکنه طبق پیش بینی بچه مادرش هم در تاریخی که گفته\r\nبود میمیره و ثروت هنگفتی بخاطر بیمه عمر زن نصیب مرد میشه! \r\nمرد تصمیم میگیره ۱سال باقی مانده از عمرش رو به خوشی بگذرونه\r\nپس به سفرهای تفریحی زیادی میره ، در بهترین هتلهای جهان اقامت\r\nمیکنه،گران ترین خودروهای دنیا رو برای خودش میخره و درآخرین\r\nروز عمرش تمام دوستان و آشنایانش رو دعوت میکنه ، مهمونی\r\nمفصلی میگیره و آخرین شب زندگیش رو با یک دختر زیبا مشغول\r\nخوشگذرونی میشه .صبح با صدای جیغ دختره از خواب پا میشه\r\nو در حالی که تعجب کرده بود که چرا هنوز زنده اس میپرسه\r\nچی شده ؟ دختره جواب میده: \r\nوکیل خانوادگی شما تو راهرو افتاده و\r\nهیچ حرکتی نمیکنه ، فکر کنم فوت شده\r\n(لازم نیست توضیح بدم که وکیل محترم پدر اصلی پسره بوده!)\r\n"},{"id":913,"category_id":7,"category_code":"s7","source_id":83,"title":"شوهر مهربان ","content":"زنی با سر و صورت کبود و زخمی سراغ دکتر روانشناس میره ..دکتر می پرسه : چه اتفاقی افتاده؟خانم در جواب میگه: دکتر، دیگه نمی دونم چکار کنم. هر وقت شوهرم عصبانی و ناراحت میاد خونه،منو زیر مشت و لگد له می کنه وعصبانیتش رو سر من خالی می کنه!!!دکتر گفت: خب دوای دردت پیشمنه : هر وقت شوهرت عصبانی و ناراحت اومد خونه، یه فنجون چای سبز بردار و شروع کن به قرقره کردن. و این کار رو ادامه بده.دو هفته بعد،اون خانم با ظاهری سالم و سرزنده پیش دکتر برگشت !!!خانم گفت: دکتر، پیشنهادتون فوق العاده بود. هر بار شوهرم عصبانی و ناراحت اومد خونه، من شروع کردم به قرقره کردن چای و شوهرم دیگه به من کاری نداشت!!!دکتر گفت: میبینی؟! اگه جلوی زبونت رو بگیری خیلی چیزا خود به خود حل میشن!"},{"id":914,"category_id":7,"category_code":"s7","source_id":84,"title":"استرس ","content":"\r\nزنی مشغول درست کردن تخم مرغ برای صبحانه بود.\r\nناگهان شوهرش سراسیمه وارد آشپزخانه شد و داد زد: مواظب باش، مواظب باش، یه کم بیشتر کره توش بریز.. وای خدای من، خیلی درست کردی.. حالا برشگردون .. زود باش. باید بیشتر کره بریزی.. وای خدای من از کجا باید کره بیشتر بیاریم؟؟ دارن می‌سوزن. مواظب باش. گفتم مواظب باش! هیچ وقت موقع غذا پختن به حرفهای من گوش نمی‌کنی.. هیچوقت!! برشون گردون! زودباش! دیوونه شدی؟؟؟؟ عقلتو ازدست دادی؟؟؟ یادت رفته بهشون نمک بزنی.نمک بزن... نمک...\r\n. زن به او زل زده و ناگهان گفت: خدای بزرگ چه اتفاقی برات افتاده؟! فکر می‌کنی من بلد نیستم یه تخم مرغ ساده درست کنم؟ شوهر به آرامی گفت: فقط می‌خواستم بدونی وقتی دارم رانندگی می‌کنم، چه احساسی دارم.\r\n"},{"id":915,"category_id":7,"category_code":"s7","source_id":85,"title":"حشره ی بزرگ ","content":"دو تا پيرمرد با هم قدم مي زدن و 20 قدم جلوتر همسرهاشون کنار هم به آرومي در حال قدم زدن بودن. \r\nپيرمرد اول: «من و زنم ديروز به يه رستوران رفتيم که هم خيلي شيک و تر تميز و با \r\nپيرمرد دوم: \" اِ... چه جالب. پس لازم شد ما هم يه شب بريم اونجا... اسم رستوران چي بود؟\"\r\nپيرمرد اول کلي فکر کرد و به خودش فشار آورد، اما چيزي يادش نيومد. بعد پرسيد: \"ببين، يه حشره اي هست، پرهاي بزرگ و خوشگلي داره، خشکش مي کنن تو خونه به عنوان تابلو نگه مي دارن، اسمش چيه؟\"\r\nپيرمرد دوم: پروانه؟\r\nپيرمرد اول: «آره!» بعد با فرياد رو به پيرزنها: \"پروانه! پروانه! اون رستوراني که ديروز رفتيم اسمش چي بود؟!!\"\r\n"},{"id":916,"category_id":7,"category_code":"s7","source_id":86,"title":"عمو حسن ","content":"\r\nصدای زنگ تلفن دختر کوچولو میره گوشی رو بر میداره\r\nسلام .\r\n کیه؟\r\n-سلام دختر خوشگلم منم بابایی! مامانی خونه است؟ گوشی رو بده بهش\r\n!- نمیشه\r\nچرا؟\r\n- چون با عمو حسن رفتن تو اطاق خواب طبقه بالا در رو هم رو خودشون بستن!\r\n سکوت!\r\n!- بابایی ما که عمو حسن نداریم\r\n- چرا داریم. الآن پهلو مامانه\r\n- ببین عزیزم. اینکاری که میگم بکن. برو بزن به درو بگو بابا اومده خونه!\r\n... چشم بابا!... چند دقیقه بعد\r\nبابا جون گفتم\r\nخوب چی شد؟\r\n- هیچی. همینکه گفتم یهو صدای جیغ مامانم اومد بعد با عجله از اطاق اومد بیرون همینطور که از پله ها میدوید هول شد پاش سر خورد با کله اومد پایین. نمیدونم چرا تکون نمیخوره دیگه؟!\r\nخوب عمو حسن چی؟\r\n- عمو حسن از پنجره پرید توی استخر. ولی پریروز آب استخر رو خودت خالی کرده بودی یک صدای بامزه ای داد نگو! هنوز همونطور خوابیده!\r\nاستخر؟ کدوم استخر؟ ببینم شماره پلاک 23 نیست؟\r\n! نه \r\nببخشید مثل اینکه اشتباه گرفتم\r\n"},{"id":917,"category_id":7,"category_code":"s7","source_id":87,"title":"کله پاچه ","content":"روزی مردی پسر کوچکش را به بازار فرستاد تا کله‌ی پخته‌ی گوسفند بخرد و به خانه بیاورد. کودک کله را خرید اما بوی خوش آن برای کودک گرسنه قابل تحمل نبود، پس به گوشه‌ای رفت و گوشت و مغز و چشم و زبان آن را خورد و بعد استخوان‌های آن را در نان پیچید و با خود به خانه آورد. وقتی پدر نان را گشود و با استخوان‌های سر گوسفند رو به رو شد به پسر گفت:\r\nچشم‌های او کجاست؟\r\nکودک گفت: این گوسفند کور بوده است!\r\nزبان او کجاست؟\r\nاین گوسفند لال بوده است!\r\nـ هرچه می‌گویی قبول، اما مغز او کجاست؟\r\nـ این گوسفند مغزش را در آموزش به گوسفندهای دیگر از دست داده است.\r\nپدر در حالی که استخوان‌ها را دوباره در نان می‌پیچید به پسر گفت: برخیز،برخیز و به دکان کله‌پز برو، و بگو که من این کله را نمی‌خواهم. کودک گفت: او این کله را از من پس نخواهد گرفت، زیرا آن را با تمام عیب‌هایش به من فروخته است!\r\n"},{"id":918,"category_id":7,"category_code":"s7","source_id":88,"title":"متقاضی کار ","content":"مسئول تست کردن شراب های يک شرابسازی می ميرد، مدير کارخانه شرابسازی دنبال يک مسئول تست ديگر می گردد تا استخدام کند. يک فرد مست با لباس ژنده و پاره برای گرفتن شغل درخواست می دهد. مدير کارخانه فکر می کند چطور اورا رد کند.* *اورا تست می کنند. به او يک گيلاس شراب می دهند و می خواهند که آنرا تست کند آزمايش می کند و می گويد شراب قرمز، مسکات، سه ساله، و در بخش شمالی تپه رشد کرده و در ظرف فلزی عمل آمده است* *مدير شرابسازی می گويد درست است گيلاس ديگری به او می دهند  اين يکی شراب قرمز کابرانه هشت ساله و در بخش جنوبی تپه رشد کرده و در چليک چوبی عمل آمده است درست است. مدير موسسه که متعجب شده است با چشمکی به منشی پيشنهادی میکند. او يک گيلاس ادرار می آورد. فرد الکلی آنرا آزمايش می کند. و می گويد* *بلوند، 26 ساله، سه ماهه حامله است و اگر کار را به من ندهيد نام پدر بچه را هم خواهم گفت."},{"id":919,"category_id":7,"category_code":"s7","source_id":89,"title":"بی پولی","content":"سه تا رفیق با هم میرن رستوران ولی بدون یه قرون پول . هر کدومشون یه جایی میشینن و یه دل سیر غذا میخورن .\r\nاولی میره پای صندوق و میگه : ممنون غذای خوبی بود این بقیه پول مارو بدین بریم : صندوقدار : کدوم بقیه آقا ؟ شما که پولی پرداخت نکردی . میگه یعنی چی آقا خودت گفتی الان خورد ندارم بعد از صرف غذا بهتون میدم. \r\nخلاصه از اون اصرار از این انکار که دومی پا میشه و رو به صندوقدار میگه : آقا راست میگن دیگه ، منم شاهدم وقتی من میزمو حساب کردم ایشون هم حضور داشتن و یادمه که بهش گفتین بقیه پولتونو بعدا میدم. \r\nصندوقداره از کوره در رفت و گفت : شما چی میگی آقا ، شما هم حساب نکردی!\r\nبحث داشت بالا میگرفت که دیدن سومی نشسته وسط سالن و هی میزنه توی سرش . ملت جمع شدن دورش و گفتن چی شده ؟\r\nگفت : با این اوضاع حتما میخواد بگه منم پول ندادم :خخخ\r\n\r\n"},{"id":920,"category_id":7,"category_code":"s7","source_id":90,"title":"طبیعت ","content":"جاسم واسه رفیقش تعریف میکرد که …حمیــــد...!! \r\nحمید : چیه؟\r\nگفت: رفته بودم جنگل , چه طبیعت بکری !! ایقد جات خالی بوود ایقد جات خالی بود!!واساده بودم محو این طبیعت شده بودم ! اینقد قشنگ بود آواز پرندگان !کاش مو این دوربینمو برده بودم با خودم برات فیلم برداری میکردم !همینطور که مو مهو این طبیعت بودم یه گله گرگ به مو حمله کردن!! \r\nحمید : خو چی شد؟\r\nگفت : خو هیچی ما بدو گرگا بدو ! مو بدو گرگا بدو !! ب…عد ر…سیدیم به یه دشت دشت پر از گل شقایق ! ایقد قشنگ بود , تا چشم کار میکرد فقط گل سرخ ! اصلا یه فضای رمانتیکی شده بود. \r\nحمید : پَ گرگا چی شدن ؟\r\nگفت : ها وولک گرگا دنبالم ! مو بدو گرگا بدو !! رسیدیم به یه کوه !پسر از قدرت خدا آب از دل کوه در میومد میخورد زمین پووووودر می شد !!نور خورشیدم افتاده بود داخلش یه رنگین کمون خشکلی درست شدهبود جات خالیکاش مو این دوربینمو با خودم برده بودم واست فیلم میگرفتم \r\nحمید : گرگا چی شدن وولک؟\r\nگفت: هااا خو گرگا دنبالمون مو بدو گرگا بدو مو بدو گرگا بدوو ! رسیدیم به یه دریا !پسر دریا نگو استخر ! یه موج داخلاین دریا نبود ! ایقد قشنگ بووود \r\nحمید :گرگااا چی شدن؟\r\nگفت : خو زهر مار !!! گرکا ول کردن تو ول نمیکنی\r\n"},{"id":921,"category_id":7,"category_code":"s7","source_id":91,"title":"مرور خاطرات ","content":"زن نصف شب از خواب بیدار می‌‌شود و می‌‌بیند که شوهرش در رختخواب نیست، ربدشامبرش را می‌‌پوشد و به دنبال او به طبقه ی پایین می‌‌رود،و شوهرش در آشپزخانه نشست بود در حالی‌ که یک فنجان قهوه هم روبرویش بود . در حالی‌ که به دیوار زل زده بود در فکری عمیق فرو رفته بود...  \r\nزن او را دید که اشک‌هایش را پاک می‌‌کرد و قهوه‌اش را می‌‌نوشید... \r\nزن در حالی‌ که داخل آشپزخانه می‌‌شد آرام زمزمه کرد : \"چی‌ شده عزیزم؟ چرا این موقع شب اینجا نشستی؟\"  \r\nشوهرش نگاهش را از قهوه‌اش بر می‌‌دارد و میگوید : هیچی‌ فقط اون موقع هارو به یاد میارم، ۲۰ سال پیش که تازه همدیگرو ملاقات می‌‌کردیم، یادته؟ \r\nزن که حسابی‌ تحت تاثیر احساسات شوهرش قرار گرفته بود، چشم‌هایش پر از اشک شد و گفت: \"آره یادمه...\"  \r\nشوهرش به سختی‌ گفت: \r\n_ یادته که پدرت ما رو وقتی‌ که رو صندلی عقب ماشین بودیم پیدا کرد؟  \r\n)_آره یادمه (در حالی‌ که بر روی صندلی‌ کنار شوهرش نشست \r\n_یادته وقتی‌ پدرت تفنگ رو به سمت من نشون گرفته بود و گفت که یا با دختر من ازدواج میکنی‌ یا ۲۰ سال می‌‌فرستمت زندان ؟!  \r\n..._آره اونم یادمه  \r\nمرد آهی می‌‌کشد و می‌‌گوید: اگه رفته بودم زندان الان آزاد شده بودم.\r\n"},{"id":922,"category_id":7,"category_code":"s7","source_id":92,"title":"غول چراغ جادو ","content":"یه روز مسوول فروش، منشی دفتر، و مدیر شرکت برای ناهار به سمت سلف قدم می زدند.\r\n یهو یه چراغ جادو روی زمین پیدا می کنن و روی اون رو مالش میدن و جن چراغ ظاهر میشه... جن میگه: من برای هر کدوم از شما یک آرزو برآورده می کنم...\r\nمنشی می پره جلو و میگه: «اول من، اول من!... من می خوام که توی باهاماس باشم، سوار یه قایق بادبانی شیک باشم و هیچ نگرانی و غمی از دنیا نداشته باشم»... پوووف! منشی ناپدید میشه.\r\nبعد مسوول فروش می پره جلو و میگه: «حالا من، حالا من!... من می خوام توی هاوایی کنار ساحل لم بدم، یه ماساژور شخصی و یه منبع بی انتهای آبجو داشته باشم و تمام عمرم حال کنم»... پوووف! مسوول فروش هم ناپدید میشه...\r\nبعد جن به مدیر میگه: حالا نوبت توئه... مدیر میگه: «من می خوام که اون دو تا هر دوشون بعد از ناهار توی شرکت باشن! \r\nنتیجهء اخلاقی اینکه همیشه اجازه بده که رئیست اول صحبت کنه.\r\n"},{"id":923,"category_id":7,"category_code":"s7","source_id":93,"title":"عاشق ","content":"خيلي تو خودش بود، آخرش دلم را زدم به دريا و گفتم: تو هيچ عاشق شدي؟\r\nگفت: آره\r\nگفتم: چند بار؟ \r\nگفت: خيلي. گفتم: مگر سر مي بري؟ \r\nگفت: يكبار\r\nگفتم: چه حسي داشتي؟ \r\nگفت: عشق حس نيست، باوره، مكتبه، بودنه \r\nگفتم: اينا را كه گفتي يعني چي؟\r\nگفت: تا حالا سوار قطار شدي؟ \r\nآره\r\nديدي يكي ترمز قطار را بكشد؟\r\nآره\r\nبه اون ميگن عشق!\r\nگفتم: يعني عشق ترمز قطاره؟ گفت: نه بابا! تو چقدر پرتي، يه جور گير كردنه\r\nگفتم: يعني آدم به هر چيزي گير بكند عاشق شده؟ \r\nگفت: ببين! اصلاً قطار و گير كردنو ول كن، ببين عشق يه لحظه واقعاً نابه، كه تو زندگي هر كسي در يك لحظه ي خاص پيش مي آيد مثلاً همين ازدواج، ديدي بعضي ها مي گويند: طرف را ديدم يك دل نه صد دل عاشقش شدم.\r\nخب منظور؟\r\n_ ببين وقتي آدم عاشق مي شه قلبش يا كند يا مي ايسته، صداش در نمياد، چشماش مي خواد از حدقه بيرون بزند و... \r\nگفتم: يعني وقتي آدم اينطوري بشه، عاشق شده؟\r\nبا بي حوصلگي گفت: آره.\r\nآن شب سر ميز غذا وقتي غذا تو گلويم گير كرد و بسوي دستشويي دويدم، وقتي خودم را در آينه ديدم فهميدم عاشق شدم. به خودم گفتم: بعضي ها عجب بد سليقه اند، به چي ميگن عشق؟\r\n"},{"id":924,"category_id":7,"category_code":"s7","source_id":94,"title":"سوال پسر ","content":"روزی ، یک پدر روستایی با پسر پانزده اش وارد یک مرکز تجاری میشوند. پسر متوجه دو دیوار براق نقره‌ای رنگ میشود که بشکل کشویی از هم جدا شدند و دو باره بهم چسبیدند، از پدر می پرسد، این چیست؟ پدر که تا بحال در عمرش آسانسور ندیده است، می گوید:\r\nپسرم، من تا کنون چنین چیزی ندیده ام.\r\nدر همین موقع آنها زنی بسیار چاق را میبینند که با صندل چرخدارش به آن دیوار نقره‌ای نزدیک شد و با انگشتش چیزی را روی دیوار فشار دادو دیوار براق از میان جدا شد و آن زن خود را بزحمت وارد اتاقکی کرد. دیوار بسته شدو پدر و پسرهر دو چشمشان به شماره هائی بر بالای آسانسور افتاد که از یک شروع و بتدریج تا سی‌ رفت، هر دو خیلی‌ متعجب تماشا میکردند که ناگهان دیدند شماره‌ها بطور معکوس و بسرعت کم شدند تا رسید به یک، در این وقت دیوار نقره‌ای باز شد و آنها حیرت زده دیدند دختـر خانمی مو طلایی و بسیار زیبا و ظریف ، با طنازی از آن اتاقک خارج شد\r\nپدر در حالی که نمی توانست چشم از آن دختر بردارد، رو به پسرش کرد و گفت: پسرم ، زود برو مادرت را بیاور اینجا!\r\n"},{"id":925,"category_id":7,"category_code":"s7","source_id":95,"title":"گمشده ","content":"روزی رییس یک شرکت بزرگ به دلیل یک مشکل اساسی در رابطه با یکی از کامپیوترهای اصلی مجبور شد با منزل یکی از کارمندانش تماس بگیرد.\r\nبنابراین، شماره منزل او را گرفت.\r\nکودکی به تلفن جواب داد و نجوا کنان گفت: سلام\r\nرییس پرسید: بابا خونس؟\r\nصدای کوچک نجواکنان گفت: بله\r\nمی تونم با او صحبت کنم؟\r\nکودکی خیلی آهسته گفت: نه\r\n- رییس که خیلی متعجب شده بود و می خواست هر چه سریع تر با یک بزرگسال صحبت کند، گفت: مامانت اونجاس؟\r\nبله\r\nمی تونم با او صحبت کنم؟\r\nدوباره صدای کوچک گفت: نه\r\n- رییس به امید این که شخص دیگری در آنجا باشد که او بتواند حداقل یک پیغام بگذارد پرسید: آیا کس دیگری آنجا هست؟\r\nکودک زمزمه کنان پاسخ داد: بله، یک پلیس\r\n- رییس که گیج و حیران مانده بود که یک پلیس در منزل کارمندش چه می کند، پرسید: آیا می تونم با پلیس صحبت کنم؟\r\nکودک خیلی آهسته پاسخ داد: نه، او مشغول است؟\r\nـ مشغول چه کاری است؟\r\nکودک همان طور آهسته باز جواب داد: مشغول صحبت با مامان و بابا و آتش نشان\r\n- رییس که نگران شده بود و حتی نگرانی اش با شنیدن صدای هلی کوپتری از آن طرف گوشی به دلشوره تبدیل شده بود پرسید: این چه صدایی است؟\r\nصدای ظریف و آهسته کودک پاسخ گفت: یک هلی کوپتر\r\nرییس بسیار آشفته و نگران پرسید: آنجا چه خبر است؟\r\nکودک با همان صدای بسیار آهسته که حالا ترس آمیخته به احترامی در آن موج می زد پاسخ داد: گروه جست و جو همین الان از هلی کوپتر پیاده شدند\r\n- رییس که زنگ خطر در گوشش به صدا درآمده بود، نگران و حتی کمی لرزان پرسید: آنها دنبال چی می گردند؟\r\nکودک که همچنان با صدایی بسیار آهسته و نجواکنان صحبت می کرد با خنده ریزی پاسخ داد: من\r\n"},{"id":926,"category_id":7,"category_code":"s7","source_id":96,"title":"مغز بادام","content":"تعدادى پیرزن با اتوبوس عازم تورى تفریحى بودند. پس از مدتى یکى از پیرزنان به پشت راننده زد و یک مشت بادام به او تعارف کرد.\r\nراننده تشکر کرد و بادام‌ها را گرفت و خورد. در حدود ۴۵ دقیقه بعد دوباره پیرزن با یک مشت بادام نزد راننده آمد و بادام‌ها را به او تعارف کرد. \r\nراننده باز هم تشکر کرد و بادام‌ها را گرفت و خورد.این کار دوبار دیگر هم تکرار شد تا آن که بار پنجم که پیرزن باز با یک مشت بادام سراغ راننده آمد، راننده از او پرسید چرا خودتان بادام‌ها را نمى‌خورید؟ \r\nپیرزن گفت چون ما دندان نداریم. راننده که خیلى کنجکاو شده بود پرسید پس چرا آن‌ها را خریده‌اید؟ پیرزن گفت ما شکلات روى بادام‌ها را خیلى دوست داریم.\r\n"},{"id":927,"category_id":7,"category_code":"s7","source_id":97,"title":" آسمان شب","content":"شرلوک هولمز کارآگاه معروف و معاونش واتسون رفته بودند صحرا نوردی و شب هم چادری زدند و زیر آن خوابیدند. نیمه های شب هولمز بیدار شد و آسمان رانگریست. بعد واتسون را بیدار کرد و گفت: نگاهی به آن بالا بینداز و به من بگو چه می بینی؟\r\nواتسون گفت: میلیونها ستاره می بینم. \r\nهولمز گفت: چه نتیجه میگیری؟\r\nواتسون گفت: از لحاظ روحانی نتیجه می گیرم که خداوند بزرگ است و ما چقدر در این دنیا حقیریم.\r\nاز لحاظ ستاره شناسی نتیجه می گیریم که ماه در برج مشتری است، پس باید اوایل تابستان باشد.\r\nاز لحاظ فیزیکی، نتیجه میگیریم که مریخ در موازات قطب است، پس ساعت باید حدود سه نیمه شب باشد.\r\nشرلوک هولمز قدری فکر کرد و گفت: واتسون تو احمقی بیش نیستی. نتیجه اول و مهمی که باید بگیری اینست که چادر ما را دزدیده اند!!\r\n"},{"id":928,"category_id":7,"category_code":"s7","source_id":98,"title":"دستشویی","content":"من تقریباً تو دستشویی نشسته بودم که از دستشویی کناری صدایی شنیدم که گفت :سلام حالت خوبه ؟\r\nمن اصلاً عادت ندارم که تو دستشویی مردانه هر کی رو که پیدا کردم شروع کنم به حرف زدن باهاش ، اما نمی دونم اون روز چم شده بود که پاسخ واقعاً خجالت آوری دادم ؛ \r\n- حالم خیلی خیلی توپه\r\nبعدش اون آقاهه پرسید ؛\r\n- خوب چه خبر ؟ چه کار می خوای بکنی ؟\r\nبا خودم گفتم ، این دیگه چه سؤالی بود ؟ اون موقع فکرم عجیب ریخت به هم برای همین گفتم ؛\r\n- اُه منم مثل خودت فقط داشتم از اینجا می گذشتم\r\nوقتی سؤال بعدی شو شنیدم ، دیدم که اوضاع داره یه جورایی ناجور میشه ، به هر ترفندی بود خواستم سریع قضیه رو تموم کنم ؛\r\n- منم می تونم بیام طرفت ؟\r\nآره سؤال یه کمی برام سنگین بود . با خودم فکر کردم که اگه مؤدب باشم و با حفظ احترام صحبت مون رو تموم کنم ، مناسب تره ، بخاطر همین بهش گفتم ؛\r\n! نه الآن یکم سرم شلوغه \r\nیک دفعه صدای عصبی فردی رو شنیدم که گفت: \r\n- ببین. من بعداً باهات تماس می گیرم . یه احمقی داخل دستشویی بغلی همش داره به همه سؤال های من جواب می ده !!! ول کن هم نیست.\r\n"},{"id":929,"category_id":7,"category_code":"s7","source_id":99,"title":"جایزه ","content":"خواهر روحانی در کلاس مدرسه مقابل دانش آموزان نوجوان، ایستاده بود. او در حالی که یک سکه یک دلاری نقره در دستش بود گفت: به دختر یا پسری که بتواند نام بزرگترین مردی را که در این دنیا زیسته است بگوید، این یک دلاری را جایزه می دهم.\r\nیک پسر خردسال ایتالیایی گفت: منظورتان میکل آنژ نیست؟\r\nخواهر روحانی جواب داد: خیر، میکل آنژ یک هنرمند برجسته به حساب می آید، لکن بزرگترین مردی که دنیا به خود دیده نیست.\r\nیک دختر خردسال یونانی گفت: آیا ارسطو بود؟\r\nخواهر روحانی جواب داد: خیر، ارسطو یک متفکر بزرگ و پدر علم منطق بود اما بزرگترین مردی که در دنیا زندگی می کرده، محسوب نمی شود.\r\nبالاخره یک پسر خردسال یهودی گفت: می دانم چه کسی است، او عیسی مسیح است.\r\nخواهر روحانی جواب داد صحیح است و یک دلاری را به او داد.\r\nخواهر روحانی که از جواب پسربچه یهودی قدری شگفت زده شده بود، در زنگ تفریح او را در زمین ورزش یافت و از او پرسید: آیا واقعا اعتقاد داری که عیسی مسیح بزرگترین مردی است که دنیا به خود دیده ؟\r\nپسربچه جواب داد: البته نه، هر کسی می داند که بزرگترین مرد موسی بود. اما معامله شوخی بردار نیست!\r\nبه نقل از کتاب بزرگترین اصل مدیریت در دنیا نوشته مایکل لوبوف\r\n"},{"id":930,"category_id":7,"category_code":"s7","source_id":100,"title":"بهترین داماد ","content":"\r\nزنى سه دختر داشت که هر سه ازدواج کرده بودند.\r\nیکروز تصمیم گرفت میزان علاقه‌اى که دامادهایش به او دارند را ارزیابى کند. \r\nیکى از دامادها را به خانه‌اش دعوت کرد و در حالى که در کنار استخر قدم مى‌زدند از قصد\r\nوانمود کرد که پایش لیز خورده و خود را درون استخر انداخت.\r\nدامادش فوراً شیرجه رفت توى آب و او را نجات داد. \r\nفردا صبح یک ماشین پژو ٢٠٦ نو جلوى پارکینگ خانه داماد بود و روى شیشه‌اش نوشته بود: \"متشکرم! از طرف مادر زنت\" \r\nزن همین کار را با داماد دومش هم کرد و این بار هم داماد فوراً شیرجه رفت توى آب وجان زن را نجات داد. \r\nداماد دوم هم فرداى آن روز یک ماشین پژو ٢٠٦ نو هدیه گرفت که روى شیشه‌اش نوشته بود: \"متشکرم! از طرف مادر زنت\"\r\nنوبت به داماد آخرى رسید. \r\nزن باز هم همان صحنه را تکرار کرد و خود را به داخل استخر انداخت. \r\nامّا داماد از جایش تکان نخورد.\r\nاو پیش خود فکر کرد وقتش رسیده که این پیرزن از دنیا برود پس چرا من خودم را به خطر بیاندازم.\r\nهمین طور ایستاد تا مادر زنش درآب غرق شد و مرد.\r\nفردا صبح یک ماشین بى‌ام‌و کورسى آخرین مدل جلوى پارکینگ خانه داماد سوم بود که روى شیشه‌اش نوشته بود: \"متشکرم! از طرف پدر زنت\"\r\n"},{"id":931,"category_id":7,"category_code":"s7","source_id":101,"title":"راز راهب","content":"یه روز یه دختر جوون سوار اتوبوس شد و کنار یک راهب با خدا و زیبا نشست...\r\nخیلی بی ادبانه و با تکبری خاص و بی مقدمه ازآن مرد با دین خواست که باهاش رابطه داشته باشه.\r\n"},{"id":932,"category_id":7,"category_code":"s7","source_id":102,"title":"دو دوست","content":"\r\nدو دوست که مدتی بود همدیگر را ندیده بودند به هم دیگر می رسند.\r\nاولی: خوب دوست عزیز بگو ببینم چه کار می کنی؟\r\nدومی: کاری نمی کنم فقط پارسال عروسی کردم.\r\nاولی: خوب، تبریک عرض میکنم.\r\nدومی: تبریک نگو چون زنم از اون آتیش پاره هاست!\r\nاولی: پس خیلی متأسفم.\r\nدومی: زیاد هم متأسف نباش، چون از اون پولداراست...!\r\nاولی: پس بهت تبریک عرض میکنم.\r\nدومی: نه، تبریک نگو، چون همه ی پولهاشو خرج کردیم و تموم شد...!\r\nاولی: پس خیلی برات متأسفم.\r\nدومی: نه، زیاد هم تأسف نداره، چون با مقداری از پولها یک خونه خریدیم.\r\nاولی: آه، پس بهت تبریک عرض می کنم\r\nدومی: نه تبریک نداره چون خونه آتیش گرفت.\r\nاولی: إ ، پس خیلی متأسفم.\r\nدومی: نه، متأسف نباش چون زنمنم تو همون خونه بود!\r\n"},{"id":933,"category_id":7,"category_code":"s7","source_id":103,"title":"راز ساعتها ","content":"\r\nفرد دروغگویی می میرد و به جهان آخرت می رود.\r\nدر آنجا مقابل دروازه های بهشت می ایستد سپس دیوار بزرگی می بیند که ساعت های مختلفی\r\nروی آن قرار گرفته بود.\r\nاز یکی از فرشتگان می پرسد:\r\nاین ساعت ها برای چه اینجا قرار گرفته اند؟ فرشته پاسخ می دهد:\r\nاین ساعت ها ساعت های دروغ سنج هستند و هر کس روی زمین یک ساعت دروغ سنج دارد\r\nو هر بار آن فرد یک دروغ بگوید عقربه ساعت یک درجه جلوتر می رود.\r\nمرد گفت:\r\nچه جالب آن ساعت کیه؟! فرشته پاسخ داد: مادر ترزا، او حتی یک دروغ هم نگفته بنابراین ساعتش اصلا حرکت نکرده است.\r\nمرد دوباره گفت:\r\nوای باور کردنی نیست، خوب آن یکی ساعت کیه؟ فرشته پاسخ داد: ساعت آبراهام لینکلن (رئیس جمهور سابق آمریکا) عقربه اش دوبار تکان خورد!\r\nفرشته گفت:\r\nخیلی جالبه راستی ساعت من کجاست؟ فرشته پاسخ داد: آن در اتاق کار سرپرست فرشتگان است.\r\nو از آن بعنوان پنکه سقفی استفاده می کنند.\r\n"},{"id":934,"category_id":7,"category_code":"s7","source_id":104,"title":" سقوط هدفمند","content":"کسی پیش وزیر نظام(امیرکبیر)حاکم تهران شکایت برد که فلانی ملک مرا غصب کرده است.\r\nان روزها هنوز املاک ثبت نشده بود غاصبین وگردن کلفت ها املاک دیگران را به زور میگرفتند ومی گفتند:ازاسمان افتاده ام!!\r\nوزیر نظام به دنبال غاصب فرستاد وچون اورا اوردند گفت:ازاسمان افتاده ام روی زمین این اقا!\r\nوزیر نظام اشاره کرد که چوب وفلک بیاوردند وغاصب را به چوب بست انقدر زدنش که فریادش به اسمان رفت وزیر گفت: \r\nهرچه بگوید همان است از اسمان افتاده باید صدایش به اسمان باز گردد\r\n"},{"id":935,"category_id":7,"category_code":"s7","source_id":105,"title":"بیمار روانی","content":"فرهاد و هوشنگ هر دو بیمار یک آسایشگاه روانى بودند. یکروز همینطور که در کنار استخر قدم مى زدند فرهاد ناگهان خود را به قسمت عمیق استخر انداخت و به زیر آب فرو رفت. هوشنگ فوراً به داخل استخر پرید و خود را در کف استخر به فرهاد رساند و او را از آب بیرون کشید.\r\nوقتى دکتر آسایشگاه از این اقدام قهرمانانه هوشنگ آگاه شد، تصمیم گرفت که او را ازآسایشگاه مرخص کند.\r\nهوشنگ را صدا زد و به او گفت: من یک خبر خوب و یک خبر بد برایت دارم. خبر خوب این است که مى توانى از آسایشگاه بیرون بروى، زیرا با پریدن در استخر و نجات دادن جان یک بیمار دیگر، قابلیت عقلانى خود را براى واکنش نشان دادن به بحرانها نشان دادى و من به این نتیجه رسیدم که این عمل تو نشانه وجود اراده و تصمیم در توست.  \r\nو اما خبر بد این که بیمارى که تو از غرق شدن نجاتش دادى بلافاصله بعد از این که از استخر بیرون آمد خود را با حوله حمامش دار زده است و متاسفانه وقتى که ما خبر شدیم او مرده بود.\r\nهوشنگ که به دقت به صحبتهاى دکتر گوش مى کرد گفت: او خودش را دار نزد. من آویزونش کردم تاخشک بشه...\r\nحالا من کى مى تونم برم خونه‌مون ؟\r\n"},{"id":936,"category_id":7,"category_code":"s7","source_id":106,"title":"مراحل ازدواج","content":"گویند: پسری قصد ازدواج داشت. پدرش گفت: بدان که ازدواج سه مرحله دارد. مرحله اول ماه عسل است که در آن تو صحبت می کنی و زنت گوش می دهد. مرحله دوم او صحبت می کند و تو گوش می کنی. و اما مرحله سوم که خطرناکترین مرحله است و آن موقع است که هر دو بلند بلند داد می زنید و همسایه گوش می کند!"},{"id":937,"category_id":7,"category_code":"s7","source_id":107,"title":"پیراهن قرمز","content":"\r\nدر ایام قدیم یه کشتی باری بود که ناخدای شجاعی داشت.\r\nیک روز دزدان دریایی به کشتی حمله کردند.\r\nناخدا گفت : اون پیراهن قرمز منو بیارید. \r\nپیراهن رو پوشید و در کنار ملوانانش مردانه جنگید و دزدان را فراری داد.\r\nاز او فلسفه پیراهن قرمز را پرسیدند.\r\nگفت: برای این است که اگر من زخمی شدم و خونریزی کردم، شما نفهمید و روحیه تان را از دست ندهید.\r\nچند بار دیگر هم همین اتفاق افتاد و هر بار دزدان در مصاف با کاپیتان پیراهن قرمز شکست می خوردند.\r\nیک روز دیده بان گفت : 10 تا کشتی دزدان همزمان به ما حمله کرده اند.\r\nهمه وحشت کردند یکی دوید تا پیراهن قرمز کاپیتان را بیاورد.\r\nکاپیتان که این دفعه حسابی ترسیده بود گفت: پیراهن قرمز لازم نیست،\r\nاون شلوار قهوه ای منو بیارید!!\r\n"},{"id":938,"category_id":7,"category_code":"s7","source_id":108,"title":"وقت استراحت ","content":"\r\nیكی از دانشجوهای پسر : استاد\r\n. نمیدین ؟ فوتبال تیم دانشكده است . می خوایم بریم تشویق كنیم استراحت\r\nاستاد: چرا ، خیلی هم خوبه . میریم اونجا هم تشویق می كنیم و هم بستنی هائی كه براتون خریدم رو میخوریم ( قضیه بستنی تو حاشیه است) \r\nیكی از دانشجوهای دختر : استاد پس ما تو این نیم ساعت ، ۴۵ دقیقه چی كار كنیم \r\nاستاد ( كه معمولا در ۱۰۱% موارد حرف واسه گفتن كم نمیاره) : خوب شما برید ….. برید قلاب بافی. \r\nكلاس می تركه . پسرها با تمام وجودشون كف میزنن ( آخه این پسرهای بیچاره دنبال موقعیت میگردن كه اظهار وجود كنند) \r\nبعد از كلاس: \r\nدختر : چرا ؟\r\nپسر : چرا چی ؟\r\nدختر : هیچی ؟\r\nپسر : نه بگو \r\nدختر : چرا وقتی استاد این حرف رو زد پسرها “ذوق مرگ” شدن ؟\r\nپسر : هاااااااا ، خوب به خاطر این كه شما دختر ها رو ساختن واسه قلاب بافی و كوبلن دوزی و آشپزی و... \r\nدختر : شما پسرها رو واسه چه كاری ساختن ؟\r\nپسر : واسه كارهای مردونه \r\nدختر : مثل حمالی ؟!!!\r\nپسر : نه خیرم . مثل درس خوندن . مثل ورزش كردن . مثل كار كردن \r\nدختر : وا . خوب ما دخترها هم كه كنار شما درس می خونیم . ورزش می كنیم . كار می كنیم. \r\nپسر : هااااااااااا ، خوب ببین این یكی از ” مشكلات ” جامعه ی مدرنیزه ی امروزه. \r\nدختر : پس تو با مدرنیزه شدن مخالفی ؟ (اولین سوتی یه پسر)\r\nپسر : ببین چیزه ……. تو نظرت راجع به اینكه میگن دخترا یه دنده شون كمه چیه ؟ ( توجه كنید كه پسر از اهرم تحریك دختر استفاده كرد هم چنین به شیوه ای به ظاهر هوشمندانه بحث رو به نفع خودش عوض كرد. ولی...) \r\nدختر : خوب این خیلی مشكل خاصی نیست . حالا جدا از اثبات نادرستی یه علمی یه این قضیه ( دومین سوتی یه پسر) ، دخترباشی و یه دنده ات كم باشه بهتر از اینه كه پسر باشی و یه تخته ات كم باشه!! \r\nپسر : میگم بی خیال بابا . جدی گرفتی. \r\nدختر : ترجیح میده فقط نیگا كنه حرفی نزنه. \r\nپسر : یه چیز دیگه یادم اومد ( بیچاره پسرها در این جور بحث ها خیلی به خودشون فشار میارن)\r\nدختر : چی ؟\r\nپسر : این كه خدا زن رو از دنده ی چپ مرد آفریده . دیگه اون موقع كه كسی نبوده كه بخواد حالا ثابت كنه این غلطه. \r\nدختر : خوب گیریم كه درسته . خدا همه كاراش رو حساب كتابه . زن رو از دنده ی چپ مرد آفریده كه در هر صورتی بتونه حال مرد رو بگیره و بكنه تو شیشه!! \r\nخوب دیگه اینجا پسر حالش گرفته شده ( به بیانی بهتر له شده ) ، ترجیح میده به گفتن این جمله كفایت كنه : من گشنمه . بریم یک چیزی بخوریم.\r\n"},{"id":939,"category_id":7,"category_code":"s7","source_id":109,"title":"انواع استرس ","content":"در کلاس درس استاد دانشگاه خطاب به یکی از دانشجویان میگه انواع استرس رو توضیح بده و استرس واقعی کدومه دانشجو میگه دختر زیبائی رو کنار خیابان سوار میکنی. اما دختره کمی بعد توی ماشینت غش می کنه. مجبور می شی اونو به بیمارستان برسونی. در این لحظه دچاراسترس آنهم از نوع ساده‌ میشی!در بیمارستان به شما می گن که این خانم حامله هست و به تو تبریک میگن که بزودی پدر میشی. تو میگی اشتباه شده من پدر این بچه نیستم ولی دختر با ناله ای میگه چرا هستی. در اینجا مقدار استرس شما بیشتر میشه. آن هم از نوع هیجانی!در خواست آزمایش دی.ان.ای می کنی. \r\nآزمایش انجام میشه و دکتر به شما میگه : دوست عزیز شما کاملا بیگناهی ، شما قدرت باروری ندارید و این مشکل شما کاملا قدیمی و بهتر بگویم مادرزادیه. خیال تو راحت میشه و سوار ماشینت میشی و میری. توی راه به سمت خونه ناگهان به یاد ۳ تا بچه ت میفتی و اینجاست که استرس واقعی شروع میشه...!\r\n"},{"id":940,"category_id":7,"category_code":"s7","source_id":110,"title":"نژاد انسانها ","content":"روزی دخترک از مادرش پرسید: 'مامان نژاد انسان ها از کجا اومد؟مادر جواب داد: خداوند آدم و حوا را خلق کرد. اون ها بچه دار شدند و این جوری نژادانسان ها به وجود اومد.\r\nدو روز بعد دختر همین سوال رو از پدرش پرسید.\r\nپدرش پاسخ داد: 'خیلی سال پیش میمون ها تکامل یافتند و نژاد انسان ها پدید اومد.\"\r\nدخترک که گیج شده بود نزد مادرش رفت و گفت:مامان تو گفتی خدا انسان ها روآفرید ولی بابا میگه انسان ها تکامل یافته ی میمون ها هستند...من که نمی فهمم!\r\nمادرش گفت: عزیز دلم خیلی ساده است. من بهت در مورد خانواده ی خودم گفتم و بابات درمورد خانواده ی خودش!\r\n"},{"id":941,"category_id":7,"category_code":"s7","source_id":111,"title":"حواله ی روزی ","content":"یک شب نصرت رحمانی وارد کافه نادری شد و به اخوان ثالث گفت : من همین حالا سی تومن پول احتیاج دارم . اخوان جواب داد : من پولم کجا بود ؟ برو خدا روزی ات را جای دیگری حواله کند. نصرت رحمانی رفت و بعد از مدتی بر گشت و بیست تومان پول و یک خودکار به اخوان داد . اخوان گفت این پول چیه ؟\r\nتو که پول نداشتی . نصرت رحمانی گفت : از دم در ؛ پالتوی تو رو ورداشتم بردم پنجاه تومن فروختم . چون بیش از سی تومن لازم نداشتم ؛ بگیر ؛ این بیست تومن هم بقیه پولت ! ضمنا، این خودکار هم توی پالتوت بود.\r\n"},{"id":942,"category_id":7,"category_code":"s7","source_id":112,"title":"بالا و پایین ","content":"\r\nدکتر بعد از معاینه و دیدن آزمایشات بیمار میگه: پدر جان ، شما بیماری قلبی دارین \r\nداروهایی رو که براتون نوشتم مصرف کنید.\r\nسعی کنید استراحت داشته باشید. \r\nبه خصوص از پله بالا و پایین نرید . سه ماه دیگه هم بیاید من ببینمتون .سه ماه بعد که بیمار میره پیش دکتر.دکتر دوباره آزمایشش میکنه و میگه: تبریک میگم ، وضع قلبتون خیلی بهتره.طرف میگه: یعنی حالا میتونم از پله بالا و پایین برم.دکتره میگه: البته.طرف می پره هوا و میگه: خدا خیرتون بده آقای دکتر، پدرم در اومد از بسکه توی این سه ماه از ناودون رفتم بالا واز پنجره پریدم پایین!!\r\n"},{"id":943,"category_id":7,"category_code":"s7","source_id":113,"title":"زود باور","content":"دانشجویی که سال آخر دانشگاه را می گذراند به خاطر پروژه ای که انجام داده بود جایزه اول را گرفت. او در پروژه خود از ۵۰ نفر خواسته بود تا دادخواستی مبنی بر کنترل سخت و یا حذف ماده شیمیایی «دی هیدروژن مونوکسید» توسط دولت را امضا کنند و برای این خواسته خود دلایل زیر را عنوان کرده بود:\r\n.  مقدار زیاد آن باعث عرق کردن زیاد و استفراغ می شود\r\nیک عنصر اصلی باران اسیدی است.\r\nوقتی به حالت گاز در می آید بسیار سوزاننده است.\r\nاستنشاق تصادفی آن باعث مرگ فرد می شود.\r\nباعث فرسایش اجسام می شود.\r\nحتی روی ترمز اتوموبیل ها اثر منفی می گذارد.\r\nحتی در تومورهای سرطانی نیز یافت شده است.\r\nاز ۵۰ نفر فوق ۴۳ نفر دادخواست را امضا کردند. ۶ نفر به طور کلی علاقه ای نشان ندادند و اما فقط یک نفر می دانست که ماده شیمیایی «دی هیدروژن مونوکسید» در واقع همان آب است!! \r\nعنوان پروژه دانشجوی فوق «ما چقدر زود باور هستیم» بود!\r\n"},{"id":944,"category_id":7,"category_code":"s7","source_id":114,"title":" تاجر و ماهیگیر","content":"یک تاجر امریکایی نزدیک یک روستای مکزیکی ایستاده بود. \r\nدر همان موقع یک قایق کوچک ماهیگیری رد شد که داخلش\r\nچند تا ماهی بود. از ماهیگیر پرسید: \r\nچقدر طول کشید تا این چند ماهی رو گرفتی ؟\r\nماهیگیر : مدت خیلی کمی.\r\nتاجر: پس چرا بیشتر صبر نکردی تا بیشتر ماهی گیرت بیاد؟\r\nماهیگیر : چون همین تعداد برای سیر کردن خانواده ام کافی است.\r\nتاجر: اما بقیه وقت را چیکار می کنی ؟\r\nماهیگیر: تا دیروقت می خوابم ،یه کم ماهیگیری می کنم با بچه ها\r\nبازی می کنم بعد میرم توی دهکده و با دوستان شروع می کنیم\r\nبه گیتار زدن خلاصه مشغولیم به این نوع زندگی.\r\nتاجر: من تو هاروارد درس خوندم و می تونم کمکت کنم.تو باید\r\nبیشتر ماهی گیری کنی.اون وقت می تونی با پولش قایق بزرگتری\r\nبخری و با درآمد اون چند تا قایق دیگر هم بعداً اضافه می کنی و\r\nاون وقت یه عالمه قایق برای ماهیگیری داری. \r\nماهیگیر: خوب بعدش چی ؟\r\nتاجر : به جای اینکه ماهی ها رو به واسطه بفروشی اونا رو\r\nمستقیماً به مشتری ها میدی و برای خودت کار و بار درست\r\nمی کنی . بعدش کارخونه راه می اندازی و به تولیداتش نظارت\r\nمی کنی و می روی مکزیکوسیتی ! بعد از اون هم لس آنجلس ! و از\r\nاونجا هم نیویورک . اونجاست که دست به کارهای مهمتری می زنی\r\nماهیگیر: این کار چقدر طول می کشه ؟\r\nتاجر: پانزده تا بیست سال. \r\nماهیگیر: اما بعدش چی آقا؟\r\nتاجر: بهترین قسمت همینه در یک موقعیت مناسب که گیر اومد\r\nمیری و سهام شرکت رو به قیمت خیلی بالا می فروشی ! این کار\r\nمیلیون ها دلار برات عایدی داره.\r\nماهیگیر: میلیون ها دلار ! خوب بعدش چی ؟\r\nتاجر : اون وقت بازنشسته می شی ! میری یه دهکده ساحلی\r\nکوچیک! جایی که می تونی تا دیر وقت بخوابی ! یه کم ماهیگیری\r\nکنی، با بچه هات بازی کنی! بری دهکده و تا دیروقت با دوستات\r\nگیتار بزنی و خوش بگذرونی.\r\n"},{"id":945,"category_id":7,"category_code":"s7","source_id":115,"title":"تنها قانون ","content":"\r\nسه تا زن توی تصادفی کشته شدن و سه تاشون رفتن بهشت!\r\nدمِ درِ بهشت مامور نگهبان گفت:\r\nشما آزادید هر کاری بکنید ، تنها قانون اینجا اینه که : روی اردک ها پا نذارین!\r\nزنها قبول کردن و رفتن توی بهشت.\r\nخیلی زیبا و سرسبز بود ولی همه جا پر از اردک بود!\r\nهمونجا اولین زن پاش رفت روی یه اردک و ازدک له شد...\r\nمامور نگهبان همون لحظه همراه با یه مرد خیلی بدقیافه اومد و گفت: \r\nتو قانون رو نقض کردی و برای تنبیهت باید تا\r\nابد با این مرد بمونی \r\nفردا اون روز ، زن دوم پاش رفت روی اردک و مامور نگهبان سریع اومد و همراهش یه مرد زشت دیگه بود و گفت: \r\nتوام قانون رو نقض کردی و باید تا ابد با این مرد بمونی برای تنبیه... \r\nزن سوم که اینا رو دیده بود خیلی ترسید و حواسشو جمع کرد که پاشو روی اردک ها نذاره\r\nچند ماه همینجوری گذشت که یه روز نگهبان با یه مرد فوق العاده خوش تیپ و زیبا اومد!نگهبان رو به زن کرد و گفت : شما باید تا ابد پیش همدیگه بمونید... \r\nزن که توی عمرش همچین مردی ندیده بود با ذوق از مرده پرسید: \r\nواااای من نمیدونم چیکار کردم که پاداشم تو هستی..! \r\nمرده گفت : منم چیزی نمیدونم ! فقط میدونم که یه اردک رو له کردم.\r\n"},{"id":946,"category_id":7,"category_code":"s7","source_id":116,"title":"پیوند مغز ","content":"بالاخره دکتر وارد شد ، با نگاهی خسته ، ناراحت و جدی  \r\nدکتر در حالی که قیافه نگرانی به خودش گرفته بود گفت :\"متاسفم که باید حامل خبر بدی براتون باشم , تنها امیدی که در حال حاضر برای عزیزتون باقی مونده، پیوند مغزه.\"  \r\n\"این عمل ، کاملا در مرحله آزمایش ، ریسکی و خطرناکه ولی در عین حال راه دیگه ای هم وجود نداره, بیمه کل هزینه عمل را پرداخت میکنه ولی هز ینه مغز رو خودتون باید پرداخت کنین.\"  \r\nاعضا خانواده در سکوت مطلق به گفته های دکتر گوش می کردن , بعد از مدتی بالاخره یکیشون پرسید :\" خب , قیمت یه مغز چنده؟\"\r\nدکتر بلافاصله جواب داد :\"5000$ برای مغز یک زن و 200$ برای مغز یک مرد.\" \r\nموقعیت نا جوری بود , خانم های داخل اتاق سعی می کردن نخندن و نگاهشون با آقایون داخل اتاق تلاقی نکنه , بعضی ها هم با خودشون پوز خند می زدن! \r\nبالاخره یکی طاقت نیاورد و سوالی که پرسیدنش آرزوی همه بود از دهنش پرید که : \"چرا مغز خانم ها گرونتره ؟\" \r\nدکتر با معصومیت بچگانه ای برای حضار داخل اتاق توضیح داد که : \" این قیمت استاندارد عمله ! باید یادآوری کنم که مغز آقایون چون استفاده میشه، خب دست دومه و طبیعتا ارزونتر!\"\r\n"},{"id":947,"category_id":7,"category_code":"s7","source_id":117,"title":"حسن آقا ","content":"حسن نامی وارد دهی شد و در مکانی که اهالی ده جمع شده بودند نشست و بنای گریه گذاشت. \r\nسبب گریه‌اش را پرسیدند، گفت: من مردغریبی هستم و شغلی ندارم برای بدبختی خودم گریه می‌کنم،\r\nمردم ده او را به شغل کشاورزی گرفتند. \r\nشب دیگر\r\nدیدند همان مرد باز گریه می‌کند، گفتند حسن آقا دیگر چه شده؟\r\nحالا که شغل پیدا کردی،  گفت: شما همه منزل و ماءوا مسکن دارید و می‌توانید خوتان\r\nرا از سرما\r\nو گرما حفظ کنید ولی من غریبم و خانه ندارم برای همین بدبختی گریه می‌کنم. \r\nبار دیگر اهالی ده همت کردن و برایش خانه‌ای تهیه کردند و وی را در آنجا جا دادند.\r\nولی شب باز دیدند دارد گریه می‌کند. وقتی علت را پرسیدند \r\nگفت: هر کدام از شما‌ها همسری دارید ولی من تنها در میان اطاقم می‌خوابم.\r\nمردم این مشکل او را نیز حل کردند و دختری از دختران ده را به ازدواج او در آوردند. \r\nولی باز شب هنگام حسن آقا داشت گریه می‌کرد. گفتند باز چی شده،\r\nگفت: همه شما سید هستید و من در میان شما اجنبی هستم.  \r\nبه دستور کدخدا شال سبزی به کمر او بستند تا شاید از صدای گریه او راحت شوند\r\nولی با کمال تعجب دیدند او شب باز گریه می‌کند، وقتی علت را پرسیدند \r\nگفت: بر جد غریبم گریه می‌کنم و به شما هیچ ربطی ندارد!!\r\n"},{"id":948,"category_id":7,"category_code":"s7","source_id":118,"title":"محکومین اعدام","content":"یه شب سه نفر برای خوش گذرونی میرن بیرون .... و حسابی مشروب میخورن و مست میکنن ... فرداش وقتی بیدار میشن توی زندان بودن... \r\nدر حالی که هیچی یادشون نمیومده اینو میفهمن که به اعدام روی صندلی الکتریکی محکوم شدن... \r\nنوبتِ نفر اول میشه که بشینه روی صندلی. وقتی میشینه میگه : من توی دانشگاه , رشته خداشناسی خوندم و به قدرت بی پایان خدا اعتقاد دارم .... میدونم که خدا نمیذاره آدم بیگناه مجازات بشه... \r\nکلید برق رو میزنن ... ولی هیچ اتفاقی نمیفته... \r\nبه بی گناهیش ایمان میارن و آزادش میکنن... \r\nنفر دوم میشینه روی صندلی و میگه : من توی دانشگاه حقوق خوندم... \r\nبه عدالت ایمان دارم و میدونم واسه آدم بی گناه اتفاقی نمیفته... \r\nکلید برق رو میزنن و هیچ اتفاقی نمیفته... \r\nبه بی گناهی اون هم اعتقاد میارن و آزادش میکنن \r\nنفر سوم میاد روی صندلی و میگه : من توی دانشگاه , رشته برق درس خوندم و به شما میگم که وقتی این دو تا کابل به هم وصل نباشن هیچ برقی وصل نمیشه به صندلی...\r\n"},{"id":949,"category_id":7,"category_code":"s7","source_id":119,"title":" عتیقه فروش","content":"عتیقه‌فروشی در روستایی به منزل رعیتی ساده وارد شد. دید كاسه‌ای نفیس و قدیمی دارد كه در گوشه‌ای افتاده و گربه در آن آب می‌خورد. با خود فکر کرد که اگر قیمت كاسه را بپرسد رعیت ملتفت مطلب می‌شود و قیمت گرانی بر آن می‌نهد. لذا گفت: عموجان چه گربه قشنگی داری آیا حاضری آن را به من بفروشی؟ رعیت گفت: چند می‌خری؟ گفت: یك درهم. رعیت گربه را گرفت و به دست عتیقه‌فروش داد و گفت: خیرش را ببینی. عتیقه‌فروش پیش از خروج از خانه با خونسردی گفت: عموجان این گربه ممكن است در راه تشنه‌اش شود بهتر است كاسه آب را هم به من بفروشی. رعیت گفت: قربان من به این وسیله تا به حال پنج گربه فروخته‌ام. كاسه فروشی نیست."},{"id":950,"category_id":7,"category_code":"s7","source_id":120,"title":"قصد ازدواج","content":"مرد جوانی نزد پدر خود رفت و به او گفت: \r\n:- می خواهم ازدواج کنم . پدر خوشحال شد و پرسید \r\n: نام دختر چیست ؟ مرد جوان گفت \r\nنامش سامانتا است و در محله ما زندگی می کند. پدر ناراحت شد . صورت در هم کشید و گفت: \r\nمن متاسفم به جهت این حرف که می زنم. اما تو نمی توانی با این دختر ازدواج کنی چون او خواهر توست . خواهش می کنم از این موضوع چیزی به مادرت نگو . مرد جوان نام سه دختر دیگر را آورد ولی جواب پدر برای هر کدام از آنها همین بود . با \r\nناراحتی نزد مادر خود رفت و گفت: \r\nمادر من می خواهم ازدواج کنم اما نام هر دختری را می آورم پدر می گوید که او خواهر توست ! و نباید به تو بگویم . مادرش لبخند زد و گفت:  \r\nنگران نباش پسرم. تو با هریک از این دخترها که خواستی می توانی ازدواج کنی . چون تو پسر او نیستی...!\r\n"},{"id":951,"category_id":7,"category_code":"s7","source_id":121,"title":" روز عاشورا","content":"روز عاشورا چیکار کِردی یَره ؟\r\nهیچی … صُبش جات خالی تو خیابون اَبکوه یک خیمه داشت لوبیا مِداد دوتا کاسه لوبیا با نون زدم تو رگ ! بعدش هموجور پیاده رَفتم فلکه دروازه قوچان دیدُم ایطرف درَن چایی مدَن اوطرف شیرکاکو ! اول رفتم شیرکاکو ره خوردُم جات خالی... \r\nبعدشم امدم چایی بخوُرم دیدم رو شیرکاکو حال نِمده ! مِزه شیرکاکو ره مُبره ! نِخوردُم ! امدُم برُم طِرف حَرَم دیدم یَک ماشین واستاد از صندوق عقبش شله زَرد دراورد زود دویدُم یا علی ! یَک شله زرد گریفتم دوتا قاشق خوردُم دیدُم مِزه اب مِده …اِنداختم تو جوب ! نزدیک میدون شهدا که رسیدُم دیدُم یک یارو دره ساندویچ تخم مرغ مِده رفتم یک ساندویچ گریفتم خوردُم گلوم گیریفت رفتم جلوتر یک لیوان چایی خوردُم تا رسیدُم حرم ! یَک سِلام مَشدی دادُم به\r\nاقا گفتم نوکرتم رفتم تو حَرم!تو حَرم یَکم سینه زدُم خیلی حال داد یَک دختره رفته بود تو کوک سینه زدن ما ! مایَم شور حسینی گریفتِما بزن که مِزنی الان ای قفسه سینَم درد مُکنه بَدجور ! نوحه که تموم رَفت امدُم شماره تلیفون بدُم بهش نمدنم کجا رَفت! \r\nهیچی ظهرشَم جات خالی رفتُم تو کوچه زردی شله خوردُم دوتا کوکا هم روش اقا سنگین رفتم امدُم رفتم تو مِسجد گلمکانیا دراز کشیدم تا عصر ! عصرشَم دیدُم باز یک بابایی دره عدسی نذری مِده دوتا کاسه خوردُم نامرد توش سنگ داشت ای دندونه جلوم شیکست ! شبشَم یک شمع از تو مِسجد بلند کِردُم را افتادم شام غریبان ! یک دختره بود شمع دستش بود لامَصب یک حال سَگی مِداد که نگو ! یک جا که شلوغ رَفت اَزَم بغلش رد رَفتم جیغ کشید باباش فهمید گریفتَن با براراش زَدنم نامردا !هی امدم تیزی ره در بیارُم واز گفتم روز عاشورا گنا دره کسی ره چاقو بزنی! \r\nهیچی شبشم امدُم خانه هم سینه ام درد می کرد هم زیر چشمُم کبود رفته بود هم دندونم شیکسته بود هم اِسهال رفته بودم.\r\n"},{"id":952,"category_id":7,"category_code":"s7","source_id":122,"title":"دختر ایتالیایی ","content":"روزی روزگاری یک زن انگلیسی قصد می‌کنه تا یک سفر دو هفته‌ای به ایتالیا داشته باشه ، شوهرش اون رو به فرودگاه می‌رسونه و واسش آرزو می‌کنه که سفر خوبی داشته باشه. \r\nزن میگه : چی دوست داری سوغاتی واست بیارم؟\r\nمرد می‌خنده و میگه : یه دختر ایتالیایی! \r\nزن هیچی نمی‌گه و سوار هواپیما می‌شه و میره . دو هفته بعد وقتی که زن از مسافرت برمی‌گرده، مرد توی فرودگاه به استقبالش میره و بهش می‌گه : خب عزیزم مسافرت خوب بود ؟\r\nزن : ممنون، عالی بود \r\nمرد به شوخی می‌پرسه : خب سوغاتی من چی شد پس؟\r\nزن : کدوم سوغاتی؟\r\nمرد : همونی که ازت خواسته بودم ... دختر ایتالیایی... \r\nزن جواب می‌ده: آهان! اون رو میگی؟ راستش من هر کاری که از دستم بر می‌آمد انجام دادم ، حالا باید 9 ماه صبر کنیم تا ببینیم پسر می‌شه یا دختر ؟؟؟  \r\nنتيجه اخلاقي : خانومها شوخي سرشان نميشود.\r\n"},{"id":953,"category_id":7,"category_code":"s7","source_id":123,"title":"خانواده ی ایده آل ","content":" \r\nمن آمادگی میرفتم خواهرم پنجم دبستان بود. \r\nیه بار بهم گفت تو بچه سره راهی هستی ما تورو از کنار مسجد پیدا کردیم! \r\nولی هرچی اصرار میکرد میگفتم نه تو دروغ میگی... \r\nیه بار مامانم دعوام کرد. \r\nمنم زدم زیره گریه گفتم : آرهههههه من خودم میدونم \r\nمامانم گفت : چیو میدونی ؟\r\nخواهرم که ۲زاریش افتاده بود هی چشم و ابرو میومد که نگووووو. به مامانم گفتم : من خودم میدونم منو از کنار مسجد پیدا کردین … مامانم گفت : کیییییییییی گفته ؟\r\nمنم گفتم کی گفته\r\nمامانم گفت : غلط کردههههههههه ، خودشو از تو جوب پیدا کردیم! \r\nو این چنین بود که خواهرم رسوا شد!\r\n \r\nحالا ببینین چه خانواده پر محتوایی دارم من\r\nخواهرم از تو جوی(به قول مامانم جوب)\r\nمنم که کنار مسجد پیدا شدیم.\r\n"},{"id":954,"category_id":7,"category_code":"s7","source_id":124,"title":"برو زن بگیر! ","content":"چندسال پیش یک روز جلوی تلویزیون دراز کشیده بودم، فوتبال نگاه می کردم و تخمه می خوردم. ناگهان پدرو مادر و آبجی بزرگ و خان داداش سرم هوار شدند و فریاد زدند که:\r\n ای الاف ! ناقص! بدبخت! بی عرضه! بی مسئولیت! پاشو برو زن بگیر.رفتم خواستگاری؛ \r\nدختر پرسید:\r\n مدرک تحصیلی ات چیه ؟ \r\nگفتم: دیپلم تمام! \r\nگفت: بی سواد! امل! بی کلاس! ناقص العقل! بی شعور! پاشوبرو دانشگاه. رفتم چهار سال دانشگاه لیسانس گرفتم \r\nبرگشتم؛ رفتم خواستگاری؛پدر دختر پرسید: خدمت رفتی؟ \r\nگفتم: هنوز نه\r\nگفت: مردنشده نامرد! بزدل! ترسو! سوسول! بچه ننه! پاشو برو سربازی \r\nرفتم دو سال خدمت سربازی را انجام دادم.برگشتم؛ رفتم خواستگاری؛مادر دختر پرسید: شغلت چیست ؟ \r\nگفتم: فعلا کار گیر نیاوردم ؛ \r\nگفت:« بی کار! بی عار! انگل اجتماع! تن لش! علاف! پاشو برو سر کار ».رفتم کار پیدا کنم؛ گفتند:« سابقه کار می خواهیم »؛\r\nرفتم سابقه کار جور کنم؛ گفتند: باید کار کرده باشی تا سابقه کار بدهیم. \r\nدوباره رفتم کار کنم؛ گفتند: « باید سابقه کار داشته باشی تا کار بدهیم».برگشتم؛ رفتم خواستگاری؛گفتم: « رفتم کار کنم گفتند سابقه کار، رفتم سابقه کار جور کنم گفتند باید کار کرده باشی»گفتند:« برو جایی که سابقه کار نخواهد »رفتم جایی که سابقه کار نخواستند.گفتند:« باید متاهل باشی»برگشتم؛ رفتم خواستگاری؛ گفتم:« رفتم جایی که سابقه کار نخواستند ولی گفتند باید متاهل باشی »گفتند:« باید کار داشته باشی تا بگذاریم متاهل شوی »رفتم؛ گفتم:«باید کار داشته باشم تا متاهل بشوم».گفتند:« باید متاهل باشی تا به تو کار بدهیم »برگشتم؛ \r\nرفتم نیم کیلو تخمه خریدم! دوباره دراز کشیدم جلوی تلویزیون و فوتبال نگاه کردم!\r\n"},{"id":955,"category_id":7,"category_code":"s7","source_id":125,"title":"نذر چوپان ","content":"چوپانی گله را به صحرا برد به درخت گردوی تنومندی رسید. \r\nاز آن بالا رفت و به چیدن گردو مشغول شد که ناگهان گردباد سختی در گرفت، \r\nخواست فرود آید، ترسید. باد شاخه ای را که چوپان روی آن بود به این طرف و آن طرف می برد. \r\nدید نزدیک است که بیفتد و دست و پایش بشکند.\r\nدر حال مستاصل شد... \r\nاز دور بقعه امامزاده ای را دید و گفت: \r\nای امام زاده گله ام نذر تو، از درخت سالم پایین بیایم.\r\nقدری باد ساکت شد و چوپان به \r\nشاخه قوی تری دست زد و جای پایی پیدا کرده و خود را محکم گرفت. \r\nگفت: \r\nای امام زاده خدا راضی نمی شود که زن و بچه من بیچاره از تنگی و خواری بمیرند و تو همه گله را صاحب شوی... \r\nنصف گله را به تو می دهم و نصفی هم برای خودم\r\nقدری پایین تر آمد. \r\nوقتی که نزدیک تنه درخت رسید گفت:\r\nای امام زاده نصف گله را چطور نگهداری می کنی؟ \r\nآنهار ا خودم نگهداری می کنم در عوض کشک و پشم نصف گله را به تو می دهم. \r\nوقتی کمی پایین تر آمد گفت:\r\nبالاخره چوپان هم که بی مزد نمی شود کشکش مال تو، پشمش مال من به عنوان دستمزد. \r\nوقتی باقی تنه را سُرخورد و پایش به زمین رسید نگاهی به گنبد امامزاده انداخت و گفت: \r\nمرد حسابی چه کشکی چه پشمی؟ \r\nما از هول خودمان یک غلطی کردیم \r\nغلط زیادی که جریمه ندارد.\r\n"},{"id":956,"category_id":7,"category_code":"s7","source_id":126,"title":"جنازه کش","content":"مسافر تاکسی آهسته روی شونه‌ی راننده زد، چون می‌خواست ازش یه سوال بپرسه… راننده جیغ زد، کنترل ماشین رو از دست داد… نزدیک بود که بزنه به یه اتوبوس… از جدول کنار خیابون رفت بالا… نزدیک بود که چپ کنه… اما کنار یه مغازه توی پیاده رو متوقف شد… برای چند ثانیه هیچ حرفی بین راننده و مسافر رد و بدل نشد… سکوت سنگینی حکم فرما بود، تا این که راننده رو به مسافر کرد و گفت: \"هی مرد! دیگه هیچ وقت این کار رو تکرار نکن… من رو تا سر حد مرگ ترسوندی!\" مسافر عذرخواهی کرد و گفت: \"من نمی‌دونستم که یه ضربه‌ی کوچولو آنقدر تو رو می‌ترسونه\" راننده جواب داد: \"واقعا تقصیر تو نیست… امروز اولین روزیه که به عنوان یه راننده‌ی تاکسی دارم کار می‌کنم… آخه من 25 سال راننده‌ی ماشین جنازه کش بودم...!\""},{"id":957,"category_id":7,"category_code":"s7","source_id":127,"title":"خر بی دم","content":"مردی خری دید به گل در نشسته و صاحب خر از بیرون کشیدن آن درمانده . مساعدت را ( برای کومک کردن ) دست در دُم خر زده قُوَت کرد( زور زد ) . دُم از جای کنده آمد . فغان از صاحب خر برخاست که \" تاوان بده!\" \r\nمرد به قصد فرار به کوچه یی دوید ، بن بست یافت . خود را به خانه یی درافگند . زنی آنجا کنار حوض خانه چیزی میشست و بار حمل داشت ( حامله بود ) . از آن هیاهو و آواز در بترسید ، بار بگذاشت ( سِقط کرد ) . خانه خدا ( صاحبِ خانه ) نیز با صاحب خر هم آواز شد. \r\nمردِ گریزان بر بام خانه دوید . راهی نیافت ، از بام به کوچه یی فروجست که در آن طبیبی خانه داشت . مگر جوانی پدر بیمارش را به انتظار نوبت در سایهء دیوار خوابانده بود ؛ مرد بر آن پیر بیمار فرود آمد ، چنان که بیمار در حای بمُرد .. پدر مُرده نیز به خانه خدای و صاحب خر پیوست! \r\nمَرد ، همچنان گریزان ، در سر پیچ کوچه با یهودی رهگذر سینه به سینه شد و بر زمینش افگند . پاره چوبی در چشم یهودی رفت و کورش کرد . او نیز نالان و خونریزان به جمع متعاقبان پیوست! \r\nمرد گریزان ، به ستوه از این همه، خود را به خانهء قاضی افگند که \" دخیلم! \" . مگر قاضی در آن ساعت با زن شاکیه خلوت کرده بود . چون رازش فاش دید ، چارهء رسوایی را در جانبداری از او یافت : و چون از حال و حکایت او آگاه شد ، مدعیان را به درون خواند... \r\nنخست از یهودی پرسید: \r\nگفت : این مسلمان یک چشم مرا نابینا کرده است . قصاص طلب میکنم. \r\nقاضی گفت : دَیتِ مسلمان بر یهودی نیمه بیش نیست . باید آن چشم دیگرت را نیز نابینا کند تا بتوان از او یک چشم برکند! \r\nو چون یهودی سود خود را در انصراف از شکایت دید ، به پنجاه دینار جریمه محکومش کرد! \r\nجوانِ پدر مرده را پیش خواند. \r\nگفت : این مرد از بام بلند بر پدر بیمار من افتاد ، هلاکش کرده است . به طلب قصاص او آمده ام. \r\nقاضی گفت : پدرت بیمار بوده است ، و ارزش حیات بیمار نیمی از ارزش شخص سالم است . حکم عادلانه این است که پدر او را زیر همان دیوار بنشانیم و تو بر او فرودآیی ، چنان که یک نیمهء جانش را بستانی! \r\nو جوانک را نیز که صلاح در گذشت دیده بود ، به تأدیهء سی دینار جریمهء شکایت بیمورد محکوم کرد!\r\nچون نوبت به شوی آن زن رسید که از وحشت بار افکنده بود ، گفت : قصاص شرعاً هنگامی جایز است که راهِ جبران مافات بسته باشد . حالی میتوان آن زن را به حلال در فراش ( عقد ازدواج ) این مرد کرد تا کودکِ از دست رفته را جبران کند . طلاق را آماده باش! \r\nمردک فغان برآورد و با قاضی جدال میکرد ، که ناگاه صاحب خر برخاست و به جانب در دوید. \r\nقاضی آواز داد : هی ! بایست که اکنون نوبت توست! \r\nصاحب خر همچنان که میدود فریاد کرد : مرا شکایتی نیست . محکم کاری را ، به آوردن مردانی میروم که شهادت دهند خر مرا از گره گی دُم نبوده است.\r\n"},{"id":958,"category_id":7,"category_code":"s7","source_id":128,"title":" سبد سیب","content":"بچه‌ها در ناهارخورى مدرسه به صف ایستاده بودند. سر میز یک سبد سیب بود که روى آن نوشته بود: فقط\r\nیکى بردارید. خدا ناظر شماست. \r\nدر انتهاى میز یک سبد شیرینى و شکلات بود. یکى از بچه‌ها رویش نوشت: هر چند تا مى‌خواهید بردارید!\r\nخدا مواظب سیب‌هاست.\r\n"},{"id":959,"category_id":7,"category_code":"s7","source_id":129,"title":" ایرانیان در ...","content":"میگن یه روز جبرئیل میره پیش خدا گلایه میکنه که: آخه خدا، این چه وضعیه آخه؟ ما یک مشت ایرونی داریم توی بهشت که فکر میکنن اومدن خونه باباشون! به جای لباس و ردای سفید، همه شون لباس های مارک دار و آنچنانی میخوان! هیچ کدومشون از بالهاشون استفاده نمیکنن، میگن بدون 'بنز' و 'ب ام و' جایی نمیرن! اون ب...وق و کرنای من هم گم شده... یکی از همین ها دو ماه پیش قرض گرفت و رفت دیگه ازش خبری نشد!"},{"id":960,"category_id":7,"category_code":"s7","source_id":130,"title":" افزایش حقوق","content":"خدمتکاری به خانم خانه ای که در آنجا کار می کرد،تقاضای افزایش حقوق داد.\r\nخانم خانه که خیلی از این موضوع ناراحت بود، تصمیم گرفت با خدمتکار صحبت کند.\r\nخانم خانه پرسید:\r\n«ماریا، چرا می خوای حقوقت افزایش پیدا کنه؟» \r\nماریا جواب داد:\r\n«خوب، می دونید خانم، سه دلیل برای اینکه حقوق من باید افزایش پیدا کنه وجود داره» \r\n«اولین دلیل اینه که من بهتر از شما اتو می کنم»\r\nخانم خانه پرسید: \r\n« کی گفته که تو بهتر از من اتو می کنی؟» \r\nماریا جواب داد:\r\n«همسرتون این طور می گه» \r\nخانم خانه گفت: \r\n«اوه»\r\nماریا ادامه داد:\r\n«دلیل دوم اینه که من بهتر از شما آشپزی می کنم» \r\nخانم خانه با اندکی ناراحتی گفت: \r\n«مزخرفه! کی گفته آشپزی تو بهتر از منه؟؟؟»\r\nماریا گفت:\r\n«همسرتون این طور می گه»\r\n \r\nخانم خانه گفت: \r\n«اوه» \r\nماریا ادامه داد: \r\n«دلیل سوم اینه که من برای عشقبازی بهتر از شما هستم» \r\nخانم خانه با عصبانیت زیاد فریاد کشید:\r\n«آهان!!! این رو هم حتماً همسرم گفته، آره؟؟؟» \r\nماریا پاسخ داد: \r\n. \r\n. \r\n.\r\n. \r\n. \r\n. \r\n. \r\n.\r\n \r\n«نه خانم! راننده ی شخصی تون این طوری می گه»\r\n \r\nخانم خانه پاسخ داد: \r\n«آهان، باشه، باشه. راستی چقدر دوست داری به حقوقت افزوده بشه؟؟؟»\r\n"},{"id":961,"category_id":7,"category_code":"s7","source_id":131,"title":"بچه شتر ","content":"آورده اند روزی میان یک ماده شتر و فرزندش گفت وگویی به شرح زیر صورت گرفت:\r\nبچه شتر: مادر جون چند تا سوال برام پیش آمده است. آیا می تونم ازت بپرسم؟ \r\nشتر مادر: حتما عزیزم. چیزی ناراحتت کرده است؟ \r\nبچه شتر: چرا ما کوهان داریم؟ \r\nشتر مادر: خوب پسرم. ما حیوانات صحرا هستیم. در کوهان آب و غذا ذخیره می کنیم تا در صحرا که چیزی پیدا نمی شود بتوانیم دوام بیاوریم. \r\nبچه شتر: چرا پاهای ما دراز و کف و پای ما گرد است؟\r\nشتر مادر: پسرم. قاعدتا برای راه رفتن در صحرا و تندتر راه رفتن داشتن این نوع دست و پا ضروری است. \r\nبچه شتر: چرا مژه های بلند و زخیم داریم؟ بعضی وقت ها مژه ها جلوی دید من را می گیرد. \r\nشتر مادر: پسرم این مژه های بلند و ضخیم یک نوع پوشش حفاظتی است که چشم ها ما را در مقابل باد و شن های بیابان محافظت می کنند.\r\nبچه شتر: فهمیدم. پس کوهان برای ذخیره کردن آب است برای زمانی که ما در بیابان هستیم. پاهایمان برای راه رفتن در بیابان است و مژه هایمان هم برای محافظت چشمهایمان در برابر باد و شن های بیابان است... .\r\nبچه شتر: فقط یک سوال دیگر دارم\r\nشتر مادر: بپرس عزیزم. \r\nبچه شتر: پس ما در این باغ وحش چه غلطی می کنیم؟\r\n"},{"id":962,"category_id":7,"category_code":"s7","source_id":132,"title":"قندان ","content":"خانم حميدي براي ديدن پسرش مسعود، به محل تحصيل او يعني لندن آمده بود. او در آنجا متوجه شد كه پسرش با يك هم اتاقي دختر به نام ويكي زندگي ميكند. كاري از دست خانم حميدي بر نمي آمد و از طرفي هم اتاقي مسعود هم خيلي خوشگل بود. او به رابطه ميان آن دو مظنون شده بود و اين موضوع باعث كنجكاوي بيشتر او ميشد. مسعود كه فكر مادرش را خوانده بود گفت:\" من ميدانم كه شما چه فكري ميكنيد، اما من به شما اطمينان ميدهم كه من و ويكي فقط هم اتاقي هستيم\" حدود يك هفته بعد، ويكي پيش مسعود آمد و گفت : \"از وقتي مادرت از اينجا رفته ، قندان نقره اي من گم شده ، تو فكر نميكني كه او قندان را برداشته باشد؟\" مسعود گفت: \"خب، من شك دارم ولي براي اطمينان به او ايميل خواهم زد\" او در ايميل خود نوشت: \" مادر عزيزم ، من نميگم كه شما قندان را از خانه من برداشتيد ، و در ضمن نميگم كه شما آن را برنداشتيد، اما در هر صورت واقعيت اين است كه قندان از وقتي شما به تهران برگشتيد گم شده. با عشق مسعود\" روز بعد مسعود يك ايميل با اين مضمون از مادرش دريافت نمود: پسر عزيزم ، من نميگم تو با ويكي رابطه داري! و در ضمن نميگم كه تو باهاش رابطه نداري، اما در هر صورت واقعيت اين است كه اگر او در رختخواب خودش ميخوابيد ، حتما تا الآن قندان را پيدا كرده بود."},{"id":963,"category_id":7,"category_code":"s7","source_id":133,"title":"جریان خون","content":"معلم داشت جریان خون در بدن را به بچه‌ها درس مى‌داد. براى این که موضوع براى بچه‌ها روشن‌تر شود گفت:\r\nبچه‌ها! اگر من روى سرم بایستم، همان طور که مى‌دانید خون در سرم جمع مى‌شود و صورتم قرمز مى‌شود. \r\nبچه‌ها گفتند: بله\r\nمعلم ادامه داد: پس چرا الان که ایستاده‌ام خون در پاهایم جمع نمى‌شود؟\r\nیکى از بچه‌ها گفت: براى این که پاهاتون خالى نیست.\r\n"},{"id":964,"category_id":7,"category_code":"s7","source_id":134,"title":"شکارچی ","content":"یک مرد ۸۰ ساله میره پیش دکترش برای چک آپ. دکتر ازش در مورد وضعیت فعلیش می پرسه و پیرمرد با غرور جواب میده:\r\nهیچوقت به این خوبی نبودم. تازگیا با یه دختر ۲۵ ساله ازدواج کردم و حالا باردار شده و کم کم داره موقع زایمانش میرسه. نظرت چیه دکتر؟\r\nدکتر چند لحظه فکر میکنه و میگه: خب… بذار یه داستان برات تعریف کنم. من یه نفر رو می شناسم که شکارچی ماهریه. اون هیچوقت تابستونا رو برای شکار کردن از دست نمیده.\r\nیه روز که می خواسته بره شکار از بس عجله داشته اشتباهی چترش رو به جای تفنگش بر میداره و میره توی جنگل.. همینطور که میرفته جلو یهو از پشت درختها یه پلنگ وحشی ظاهر میشه و میاد به طرفش.\r\nشکارچی چتر رو می گیره به طرف پلنگ و نشونه می گیره و ….. بنگ! پلنگ کشته میشه و میفته روی زمین!\r\nپیرمرد با حیرت میگه: این امکان نداره! حتما' یه نفر دیگه پلنگ رو با تیر زده!\r\nدکتر یه لبخند میزنه و میگه: دقیقا' منظور منم همین بود!\r\n"},{"id":965,"category_id":7,"category_code":"s7","source_id":135,"title":"مامان یا خدا؟ ","content":"خدا به ما انگشت داده – مامان ميگه: \"باچنگال غذابخور\"\r\nخدا به ما صدا داده – مامان ميگه:\"جيغ نزن\"\r\nمامان ميگه،«كلم بخور،حبوبات و هويج بخور» ولي خدا به ما هوس بستني شيره‌اي داده \r\nخدا به ما انگشت داده – مامان ميگه:\"دستمال بردار\"\r\nخدا به ما آب گل آلود داده – مامان ميگه:\"شالاپ شولوپ نكن\"\r\nمامان ميگه،«ساكت باش، خوابه بابات» اما خدا به ما درسطل آشغال داده كه ميشه باهاش شترق صدا داد! \r\nخدا به ما انگشت داده – مامان ميگه:\"بايد دستكش هات رو دست كني\"\r\nمن چندان باهوش نيستم، ولي يه چيز رو مطمئنم بخدا\r\nيا مامان داره اشتباه مي كنه، يا اگه نه،خدا\r\n"},{"id":966,"category_id":7,"category_code":"s7","source_id":136,"title":"کامپیوتر دانا ","content":"یک بابایی میخوره زمین دستش پیچ میخوره، منتها تنبلیش میومده که بره دکتر نشونش بده.\r\nخلاصه دستش یک مدت همینجور درد میکرده، تا یک روزرفیقش بهش میگه این داروخونه سر کوچه یک کامپیوتر آورده که صد تومن میگیره، سر سه سوت هر مرضی رو تشخیص میده. ... یارو هم میگه: خوب دیگه صد تومن که پولی نیست، بریم ببینیم چه جوریاست.\r\nخلاصه میره اونجا، میبینه یک دستگاه گنده گذاشتن، جلوش یک شکاف داره، روش نوشته: لطفأ اسکناس صد تومانی وارد کنید.\r\nیارو یک صد تومنی میگذاره، یهو یک چیز قیف مانند میاد بیرون، میگه: نمونه ادرار\r\n...\r\nطرف هم با خجالت و یواشکی کارشو میکنه تو جناب قیف!\r\nبعد از دو سه دقیقه تلق تولوق و بوق بوق، کامپیوتره یک تیکه کاغذ میده بیرون که روش نوشته بوده:\r\nیکی از تاندنهای دست شما پاره شده. باید یک هفته ببندینش و باهاش کار سنگین نکنید تا خوب شه.\r\nیارو کف میکنه که این لا مصب اینهمه چیز رو چطور از ادرار آدم میفهمه؟\r\nخلاصه کرمش میگیره که ببینه میشه گولش زد یا نه.\r\nفرداش یک شیشه مربا ورمیداره، تا نصف توش آب میریزه، بعد میده سگش توش ... یک دونه از آدامسای دخترش رو هم میندازه توش، ، بعدم میره همون داروخونه، معجونش رو میریزه به جای نمونه ادرار.\r\nکامپیوتره یک 15 دقیقه قیژ قیژ و دلنگ دلونگ میکنه، بعد یک کاغد چاپ میکنه میده بیرون که روش نوشته بوده:\r\nآب شیرتون آهک داره، باید لوله کش بیارید درستش کنه.\r\nسگت قلبش ناراحته، همین روزها تموم میکنه.\r\nدخترت حاملست، باید بری خر پسر طبقه پایینی رو بگیری!\r\nدرضمن اگه بخوای حروم زاده بازی در بیاری، تاندن دستت هیچ وقت خوب نمیشه!\r\n"},{"id":967,"category_id":7,"category_code":"s7","source_id":137,"title":" تکرار اشتباه","content":"کارمندی به دفتر رئیس خود می‌رود و می‌گوید: معنی این چیست؟ شما 200 دلار کمتر از چیزی که توافق کرده بودیم به من پرداخت کردید. \r\nرئیس پاسخ می دهد: خودم می‌دانم، اما ماه گذشته که 200 دلار بیشتر به تو پرداخت کردم هیچ شکایتی نکردی. \r\nکارمند با حاضر جوابی پاسخ می دهد: درسته، من معمولا از اشتباه های موردی می گذرم اما وقتی تکرار می شود وظیفه خود می دانم به شما گزارش کنم.\r\n"},{"id":968,"category_id":7,"category_code":"s7","source_id":138,"title":" روانپزشک","content":"هنگام بازدید از یک بیمارستان روانى، از روان‌پزشک پرسیدم شما چطور می‌فهمید که یک بیمار روانى به بسترى شدن در بیمارستان نیاز دارد یا نه؟\r\nروان‌پزشک گفت: ما وان حمام را پر از آب می‌کنیم و یک قاشق چایخورى، یک فنجان و یک سطل جلوى بیمار می‌گذاریم و از او می‌خواهیم که وان را خالى کند.\r\nمن گفتم: آهان! فهمیدم. آدم عادى باید سطل را بردارد چون بزرگ‌تر است.\r\nروان‌پزشک گفت: نه! آدم عادى درپوش زیر آب وان را بر می‌دارد. شما می‌خواهید تخت‌تان کنار پنجره باشد؟ \r\nنمیخواد تظاهر کنین که شما به فکر سطل نیوفتادین ... شما دوست دارین تختتون کجا باشه ؟؟؟؟\r\n"},{"id":969,"category_id":7,"category_code":"s7","source_id":139,"title":"مستجاب الدعوه","content":"زاهدی کیسه ای گندم نزد آسیابان برد. آسیابان گندم او را در کنار سایر کیسه ها گذاشت تا به نوبت آرد کند.\r\nزاهد گفت: \"اگر گندم مرا زودتر آرد نکنی دعا می کنم خرت سنگ بشود.\"  \r\nآسیابان گفت: \"تو که چنین مستجاب الدعوه هستی دعا کن گندمت آرد بشود.\"\r\n"},{"id":970,"category_id":7,"category_code":"s7","source_id":140,"title":"شیوه ی طرح سوال ","content":"در بازگشت از کلیسا، جک از دوستش ماکس می پرسد: \"فکر می کنی آیا می شود هنگام دعا کردن سیگار کشید؟\"\r\nماکس جواب می دهد: \"چرا از کشیش نمی پرسی؟\"\r\nجک نزد کشیش می رود و می پرسد: جناب کشیش، می توانم وقتی در حال دعا کردن هستم، سیگار بکشم.\r\nکشیش پاسخ می دهد: نه، پسرم، نمی شود. این بی ادبی به مذهب است.\r\nجک نتیجه را برای دوستش ماکس بازگو می کند.\r\nماکس می گوید: تعجبی نداره. تو سئوال را درست مطرح نکردی. بگذار من بپرسم.\r\nماکس نزد کشیش می رود و می پرسد: «آیا وقتی در حال سیگار کشیدنم می توانم دعا کنم ؟\r\nکشیش مشتاقانه پاسخ می دهد: مطمئناً، پسرم. مطمئناً\r\n"},{"id":971,"category_id":7,"category_code":"s7","source_id":141,"title":"اعتراف ","content":"\r\nمردی برای اعتراف نزد کشیش رفت.\r\n«پدر مقدس، مرا ببخش. در زمان جنگ جهانی دوم من به یک یهودی پناه دادم» \r\n«مسلماً تو گناه نکرده ای پسرم» \r\n«اما من ازش خواستم برای ماندن در انباری من هفته ای بیست شیلینگ بپردازد»\r\nخوب البته این یکی زیاد خوب نبوده. اما بالاخره تو جون اون آدم رو نجات دادی، بنابراین بخشیده می شوی. \r\n«اوه پدر این خیلی عالیه. خیالم راحت شد. حالا میتونم یه سئوال دیگه هم بپرسم؟» \r\n«چی می خوای بپرسی پسرم؟» \r\n«به نظر شما باید بهش بگم که جنگ تموم شده؟» \r\n"},{"id":972,"category_id":7,"category_code":"s7","source_id":142,"title":"نقش زن در زندگی ","content":"میگویند زنها در موفقیت و پیشرفت شوهرانشان نقش بسزایی دارند.\r\nساعد مراغه ای از نخست وزیران دوران پهلوی نقل کرده بود:\r\nزمانی که نایب کنسول شدم با خوشحالی پیش زنم آمدم و این خبر داغ را به اطلاع سرکار خانم رساندم...\r\nاما وی با بی اعتنایی تمام سری جنباند و گفت :خاک بر سرت کنند؛ فلانی کنسول است؛ تو نایب کنسولی؟ \r\nگذشت و چندی بعد کنسول شدیم و رفتیم پیش خانم؛ آن هم با قیافهایی حق به جانب\r\nباز خانم ما را تحویل نگرفت و گفت :خاک بر سرت کنند؛ فلانی معاون وزارت امور خارجه است و تو کنسولی؟ \r\nشدیم معاون وزارت امور خارجه؛ که خانم باز گفت :خاک بر سرت؛ فلانی وزیر امور خارجه است و تو...؟\r\nشدیم وزیر امور خارجه گفت :فلانی نخست وزیر است... خاک بر سرت کنند! \r\nالقصه آنکه شدیم نخست وزیر و این بار با گامهای مطمئن به خانه رفتم و منتظر بودم که خانم حسابی یکه بخورد و به عذر خواهی بیفتد.\r\nتا این خبر را دادم به من نگاهی کرد؛ سری جنباند و آهی کشید و گفت: خاک بر سر ملتی که تو نخست وزیرش باشی\r\n"},{"id":973,"category_id":7,"category_code":"s7","source_id":143,"title":"آرزوی پیرمرد","content":"يك زوج در اوايل 60 سالگي، در يك رستوران كوچيك رمانتيك سي و پنجمين سالگرد ازدواجشان را جشن گرفته بودن.\r\nناگهان يك پري كوچولوِ قشنگ سر ميزشون ظاهر شد و گفت: چون شما زوجي اينچنين مثال زدني هستين و درتمام اين مدت به هم وفادار موندين، هر كدومتون مي تونين يك آرزو بكنين.\r\nخانم گفت: اووووووووووووووووه! من مي خوام به همراه همسر عزيزم، دور دنيا سفر كنم. پري چوب جادووييش رو تكون داد و اجي مجي لا ترجي دو تا بليط درجه یک در دستش ظاهر شد.\r\nحالا نوبت آقا بود، چند لحظه فكر كرد و گفت: خب، اين خيلي رمانتيكه ولي چنين موقعيتي فقط يك بار در زندگي آدم اتفاق مي افته، بنابراين، خيلي متاسفم عزيزم ولي آرزوي من اينه كه همسري 30 سال جوانتر از خودم داشته باشم.\r\nخانم و پري واقعا نا اميد شده بودن ولي آرزو، آرزوه ديگه !!! پري چوب جادوييش و چرخوند و... اجي مجي لا ترجي و آقا 92 ساله شد!\r\n"},{"id":974,"category_id":7,"category_code":"s7","source_id":144,"title":"راز خوشبختی","content":"روزی یک زوج،بیست و پنجمین سالگرد ازداوجشان را جشن گرفتند.آنها در شهر مشهور شده بودند به خاطر اینکه در طول 25 سال حتی کوچکترین اختلافی با هم نداشتند.\r\nتو این مراسم سردبیرهای روزنامه های محلی هم جمع شده بودند تا علت مشهور بودنشون (راز خوشبختی شونو) بفهمند.\r\nسردبیر میگه:آقا واقعا باور کردنی نیست؟ یه همچین چیزی چطور ممکنه؟ شوهره روزهای ماه عسل رو بیاد میاره و میگه:بعد از ازدواج برای ماه عسل به شمیلا رفتیم،اونجا برای اسب سواری هر دو،دو تا اسب مختلف انتخاب کردیم.اسبی که من انتخاب کرده بودم خیلی خوب بود ولی اسب همسرم به نظر یه کم سرکش بود.\r\nسر راهمون اون اسب ناگهان پرید و همسرم رو زین انداخت همسرم خودشو جمع و جور کرد و به پشت اسب زد و گفت :این بار اولته دوباره سوار اسب شد و به راه افتاد.بعد یه مدتی دوباره همون اتفاق افتاد این بار همسرم نگاهی با آرامش به اسب انداخت و گفت:این دومین بارت بعد بازم راه افتادیم .وقتی که اسب برای سومین بار همسرم رو انداخت خیلی با آرامش تفنگشو از کیف برداشت و با آرامش شلیک کرد و اونو کشت.\r\nسر همسرم داد کشیدم و گفتم :چیکار کردی روانی؟ حیون بیچاره رو کشتی!دیونه شدی؟ یه نگاهی به من کرد و گفت:این باراولته!\r\n"},{"id":975,"category_id":7,"category_code":"s7","source_id":145,"title":"تجویز پزشک","content":"خانمی وارد داروخانه می شه و به دکتر داروساز میگه که به سیانور احتیاج داره! داروسازه میگه واسه چی سیانور می‌‌خوای؟ خانمه توضیح می ده که لازمه شوهرش را مسموم کنه. چشم‌های داروسازه چهارتا می شه و میگه: خدا رحم کنه، خانوم من نمی‌تونم به شما سیانور بدم که برید و شوهرتان را بکُشید! این بر خلاف قوانینه! من مجوز کارم را از دست خواهم داد... هر دوی ما را زندانی خواهند کرد و دیگه بدتر از این نمی شه! نه خانوم، نـــه! شما حق ندارید سیانور داشته باشید و حداقل من به شما سیانور نخواهم داد. بعد از این حرف خانمه دستش رو می بره داخل کیفش و از اون یه عکس میاره بیرون؛ عکسی که در اون شوهرش و زن داروسازه توی یه رستوران داشتند شام می‌خوردند. داروسازه به عکسه نگاه می کنه و می گه: چرا به من نگفته بودید که نسخه دارید؟"},{"id":976,"category_id":7,"category_code":"s7","source_id":146,"title":"صداقت مردان","content":"اولین طلاق پس از حادثه 11 سپتامبر مربوط می شه به مردی که محل کارش طبقه 103 برج تجارت جهانی بوده، ولی در روز حادثه به جای اینکه سر کارش باشه، خونه دوست دخترش خواب بوده! تلویزیون رو هم ندیده بوده که بدونه چه خبره! خانمش زنگ می زنه. آقا گوشی رو بر می داره. خانمش می پرسه عزیزم حالت خوبه؟ کجایی؟ آقا جواب می ده: سر کارم هستم تو دفترم!!"},{"id":977,"category_id":7,"category_code":"s7","source_id":147,"title":"سرود ملی","content":"داستانی که در زیر نقل می‌شود مربوط به دانشجویان ایرانی است که دوران سلطنت «احمدشاه قاجار» برای تحصیل به آلمان رفته بودند و آقای «دکتر جلال گنجی» فرزند مرحوم «سالار معتمد گنجی نیشابوری» نقل کرده است:  \r\n\"ما هشت دانشجوی ایرانی بودیم که در آلمان در عهد «احمد شاه» تحصیل می‌کردیم. روزی رئیس دانشگاه به ما اعلام نمود که همه دانشجویان خارجی باید از مقابل امپراطور آلمان رژه بروند و سرود ملی کشور خودشان را بخوانند. \r\nما بهانه آوریم که عده‌مان کم است. گفت: اهمیت ندارد. از برخی کشورها فقط یک دانشجو در اینجا تحصیل می‌کند و همان یک نفر، پرچم کشور خود را حمل خواهد کرد، و سرود ملی خود را خواهد خواند. \r\nچاره‌ای نداشتیم. همه ایرانی‌ها دور هم جمع شدیم و گفتیم ما که سرود ملی نداریم، و اگر هم داریم، ما به یاد نداریم. پس چه باید کرد؟ وقت هم نیست که از نیشابور و از پدرمان بپرسیم. \r\nبه راستی عزا گرفته بودیم که مشکل را چگونه حل کنیم. یکی از دوستان گفت: اینها که فارسی نمی‌دانند. چطور است شعر و آهنگی را سر هم بکنیم و بخوانیم و بگوئیم همین سرود ملی ما است. کسی نیست که سرود ملی ما را بداند و اعتراض کند.\r\nاشعار مختلفی که از سعدی و حافظ می‌دانستیم، با هم تبادل کردیم. اما این شعرها آهنگین نبود و نمی‌شد به‌صورت سرود خواند. \r\nبالاخره من [دکتر گنجی] گفتم: بچه‌ها، عمو سبزی‌فروش را همه بلدید؟! گفتند: آری. گفتم: هم آهنگین است، و هم ساده و کوتاه. بچه‌ها گفتند: آخر عمو سبزی‌فروش که سرود نمی‌شود. گفتم: بچه‌ها گوش کنید! و خودم با صدای بلند و خیلی جدی شروع به خواندن کردم: «عمو سبزی‌فروش . . . بله. سبزی کم‌فروش . . . بله. سبزی خوب داری؟ . . . بله.» فریاد شادی از بچه‌ها برخاست و شروع به تمرین نمودیم. بیشتر تکیه شعر روی کلمه «بله» بود که همه با صدای بم و زیر می‌خواندیم.  \r\nهمه شعر را نمی‌دانستیم. با توافق هم‌دیگر، «سرود ملی» به این‌صورت تدوین شد:  \r\nعمو سبزی‌فروش! . . . بله \r\nسبزی کم‌فروش! . . . . بله\r\nسبزی خوب داری؟ . . . بله \r\nخیلی خوب داری؟ . . . .بله\r\nعمو سبزی‌فروش! . . . .بله \r\nسیب کالک داری؟ . . . بله \r\nزال‌زالک داری؟ . . . . . . بله \r\nسبزیت باریکه؟ . . . . . بله \r\nشبهات تاریکه؟ . . . . . .بله \r\nعمو سبزی‌فروش! . . . .بله  \r\nاین را چند بار تمرین کردیم. روز رژه، با یونیفورم یک‌ شکل و یک‌رنگ از مقابل امپراطور آلمان، «عمو سبزی‌فروش» خوانان رژه رفتیم. پشت سر ما دانشجویان ایرلندی در حرکت بودند. از «بله» گفتن ما به هیجان آمدند و «بله» را با ما همصدا شدند، به‌طوری که صدای «بله» در استادیوم طنین‌انداز شد و امپراطور هم به ما ابراز تفقد فرمودند و داستان به‌خیر گذشت.\"\r\n"},{"id":978,"category_id":7,"category_code":"s7","source_id":148,"title":" تق و تق","content":"ﺯﻥ ﻭ ﺷﻮﻫﺮﻱ ﺑﺎ ۹ ﺗﺎ ﺑﭽﻪ ﺩﺭ ﺍﻳﺴﺘﮕﺎﻩﺍﺗﻮﺑﻮﺱ ﻣﻨﺘﻈﺮ ﺍﻳﺴﺘﺎﺩﻩ ﺑﻮﺩﻧﺪ ﻛﻪ ﭘﯿﺮﻣﺮﺩ ﻧﺎﺑﻴﻨﺎﻳﻲ ﻫﻢ ﺑﻪ ﺁﻧﻬﺎ ﻣﻠﺤﻖ ﺷﺪ. \r\nﺍﺗﻮﺑﻮﺱ ﻛﻪ ﺁﻣﺪ ﭘﺮ ﺑﻮﺩ ﻭ ﻓﻘﻂ ﺯﻥ ﻭ ۹ ﺗﺎ ﺑﭽﻪﺗﻮﻧﺴﺘﻨﺪ ﺳﻮﺍﺭ ﺑﺸﻮﻧﺪ. \r\nﺑﻪ ﻫﻤﻴﻦ ﺧﺎﻃﺮ ﺷﻮﻫﺮﻭ ﭘﯿﺮﻣﺮﺩ ﻧﺎﺑﻴﻨﺎ ﺗﺼﻤﻴﻢ ﮔﺮﻓﺘﻨﺪ ﭘﻴﺎﺩﻩ ﺭﺍﻩ ﺑﻴﺎﻓﺘﻨﺪ. \r\nﺑﻌﺪ ﺍﺯ ﻣﺪﺗﻲ ﺷﻮﻫﺮﻩ ﺍﺯ ﺗﻖ ﺗﻖ ﭼﻮﺏ ﻣﺮﺩﻧﺎﺑﻴﻨﺎ ﻋﺼﺒﺎﻧﻲ ﺷﺪ،\r\nﮔﻔﺖ ﭼﺮﺍ ﻳﻪ ﺗﻴﻜﻪ ﻻﺳﺘﻴﻚ ﺳﺮ ﭼﻮﺑﺖ ﻧﻤﻴﻜﻨﻲ؟\r\nﺗﻖ ﺗﻖ ﺍﺵ ﻣﻨﻮ ﺩﻳﻮﻭﻧﻪ ﻛﺮﺩ!! \r\nﭘﻴﺮﻣﺮﺩ ﻧﺎﺑﯿﻨﺎ ﺟﻮﺍﺏ ﺩﺍﺩ: \r\nﺍﮔﻪ ﺗﻮ ﻫﻢ ﻻﺳﺘﻴﻚﺳﺮ ﭼﻮبتﻣﻲ ﺫﺍﺷﺘﻲ،  \r\nﺍﻻﻥ 9 تا بچه نداشتی وﻣﺎ هم ﺳﻮﺍﺭ ﺍﺗﻮﺑﻮﺱ بودیم.\r\n"},{"id":979,"category_id":7,"category_code":"s7","source_id":149,"title":"قرعه کشی","content":"جک از یک مزرعه‌دار در تگزاس الاغی به قیمت ۱۰۰ دلار خرید. قرار شد که مزرعه‌دار الاغ را روز بعد تحویل بدهد. \r\nاما روز بعد مزرعه‌دار سراغ جک آمد و گفت: متأسفم جوون. خبر بدی برات دارم. الاغه مرد.\r\nجک جواب داد: ایرادی نداره. همون پولم رو پس بده\r\nمزرعه‌دار گفت: نمی‌شه. آخه همه پول رو خرج کردم\r\nجک گفت: باشه. پس همون الاغ مرده رو بهم بده\r\nمزرعه‌دار گفت: می‌خوای باهاش چی کار کنی؟\r\nجک گفت: می‌خوام باهاش قرعه‌ کشی برگزار کنم\r\nمزرعه‌دار گفت: نمی‌شه که یه الاغ مرده رو به قرعه‌کشی گذاشت\r\nجک گفت: معلومه که می‌تونم. حالا ببین. فقط به کسی نمی‌گم که الاغ مرده است\r\nیک ماه بعد مزرعه ‌دار جک رو دید و پرسید: از اون الاغ مرده چه خبر؟\r\nجک گفت: به قرعه‌کشی گذاشتمش. ۵۰۰ تا بلیت ۲ دلاری فروختم و 998 دلار سود کردم\r\nمزرعه‌دار پرسید: هیچ کس هم شکایتی نکرد؟\r\nجک گفت: «فقط همونی که الاغ رو برده بود. من هم ۲ دلارش رو پس دادم.\r\n"},{"id":980,"category_id":7,"category_code":"s7","source_id":150,"title":"اوباما","content":"یه روز چاوز راه افتاد هلک و هلک رفت آمریکا. وضعیت اونجا رو که دید، توی دلش، جوری که بقیه متوجه نشن اون از آمریکا خوشش اومده، گفت: عجب پیشرفتی! عجب کشوری، چه رفاهی، چه نظمی، چه سیستم اداری منظمی، چه تشکیلاتی... \r\n\r\nبعد رفت پیش اوباما و ازش پرسید: بابا دمتون گرم! شما چکار کردین که اینقدر پیشرفت کردین؟ \r\n\r\nاوباما گفت: ببین! کارهای ما مثل کارهای شما هرتی پرتی نیست. ما وقتی می‌خوایم وزیر انتخاب کنیم، از همشون تست هوش می‌گیریم، باهوش‌ترین و به درد بخورترین اونها رو انتخاب می‌کنیم. نه هر ننه قمری را! الان برات تست می‌کنم حالشو ببری! \r\nاوباما زنگ زد به هیلاری کلینتون گفت: هیلاری جان! عزیزم یه نوک پا بیا دفتر من، کارت دارم. \r\nاز اونجا که اوباما مثل چاوز نبود، هیلاری با آرامش و سر فرصت رفت پیش اوباما. نه اینکه هول کنه و آب دستشه بذاره زمین! \r\nاوباما به هیلاری گفت: یه سوال ازت می‌پرسم، 30 ثانیه زمان داری که جواب بدی. «اون کیه که زاده‌ی پدر و مادرته، اما برادر و خواهرت نیست؟» \r\nچاوز خودش هم هنگ کرد و توی جواب موند که یهو هیلاری گفت: خوب معلومه، خودمم دیگه! \r\nچاوز کف کرد و سریع برگشت ونزوئلا و زنگ زد به « نیکولاس مادورو» وزیر خارجه و گفت: آب دستته بذار زمین بیا اینجا کارت دارم!\r\nوقتی مادورو اومد کلی داد و هوار راه انداخت و حنجره پاره کرد که: خاک بر سرت. آخه این چه وضع مملکته. این چه وضع جهانه! مثلا تو وزیر امور خارجه‌ای! خجالت بکش. یه سوال ازت می‌پرسم، سه روز فرصت داری جواب بدی. وگرنه می‌فرستمت جایی که عرب نی انداخت...\r\nبعد پرسید: اون کیه که زاده‌ی پدر و مادرت هست، اما برادر و خواهرت نیست؟ \r\nمادورو عزا گرفت که عجب سوال خفنی. خلاصه رفت و هر چی فکر کرد چیزی به ذهنش نرسید. \r\nیهو یادش افتاد بره پیش «کالین» از نخبه‌های مزدور بدبخت استکباری کشورش که سال قبل بازنشسته‌اش کردن و از اون بپرسه. وقتی «کالین» رو دید گفت: ای بدبخت غربزده، بگو ببینم: اون کیه که زاده‌ی پدر و مادرت هست، اما خواهر و برادرت نیست؟ \r\nکالین سریع گفت: خوب معلومه، خودمم دیگه!\r\nمادورو کلی حال کرد و از ذوقش سریع رفت پیش چاوز و گفت: کجایی چاوز من که جواب رو پیدا کردم...\r\nچاوز گفت: خوب بگو ببینم: «اون چه کسیه که زاده‌ی پدر و مادرت هست، اما خواهر و برادرت نیست؟\r\nوزیر خارجه گفت: خوب معلومه، اون «کالینه» دیگه \r\nچاوز عصبانی شد و داد زد: نه احمق، نه گیج! اون هیلاری کلینتونه، هیلاری کلینتون!\r\n"},{"id":981,"category_id":7,"category_code":"s7","source_id":151,"title":"مغز الکترونیکی","content":"طراح یک مغز الکترونیکی داشت در مورد این که اختراعش می تواند هر کاری بکند اغراق می کرد. او به یک رفیق صمیمی گفت که از دستگاه هر سؤالی که تمایل دارد بپرسد. دوستش از دستگاه پرسید: «پدر من اکنون کجاست؟» مغز الکترونیکی پاسخ داد: «پدر تو در حال ماهیگیری است.» دوستش با خنده گفت: «پدر من، رابرت، الان در اداره اش است. من همین الان با او تلفنی صحبت کردم!» دستگاه پاسخ داد: «رابرت در اداره اش است؛ پدر تو در حال ماهیگیری است!» "},{"id":982,"category_id":7,"category_code":"s7","source_id":152,"title":"قلیه حلوا","content":"بزرگی را از اکابر که در ثروت، قارون زمان خود بود، اجل فرا رسید، امید زندگانی قطع کرد. جگرگوشگان خود را که طفلان خاندان کرم بودند، حاضر کرد.\r\nگفت : ای فرزندان، روزگاری دراز در کسب مال، زحمت های سفر و حضر کشیده ام و حلق خود را به سرپنجه گرسنگی فشرده تا این چند دینار ذخیره کرده ام. هرگز از محافظت آن غافل مباشید و به هیچ وجه، دست خرج بدان نزنید و یقین دانید که:\r\nزر عزیز آفریده است خدا\r\nهر که خوارش بکرد ، خوار بشد\r\nاگر کسی با شما سخن گوید که پدر شما را در خواب دیدم قلیه حلوا می خواهد، هرگز به مکر آن فریب نخورید که آن من نگفته باشم و مرده چیزی نخورد.\r\nاگر من خود نیز به خواب شما بیایم و همین التماس کنم، بدان توجه نباید کرد که آن را خواب و خیال و رویا خوانند، چه بسا که آن را شیطان به شما نشان داده باشد، من آنچه در زندگی نخورده باشم در مردگی تمنا نکنم. این بگفت و جان به خزانه مالک دوزخ سپرد.\r\n"},{"id":983,"category_id":7,"category_code":"s7","source_id":153,"title":"ادعای خلیفه","content":"مهدی خلیفه در شکار از لشکر جدا ماند، شب به خانه عربی بیابانی رسید. غذایی که در خانه موجود بود و کوزه ای شراب پیش آورد. چون کاسه ای بخوردند، مهدی گفت : « من یکی از خواص مهدی ام،» کاسه دوم بخوردند، گفت: « یکی از امرای مهدی ام.» کاسه سیم بخوردند، گفت : من مهدی ام.\r\nاعرابی کوزه را برداشت و گفت : کاسه اول خوردی ، دعوی خدمتکار کردی. دوم دعوی امارت کردی. سیم دعوی خلافت کردی، اگر کاسه ی دیگری بخوری ، بی شک دعوی خدایی کنی!\r\nروز دیگر چون لشکر او جمع شدند، اعرابی از ترس می گریخت. مهدی فرمود که حاضرش کردند. زری چندش بداد. اعرابی گفت: اشهد انک الصادق و لو دعیت الرابعه. ( گواهی می دهم که تو راستگویی حتی اگر آن ادعای چهارم را هم داشته باشی! )\r\n"},{"id":984,"category_id":7,"category_code":"s7","source_id":154,"title":"لک لک","content":"طلحک را برای کار مهمی پیش خوارزمشاه فرستادند. مدتی آنجا بماند، گویا خوارزمشاه محبت و رعایتی چنان که او می خواست، نمی کرد. روزی پیش خوارزمشاه حکایت مرغان و خاصیت هر یکی می گفتند ، طلحک گفت : هیچ مرغی از لک لک زیرکتر نیست، گفتند : از چه دانی ؟ گفت : از بهر آن که هرگز به خوارزم نمی آید.!!"},{"id":985,"category_id":7,"category_code":"s7","source_id":155,"title":"گرگ مکار و شتر","content":"آورده اند که گرگی و شتری خانه یکی شدند و قرار گذاشتند که از آن پس جدایی از میان برداشته شود و دو خانواده ، یکی بشمار رود و مابین کودکان آنها هم تفاوتی نباشد.\r\nروزی شتر برای تلاش معاش به صحرا رفت. گرگ یکی از بچه های او را خورد و در گوشه ای خزید. چون سروکله ی شتر از دور پیدا شد ، گرگ پیش دوید و گفت : ای برادر بیا که یکی از بچه هایمان نیست.\r\nشتر بیچاره نگران شد و پرسید: یکی از بچه های من یا بچه های تو؟\r\nگرگ پاسخ داد : رفیق بازهم من و تویی کردی؟ یکی از آن پاپهن هایمان!!!\r\n"},{"id":986,"category_id":7,"category_code":"s7","source_id":156,"title":"رشته فلسفه چطوریه ؟","content":"یکی از دانشجویان رشته ی فلسفه می گفت : در سال اولی که ما شروع به خواندن فلسفه کردیم ، هم استاد و هم دانشجو ، مطالب را درک می کردند. در سال دوم فقط استاد می فهمید و ما نمی فهمیدیم ولی در سال سوم نه او می فهمید چه میگوید و نه ما می فهمیدیم چه می خوانیم."},{"id":987,"category_id":7,"category_code":"s7","source_id":157,"title":"ارسطو و مرد پرحرف","content":"شخص پرحرفی ارسطو را گیر آورده و به قدری حرف زد که او را خسته کرد و بالاخره در ضمن صحبت های خود گفت : آیا از این تفضیلاتی که عرض می کنم ، هیچ تعجبی نکرده اید؟\r\nارسطو گفت : از صحبت ها خیر ، تعجب و تحیرم برای این است که با وجود این که خدا دو پا برای فرار داده ، من از دست شما فرار نمی کنم.!!!\r\n"},{"id":988,"category_id":7,"category_code":"s7","source_id":158,"title":"حکایت شیر و خر","content":"یک شیر و یک خر در بیشه ای زندگی می کردند. شیر زورگو کارش فقط زدن خر بود؛ هر بار که او را می دید ، کتک مفصلی به او می زد. بالاخره یک روز خر بیچاره آنجا را ترک کرد و رفت.\r\nهنوز چند روزی نگذشته بود که یک گوره خر به آن طرف ها آمد. شیر جلوی او را گرفت و گفت : تو فکر می کنی، اگر لباست را عوض کنی ، من دیگر نمی شناسمت؟\r\nو گوره خر بیچاره را به باد کتک گرفت.\r\n"},{"id":989,"category_id":7,"category_code":"s7","source_id":159,"title":"راننده","content":"ﭼﻬﺎﺭ ﻧﻔﺮ ﺳﻮﺍﺭ ﺗﺎﮐسی ﻣﯿﺸﻦ ﻭﻟﯽ\r\nﮐﺮﺍﯾﻪ ﻧﺪﺍﺷﺘﻦ ﺑﺪﻥ! ﻗﺮﺍﺭﮔﺬﺍﺷﺘﻦ ﺑﻪ\r\nﻣﻘﺼﺪ ﮐﻪ ﺭﺳﯿﺪﻥ ﭘﯿﺎﺩﻩ ﺑﺸﻦ ﻭ فرار کنن !\r\nﺑﻌﺪﺍﺯ ﺭﺳﯿﺪﻥ ﺑﻪ ﻣﻘﺼﺪ ﭼﻬﺎﺭﺗﺎﺷﻮﻥ\r\nﺩﺭﺍﯼ ﻣﺎﺷﯿﻨﻮ ﺑﺎﺯﻣﯿﮑﻦ ﻭ با سرعت\r\nﭘﺎ ﺑﻪ ﻓﺮﺍﺭ ﻣﯿﺬﺍﺭﻥ..\r\nﻣﯿﺮﻥ ﺗﺎ ﻣﯿﺮﺳﻦ ﺑﻪ ﯾﻪ ﺳﺎﺧﺘﻤﻮﻥ ﺗﺎﺭﯾﮏ ﻫﯿﭽﮑﯽ ﻫﯿﭽﮑﯽ\r\nﺭﻭ ﻧﻤﯿﺪﯾﺪ ﻭ ﻓﻘﻂ ﺻﺪﺍﯼ تند تند زدن ﻧﻔﺴﺸﻮﻥ ﻣﯿﺎﺩ\r\nﯾﮑﯿﺸﻮﻥ زد رو شونه ﺑﻐﻠﯿﺶ ﺑﻬﺶ ﮔﻔﺖ ﻓﮑﺮﺷﻮ بکن ﺣﺎﻻ ﺭﺍﻧﻨﺪﻩﭼﻪ ﺣﺎﻟﯽ داره !\r\nبهش گفت بابا راننده منم، فقط بگین چی شده !؟\r\n"},{"id":990,"category_id":7,"category_code":"s7","source_id":160,"title":"سیگار","content":"ﺩﺧﺘﺮﻩ ﺍﺯ ﭘﺪﺭﺵ ﭘﺮﺳﯿﺪﻩ : ﺑﺎﺑﺎ ! \r\nﺍﮔﻪ ﯾﻪ ﻧﻔﺮ ﮐﻪ ﺧﯿﻠﯽ\r\nﺩﻭﺳﺘﺶ ﺩﺍﺭﯼ ﯾﻪ ﮐﺎﺭ ﺑﺪﯼ ﺑﮑﻨﻪ، ﻣﻦ ﭼﯽ ﮐﺎﺭ ﺑﺎﯾﺪ\r\nﺑﮑﻨﻢ؟\r\nﭘﺪﺭ ﺟﻮﺍﺏ ﺩﺍﺩ : ﺑﺎﯾﺪ ﺑﻬﺶ ﺑﮕﯽ ﺍﯾﻦ ﮐﺎﺭ ﺧﻮﺑﯽ\r\nﻧﯿﺴﺖ . ﺍﯾﻦ ﮐﺎﺭﻭ ﻧﮑﻦ !\r\nﭘﺮﺳﯿﺪ : ﺍﮔﻪ ﺭﻭﻡ ﻧﺸﻪ ﺑﻬﺶ ﺑﮕﻢ ﭼﯽ؟\r\nﺟﻮﺍﺏ ﺩﺍﺩ : ﺧﺐ ﺭﻭﯼ ﯾﻪ ﺗﯿﮑﻪ ﮐﺎﻏﺬ ﺑﻨﻮﯾﺲ ﺑﺬﺍﺭ ﺗﻮﯼ\r\nﺟﯿﺒﺶ.\r\nﺻﺒﺢ ﮐﻪ ﻣﺮﺩ ﺑﺮﺍﯼ ﺭﻓﺘﻦ ﺑﻪ ﺍﺩﺍﺭﻩ ﺁﻣﺎﺩﻩ ﻣﯿﺸﺪ، ﺩﺭ\r\nﺟﯿﺐ ﮐﺘﺶ ﮐﺎﻏﺬﯼ ﭘﯿﺪﺍ ﮐﺮﺩ ﮐﻪ ﺭﻭﺵ ﻧﻮﺷﺘﻪ ﺑﻮﺩ\r\nﺑﺎﺑﺎ ﺳﻼﻡ. ﺳﯿﮕﺎﺭ ﮐﺸﯿﺪﻥ ﮐﺎﺭ ﺧﻮﺑﯽ ﻧﯿﺴﺖ. ﻟﻄﻔﺎً ﺍﯾﻦ\r\nﮐﺎﺭ ﺭﻭ ﻧﮑﻦ !\r\nﭘﺪﺭ ﺍﺷﮏ ﺩﺭ ﭼﺸﻤﺎﻧﺶ ﺟﻤﻊ ﺷﺪ\r\nﻭ ﺭﻭﯼ ﮐﺎﻏﺬ ﻧﻮﺷﺖ\r\n ﺩﺧﺘﺮ ﻋﺰﻳﺰﻡ: \r\nﮔﻮﻩ ﺧﻮﺭﯾﺶ ﺑﻪ ﺗﻮ ﻧﯿﻮﻣﺪﻩ!\r\n"},{"id":991,"category_id":7,"category_code":"s7","source_id":161,"title":"مادر","content":"تو خیابون یه مرد میانسالی جلومو گرفت , گفت\r\nآقا ببخشید, مادر من تو اون آسایشگاه روبرو نگهداری میشه, من روم نمیشه چشم تو چشمش بشم چون زنم مجبورم کرد ببرمش اونجا, این امانتی رو اگه از قول من بهش بدید خیلی لطف کردید.\r\nقبول کردم و کلی هم نصیحتش کردم که مادرته بابا, اونم ابراز پشیمونی کرد و رفتم داخل آسایشگاه, پیر زن رو پیدا کردم, گفتم این امانتی مال شماس, گفت حامد پسرم تویی؟\r\nگفتم نه مادر, دیدم دوباره گفت حامد تویی مادر؟\r\nدلم نیومد این سری بگم نه , گفتم آره, پیرزنه داد زن میدونستم منو تنها نمی ذاری,\r\nشروع کرد با ذوق به صدا کردن پرستار که دیدی پسر من نامهربون نیست؟\r\nپرستاره تا اومد گفت شما پسرشون هستید؟\r\nتا گفتم آره دستمو گرفت, گفت 4 ماه هزینه ی نگهداری مادرتون عقب افتاده , باید تسویه کنید\r\nحالا از من هی غلط کردم واینکه من پسرش نیستم ولی دیگه باور نمی کردن\r\nآخر چک و نوشتم دادم دستش, ولی ته دلم راضی بود که باز این پیر زن و خوشحال کردم , هر چند که پسرش خیلی ... بود.\r\nاومدم از پیرزنه خدافظی کنم تا منو دید گفت دستت درد نکنه , رفتی بیرون به پسرم حامد بگو پرداخت شد , بیا تو مادر!!! :)))\r\n"},{"id":992,"category_id":7,"category_code":"s7","source_id":162,"title":"راننده کامیون","content":"راننده کامیونی وارد رستوران شد . دقایقی پس از این که او شروع به غذا خوردن کرد ، سه جوان موتور سیکلت سوار هم به رستوران آمدند و یک راست به سراغ میز راننده کامیون رفتند . بعد از چند دقیقه پچ پچ کردن ، اولی سیگارش را در استکان چای راننده خاموش کرد . راننده به او چیزی نگفت .\r\nدومی شیشه نوشابه را روی سر راننده خالی کرد و باز هم راننده سکوت کرد .\r\nوقتی راننده بلند شد تا صورتحساب رستوران را پرداخت کند ، نفر سوم به پشت او پا زد و راننده محکم به زمین خورد ، ولی باز هم ساکت ماند .\r\nدقایقی بعد از خروج راننده از رستوران یکی از جوان ها به صاحب رستوران گفت : چه آدم بی خاصیتی بود ، نه غذا خوردن بلد بود ، نه حرف زدن و نه دعوا !\r\nرستورانچی جواب داد : از همه بد تر رانندگی بلد نبود ، چون وقتی داشت می رفت دنده عقب ، 3 تا موتور نازنین را له کرد و رفت !!!\r\n"},{"id":993,"category_id":7,"category_code":"s7","source_id":163,"title":"لکنت زبون","content":"طرف لکنت زبون داشته.\r\nزنگ میزنه اورژانس که بیان جنازه ی همسایشو ببرن!\r\nمیگه: اااالو اااوورجانس ،این ههههمسسسایمووون ممممرده!\r\nیه آمبولانس میفرررررستین؟!...\r\nطرف میگه: آدرستون؟!\r\nیارو تا میاد آدرسو بگه زبونش بند میاد میگه: ظظظظظ!.........\r\nطرف میگه :ظفر منظورته ؟\r\nمیگه: نننننننـــنه!\r\nطرف فکر میکنه سرکاره قطع میکنه!\r\nیه هفته بعد همین اتفاق میفته بازم طرف میگه :آدرستون؟\r\nباز زبونِ یارو بند میاد میگه: ظظظ ظ!\r\nطرف میگه ظفر؟ میگه: ننننه!\r\nباز مامور اورژانس فکر میکنه سرکاره قطع میکنه!\r\nیک! ماه رد میشه،باز طرف زنگ میزنه میگه:\r\nاااااووووورژانس، این هههمسایمون ممممرده محلللمون بوی گند\r\nگررررررفته یه آمبولانس بببفرستیییین!\r\nطرف میگه :آدرستون؟!\r\nباز زبون یارو بند میاد میگه: ظظظظ!\r\nاز اونور میگن :آقا منظورت ظفره؟!\r\nطرف میگه :آآآآررررره آآآآشغااااال؛\r\nآآآآررره کککککثافت\r\nککشووووندم آورددددمش ظفرببییییا بببرش\r\n"},{"id":994,"category_id":7,"category_code":"s7","source_id":164,"title":"پسر و دخترم","content":"ﺍﺯ ﺧﺎﻧﻤﯽ ﭘﺮﺳﯿﺪﻧﺪ : ﺷﻨﯿﺪﻩ ﺍﻡ ﭘﺴﺮ ﻭ ﺩﺧﺘﺮﺕ ﻫﺮ\r\nﺩﻭ ﺍﺯﺩﻭﺍﺝ ﮐﺮﺩﻩ ﺍﻧﺪ، ﺁﯾﺎ ﺍﺯ ﺯﻧﺪﮔﯽ ﺧﻮﺩ ﺭﺍﺿﯽ\r\nﻫﺴﺘﻨﺪ ؟\r\nﺧﺎﻧﻢ ﺟﻮﺍﺏ ﺩﺍﺩ : ﺩﺧﺘﺮﻡ ﺯﻧﺪﮔﯽ ﺧﻮﺷﯽ ﭘﯿﺪﺍ ﮐﺮﺩﻩ\r\nﮐﻪ ﻣﻦ ﻫﻤﯿﺸﻪ ﺑﺮﺍﯾﺶ ﺁﺭﺯﻭ ﻣﯽ ﮐﺮﺩﻡ . ﺍﺑﺪﺍ ﺩﺳﺖ\r\nﺑﻪ ﺳﯿﺎﻩ ﻭ ﺳﻔﯿﺪ ﻧﻤﯽ ﺯﻧﺪ .\r\nﺻﺒﺤﺎﻧﻪ ﺭﺍ ﺩﺭ ﺭﺧﺘﺨﻮﺍﺏ ﻣﯽ ﺧﻮﺭﺩ . ﺑﻌﺪ ﺍﻇﻬﺮﻫﺎ ﻫﻢ\r\nﺩﻭ ﺳﻪ ﺳﺎﻋﺘﯽ ﻣﯽ ﺧﻮﺍﺑﺪ . ﻋﺼﺮ ﺑﺎ ﺩﻭﺳﺘﺎﻧﺶ ﺑﻪ\r\nﮔﺮﺩﺵ ﻣﯽ ﺭﻭﺩ ﻭ ﺷﺐ ﻫﻢ ﺑﺎ ﺗﻔﺮﯾﺤﺎﺗﯽ ﻣﺜﻞ ﺳﯿﻨﻤﺎ\r\nﻭ ﺗﻠﻮﯾﺰﯾﻮﻥ ﺳﺮ ﺧﻮﺩ ﺭﺍ ﮔﺮﻡ ﻣﯽ ﮐﻨﺪ . ﯾﻘﯿﻦ ﺩﺍﺭﻡ\r\nﮐﻪ ﺩﺍﻣﺎﺩﻡ ﻫﻢ ﺑﺎ ﺩﺍﺷﺘﻦ چنین ﻫﻤﺴﺮﯼ ﺳﻌﺎﺩﺗﻤﻨﺪ ﺍﺳﺖ !\r\nﭘﺮﺳﯿﺪﻥ ﻭﺿﻊ ﭘﺴﺮﺕ ﭼﻄﻮﺭ ﺍﺳﺖ ؟\r\nﮔﻔﺖ : ﺍﻭﻩ ﺍﻭﻩ !!! ﺧﺪﺍ ﻧﺼﯿﺐ ﻧﮑﻨﺪ ! ﺑﻼ ﺑﺪﻭﺭ ، ﯾﮏ\r\nﺯﻥ ﺗﻨﺒﻞ ﻭ ﻭ ﻭﺍﺭﻓﺘﻪ ﺍﯼ ﺩﺍﺭﺩ ﮐﻪ ﺍﻧﮕﺎﺭ ﺧﺎﻧﻪ ﺷﻮﻫﺮ\r\nﺭﺍ ﺑﺎ ﺗﻨﺒﻞ ﺧﺎﻧﻪ ﺍﺷﺘﺒﺎﻩ ﮔﺮﻓﺘﻪ ﺍﺳﺖ .\r\nﺩﺳﺖ ﺑﻪ ﺳﯿﺎﻩ ﺳﻔﯿﺪ ﮐﻪ ﻧﻤﯽ ﺯﻧﺪ . ﺍﺻﺮﺍﺭ ﺩﺍﺭﺩ ﮐﻪ\r\nﺻﺒﺤﺎﻧﻪ ﺭﺍ ﺩﺭ ﺭﺧﺘﺨﻮﺍﺏ ﺑﺨﻮﺭﺩ .\r\nﺗﺎ ﻇﻬﺮ ﺩﻫﻦ ﺩﺭﻩ ﻣﯽ ﮐﻨﺪ . ﺑﻌﺪ ﺍﻇﻬﺮ ﻫﺎ ﺑﺎﺯ ﺗﺎ\r\nﻏﺮﻭﺏ ﺧﺒﺮ ﻣﺮﮔﺶ ﮐﭙﯿﺪﻩ ! ﻋﺼﺮ ﻫﻢ ﺍﺯ ﺧﺎﻧﻪ ﺑﯿﺮﻭﻥ\r\nﻣﯽ ﺭﻭﺩ ﻭ ﺗﺎ ﻧﺼﻔﻪ ﺷﺐ ﻣﺸﻐﻮﻝ ﮔﺮﺩﺵ ﺍﺳﺖ . ﺑﺎ\r\nﻭﺟﻮﺩ ﺍﯾﻦ ﺯﻥ ، ﭘﺴﺮﻡ ﺑﺪﺑﺨﺖ ﺍﺳﺖ\r\n"},{"id":995,"category_id":7,"category_code":"s7","source_id":165,"title":"فداکاری","content":"ﺩﻩ ﻣﺮﺩ ﻭ ﯾﮏ ﺯﻥ ﺑﻪ ﻃﻨﺎﺑﯽ ﺁﻭﯾﺰﺍﻥ ﺑﻮﺩﻧﺪ ﻃﻨﺎﺏ\r\nﺗﺤﻤﻞ ﻭﺯﻥ ﯾﺎﺯﺩﻩ ﻧﻔﺮ ﺭﺍ ﻧﺪﺍﺷﺖ ﺑﺎﯾﺪ ﯾﮑﻨﻔﺮ ﻃﻨﺎﺏ ﺭﺍ\r\nﺭﻫﺎ ﻣﯿﮑﺮﺩ ﻭﮔﺮﻧﻪ ﻫﻤﻪ ﺳﻘﻮﻁ ﻣﯿﮑﺮﺩﻧﺪ ﺯﻥ ﮔﻔﺖ:\r\nﻣﻦ ﺩﺭ ﺗﻤﺎﻡ ﻋﻤﺮ ﻫﻤﯿﺸﻪ ﻋﺎﺩﺕ ﺩﺍﺷﺘﻢ ﮐﻪ ﺩﺍﻭﻃﻠﺒﺎﻧﻪ\r\nﺧﻮﺩﻡ ﺭﺍ ﻭﻗﻒ ﻓﺮﺯﻧﺪﺍﻥ ﻭ ﻫﻤﺴﺮﻡ ﮐﻨﻢ ﻭ ﺩﺭ ﻣﻘﺎﺑﻞ\r\nﭼﯿﺰﯼ ﻣﻄﺎﻟﺒﻪ ﻧﮑﻨﻢ ... ﻣﻦ ﻃﻨﺎﺏ ﺭﺍ ﺭﻫﺎ ﻣﯿﮑﻨﻢ ﭼﻮﻥ\r\nﺑﻪ ﻓﺪﺍﮐﺎﺭﯼ ﻋﺎﺩﺕ ﺩﺍﺭﻡ ﺩﺭ ﺍﯾﻦ ﻟﺤﻈﻪ ﻣﺮﺩﺍﻥ ﺳﺨﺖ ﺑﻪ\r\nﻫﯿﺠﺎﻥ ﺁﻣﺪﻧﺪ ﻭ ﺷﺮﻭﻉ ﺑﻪ ﮐﻒ ﺯﺩﻥ ﮐﺮﺩﻧﺪ.\r\n"},{"id":996,"category_id":7,"category_code":"s7","source_id":166,"title":"عشق ورزی","content":"ﺭﻭﺯﯼ ﻣﺮﺩﯼ ﻋﻘﺮﺑﯽ ﺭﺍ ﺩﯾﺪ ﮐﻪ ﺩﺭﻭﻥ ﺍﺏ ﺩﺳﺖ ﻭ ﭘﺎﻣﯿﺰﻧﺪ،ﺍﻭ ﺗﺼﻤﯿﻢ ﮔﺮﻓﺖ ﻋﻘﺮﺑ ﺮﺍ ﻧﺠﺎﺕ ﺩﻫﺪﺍﻣﺎ ﻋﻘﺮﺏ ﺍﻧﮕﺸﺖ ﺍﻭ ﺭﺍ ﻧﯿﺶ ﺯﺩ .\r\nﻣﺮﺩ ﺑﺎﺯ ﻫﻢ ﺳﻌﯽ ﮐﺮﺩ ﺗﺎ ﻋﻘﺮﺏ ﺭﺍ ﺍﺯ ﺍﺏ ﺑﯿﺮﻭﻥﺑﯿﺎﻭﺭﺩ،ﺍﻣﺎﻋﻘﺮﺏ ﺑﺎﺭ ﺩﯾﮕﺮ ﺍﻭ ﺭﺍ ﻧﯿﺶ ﺯﺩ .\r\nﺭﻫﮕﺬﺭﯼ ﺍﻭ ﺭﺍ ﺩﯾﺪ ﻭﭘﺮﺳﯿﺪ : ﺑﺮﺍﯼ ﭼﻪ ﻋﻘﺮﺑﯽ ﺭﺍ ﮐﻪﻧﯿﺶﻣﯿﺰﻧﺪ ﻧﺠﺎﺕ ﻣﯿﺪﻫﯽ؟\r\nﻣﺮﺩ ﭘﺎﺳﺦ ﺩﺍﺩ: ﺍﯾﻦ ﻃﺒﯿﻌﺖ ﻋﻘﺮﺏ ﺍﺳﺖ ﮐﻪ ﻧﯿﺶ ﺑﺰﻧﺪ ﻭﻟﯽ ﻃﺒﯿﻌﺖﻣﻦ ﺍﯾﻦﺍﺳﺖ ﮐﻪ ﻋﺸﻖ ﺑﻮﺭﺯﻡ \r\n\r\n.\r\n.\r\n.\r\n.\r\n\r\n\r\nﺭﻫﮕﺬﺭ ﮔﻔﺖ : ﺁﻧﻘﺪﺭ ﻋﺸﻖ ﺑﻮﺭﺯ ﺗﺎ جونت درآد! \r\n"},{"id":997,"category_id":7,"category_code":"s7","source_id":167,"title":"زرنگی همیشه جواب نمیده","content":"\r\nیه بنده خدا نشسته بود داشت تلویزیون میدید که یهو مرگ اومد پیشش …\r\nمرگ گفت : الان نوبت توئه که ببرمت …\r\nطرف یه کم آشفته شد و گفت : داداش اگه راه داره بیخیال ما بشو بذار واسه بعد …\r\nمرگ : نه اصلا راه نداره. همه چی طبق برنامست. طبق لیست من الان نوبت توئه …\r\nاون مرد گفت : حداقل بذار یه شربت بیارم خستگیت در بره بعد جونمو بگیر …\r\nمرگ قبول کرد و اون مرد رفت شربت بیاره …\r\nتوی شربت 2 تا قرص خواب خیلی قوی ریخت …\r\nمرگ وقتی شربته رو خورد به خواب عمیقی فرو رفت …\r\nمرد وقتی مرگ خواب بود لیستو برداشت اسمشو پاک کرد و نوشت آخر لیست\r\nو منتظر شد تا مرگ بیدار شه …\r\nمرگ وقتی بیدار شد گفت : دمت گرم داداش حسابی حال دادی خستگیم در رفت!\r\nبخاطر این محبتت منم بیخیال تو میشم و میرم از آخر شروع به جون گرفتن میکنم!\r\n"},{"id":998,"category_id":7,"category_code":"s7","source_id":168,"title":"باد شکم","content":"\r\nسوار تاکسی بودم که یه خانم جوان با یه پسر بچه زبل ۵-۶ ساله\r\nکنارم نشست . بچه هه خیلی بپر بپر می کرد و تاکسی رو روی\r\nسرش گذاشته بود . خانومه هرچی گفت ساکت!نشد که\r\nنشد.آخرسر خانومه یه نیشگون اساسی از بچه هه گرفت که داد\r\nبچه بالارفت .\r\nبچه ی زبل با گریه گفت منو زدی؟حالا به بابا می گم دیشب خونه ی\r\nعمو اینا چیکار کردی. زنه که دید خیلی ناجور شد،گفت :چیکار\r\nکردم؟بچه هه گفت: خب گوزیدی! حالا ما سفت خودمونو گرفته\r\nبودیم که نخندیم و مثلا اصلا چیزی نشنیدیم ، ولی خود زنه اونقدر\r\nدست پاچه شد که به راننده گفت آقا آقا ما همین بغل پیاده می\r\nشم.ماشین نگه داشته – نداشته در رو باز کرد که بپره پائین .\r\nیهو یه ماشین دیگه از راه رسید و زد درب تاکسی کلا کنده شد. حالا\r\nمردم جمع شده بودند و راننده تاکسی که یه پیر مردی بود ، داد می\r\nزد و به زنه می گفت : آخه خواهر من، مادر من ،تو که منو بیچاره\r\nکردی! خب همه می گوزن . منم می گوزم ،اینم می گوزه . آقا شما\r\nنمی گوزی ؟ شما چی ، شما نمی گوزی ؟…\r\n"},{"id":999,"category_id":7,"category_code":"s7","source_id":169,"title":"زشت ترین زن","content":"مردی تعریف می کرد که با دو دوستش به جنگل های آمازون رفته بود و در آنجا گرفتار قبیله زنان وحشی شدند و آنها دو دوستش را کشتند. وقتی از او پرسیدند چرا تو زنده ماندی، گفت: زن های وحشی آمازون از هر یک از ما خواستند چیزی را از آنها بخواهیم که نتوانند انجام بدهند. خواسته های دو دوستم را انجام دادند و آنها را کشتند. وقتی نوبت به من رسید به آنها گفتم: لطفا زشت ترین شما مرا بکشد! "},{"id":1000,"category_id":7,"category_code":"s7","source_id":170,"title":"سمعک","content":"يارو ميره سمعک بخره فروشنده ميگه: همه جورشو داريم از هزار تومني تا يک ميليون تومني.\r\nطرف ميپرسه: هزارتومني اش چطوري کارمي کنه؟ فروشنده ميگه: اين اصلا کار نميکنه فقط مردم با ديدنش بلندتر حرف میزنند. \r\n"},{"id":1001,"category_id":7,"category_code":"s7","source_id":171,"title":"پناهنده","content":"مردی می ره پیش کشیش تا اعتراف کنه. می گه: من در زمان جنگ جهانی دوم به یک مرد در خانه خودم پناه دادم.\r\nکشیش می گه: خوب این که گناه نیست!\r\nمرد می گه: ولی من بهش گفتم برای هر یک هفته ای که در خانه من بمونه باید ۵ دلار بپردازه.\r\nکشیش می گه: درسته که کارت خوب نبوده، ولی تو با نیت خوبی این کار رو انجام دادی.\r\nمرد می گه: اوه! متشکرم! خیالم راحت شد. فقط یه سوال دیگه…\r\nکشیش می گه: بگو فرزندم.\r\nمرد می گه: آیا باید بهش بگم که جنگ تموم شده؟\r\n"},{"id":1002,"category_id":7,"category_code":"s7","source_id":172,"title":"وصیت نامه","content":"پیرمردی مشکل شنوایی داشته و هیچ صدایی رو نمی تونسته بشنوه.\r\nبعد از چند سال بالاخره با یک دارویی خوب می شه.\r\nدو سه هفته می گذره و می ره پیش دکترش که بگه گوشش حالا می شنوه.\r\nدکتر خیلی خوشحال می شه و می گه: خانواده شما هم باید ظاهرا خیلی خوشحال باشن که شنوایی تون رو بدست آوردید.\r\nپیرمرد می گه: نه، من هنوز بهشون چیزی نگفته ام! هر شب می شینم و به حرف هاشون گوش می کنم… فقط تنها اتفاقی که افتاده اینه که توی این مدت تا حالا چند بار وصیت نامه ام رو عوض کرده ام!\r\n"},{"id":1003,"category_id":7,"category_code":"s7","source_id":173,"title":"معرفی خود","content":"روزی لئون تولستوی در خیابانی راه می رفت که ناآگاهانه به زنی تنه زد. زن بی وقفه شروع به فحش دادن و بد وبیراه گفتن کرد .\r\nبعد از مدتی که خوب تولستوی را فحش مالی کرد ،تولستوی کلاهش را از سرش برداشت و محترمانه معذرت خواهی کرد و در پایان گفت : مادمازل من لئون تولستوی هستم .\r\nزن که بسیار شرمگین شده بود ،عذر خواهی کرد و گفت :چرا شما خودتان را زودتر معرفی نکردید ؟\r\nتولستوی در جواب گفت : شما آنچنان غرق معرفی خودتان بودید که به من مجال این کار را ندادید!!!\r\n"},{"id":1004,"category_id":7,"category_code":"s7","source_id":174,"title":"کارت پخش کن","content":"یه روز تو پیاده رو داشتم می رفتم ، از دور دیدم یک کارت پخش کن خیلی با کلاس ، کارت های رنگی قشنگی دستشه ولی این کارت ها رو به هر کسی نمیده ! به خانم ها که اصلاً نمی داد و تحویلشون نمی گرفت ،\r\nدر مورد اقایون هم خیلی گزینشی رفتار می کرد و معلوم بود فقط به کسانی کارت میداد که مشخصات خاصی از نظر خودش داشته باشند ، احساس کردم فکر میکنه هر کسی لیاقت داشتن این تبلیغات تمام رنگی خیلی خوشگل و گرون قیمت رو نداره ، لابد فقط به ادم های با کلاس و شیک پوش و با شخصیت میده ! بدجوری کنجکاو بودم بدونم اون کارت ها چین !! با خودم گفتم یعنی نظر این کارت پخش کن خوش تیپ و با کلاس راجع به من چیه ؟! منو تائید می کنه ؟!\r\nکفش هامو با پشت شلوارم پاک کردم تا مختصر گرد و خاکی که روش نشسته بود پاک بشه و برق بزنه ! شکمو دادم تو و در عین حال سعی کردم خودم رو جوری نشون بدم که انگار واسم مهم نیست ! دل تو دلم نبود ! یعنی به من هم از این کاغذهای خوشگل میده ؟! همین طور که سعی می کردم با بی تفاوتی از کنارش رد بشم با لبخندی بهم نگاه کرد و یک کاغذ رنگی طرفم گرفت و گفت : اقای محترم ! بفرمایید !\r\nقند تو دلم اب شد ! با لبخندی ظاهری و با حالتی که نشون بدم اصلا برام مهم نیست بهش گفتم : می گیرمش ولی الان وقت خوندنش رو ندارم ! چند قدم اونورتر پیچیدم توی قنادی و اون قدر هول بودم که داشتم با سر می رفتم توی کیک ! وایستادم و با ذوق تمام به کاغذ نگاه کردم ، فکر می کنید رو کاغذ چی نوشته بود ؟؟\r\n.\r\n.\r\n.\r\n.\r\n.\r\n.\r\n.\r\n.\r\n.\r\n.\r\n.\r\nدیگر نگران طاسی سر خود نباشید ! پیوند مو با جدیدترین متد روز اروپا و امریکا !! \r\n"},{"id":1005,"category_id":7,"category_code":"s7","source_id":175,"title":"فیلمبردار","content":"واسه بازی پرسپولیس و فولاد رفته بودم استادیوم ، اخرای بازی بود که یکی از دوربینهای صدا سیما زوم کرده بود روی من بیچاره و داشت زنده ، تصویرم رو پخش میکرد!!\r\nمن از خدا بیخبر هم انگشتم رو تا ته کرده بودم تو دماغم و 360 درجه میچرخوندم ... بعد انگشتم رو در اوردم و مالیدم به لباس نفر کناریم!!\r\nبعد از چند لحظه مهرناز باهام تماس گرفت و با گریه بهم گفت :\r\nخاک تو سرت ، بی فرهنگ.! فقط میخواستی ابروی من رو جلو دوستام ببری... دیگه یه لحظه هم نمیخوام ببینمت!! تا اومدم بگم چی شده زرتی قطع کرد!!\r\nهنوز گوشیم رو تو جیبم نزاشته بودم که بابام تماس گرفت و گفت:\r\nحالا به جا دانشگاه میپیچونی میری فوتبال ببینی اره !!! امشب اومدی خونه اون دماغت رو صاف میکنم ، پسره ی بی شخصیت!!\r\nاونم زارت قطع کرد!!\r\nدوباره گوشیم صداش در اومد. اینبار جاسم بود... دوستم.. گفت:\r\nاقا چه صحنه ای بود... کلی خندیدیم با بچه ها... یادت باشه اومدی یه دکتر زیبایی بهت معرفی کنم ، اون دماغت رو عمل کنی!!\r\nزارت قطع کرد!!\r\nهنوز تو شوک حرفای این سه نفر بودم که دیدم ، نفر کناریم داره با عصبانیت نگام میکنه و یهو یه کشیده ی محکم خابوند تو گوشم و گفت:\r\nتا تو باشی دفعه ی بعد اشغالای دماغت رو با لباس این و اون پاک نکنی!!\r\n.\r\n.\r\n.\r\nیعنی اگه من دستم به اون فیلم بردار برسه...\r\n"},{"id":1006,"category_id":7,"category_code":"s7","source_id":176,"title":"گاو","content":"\r\nدوستی می گفت :\r\nتو جاده شمال بودم، یه دفه یه گاو پرید وسط جاده منم محکم زدم\r\nرو ترمز و خیلی عصبی شروع کردم بوق زدن که بره ، دیدم نه همینجوری وایساده وسط\r\nجاده داره چپ چپ نگام میکنه ،یه جوری نگام میکرد انگار منتظر بود پیاده شم روشو\r\nببوسم ازش عذرخواهی کنم ، یعنی درگیر جذبش شده بودم ، بعد دو سه دیقه دیدم دیگه\r\nخیلی بد داره نگا میکنه، اومدم پیاده شم دیدم گاوه یه نگا به من کرد یه نگا به تابلوی محل\r\nعبور حیوانات اهلی اونور جاده، بعد با افسوس سرشو انداخت پایینو رفت، یعنی این\r\nحرکتش از فحش خوارو مادر بدتر بود، کلی خجالت زدمون کرد، فقط مونده بود قبل رفتن\r\nیکم نصیحتم کنه.\r\n"},{"id":1007,"category_id":7,"category_code":"s7","source_id":177,"title":"بازاریابِ","content":"یه بازاریابِ جارو برقی درِ یه خونه ای رو میزنه، و تا خانمِ خونه در رو باز میکنه قبل از اینکه حرفی زده بشه، بازاریاب میپره تو خونه و یه کیسه کود گاوی رو روی فرش خالی میکنه و میگه: اگه من قادر به جمع کردن و تمیز کردنِ همه ی اینها با این جاروبرقی قدرتمند نباشم حاضرم که تمامِ این گُـ ــه ها رو بخورم!\r\nخانوم میگه: سُــسِ سفید میخوای یا قرمز؟\r\nبازاریاب: چــــرا؟ \r\nخانوم: چند وقته برقِ خونه مون قطعه ..!\r\n"},{"id":1008,"category_id":7,"category_code":"s7","source_id":178,"title":"این به اون در!","content":"يكی از دانشمندان، گوش‌های بزرگی داشت. شخصی بر سبيل استهزا به او گفت: گوش‌های شما متناسب بدن يك انسان نيست. مرد دانشمند در جواب گفت: بله، درست است. اتفاقا گوش‌های شما هم برای جثه‌ی يك الاغ بسيار كوچك است."},{"id":1009,"category_id":7,"category_code":"s7","source_id":179,"title":"شارژ ایرانسل","content":"پیداشدن کارت شارژ ایرانسل توی جیب مرد متاهلی که خط همراه اول داره،\r\nمثل کشف ۱۰کیلو تریاکه توی ماشین یه قاچاقچی …….\r\nحکمش اعدامه… اعدام!\r\n"},{"id":1010,"category_id":7,"category_code":"s7","source_id":180,"title":"یک کیلو پنبه","content":"روزی نیوتن در محضر یک نفر نشسته بود.\r\nآن شخص از ایشان پرسید :\r\nشنیده ام شما گفتید : یک کیلو آهن و یک کیلو پنبه وزن برابر دارند؟؟؟ \r\nنیوتن گفت : بله همین طور است. \r\nمرد گفت یک کیلو پنبه و یک کیلو آهن آوردند .\r\nاول پنبه را به سر نیوتن زد سپس آهن را به سر نیوتن زد!!! \r\nنیوتن از درد نالید. مرد گفت :\r\nحالا کدام سنگینتر بود!!!!\r\nنیوتن از گفته خود پشیمان شد و فوراً در یکی از روستاها مشغول دامداری شد.\r\n"},{"id":1011,"category_id":7,"category_code":"s7","source_id":181,"title":"پیغام رییس","content":"\r\nباغ وحش مملو از جمعیتی بود که برای دیدن حیوانات آمده بودند، مدتی بعد به رئیس باغ وحش گزارش دادند که برخی از مردم هر نوع خوردنی به حیوانات می دهند و باعث مریضی آنها شده اند.\r\nرئیس باغ وحش رفت پشت بلندگو و اعلام کرد: شهروندان گرامی لطفا به هیچ کدام از حیوانات هیچ خوراکی ندهید،زیرا بعضی از آنها مریض شده اند.\r\nکمی بعد وقتی رئیس که فهمید تذکرش فایده نداشته با لحنی ناراحت در بلندگو اعلام کرد:همشهریان گرامی ازتون خواهش کردم خوراکی به حیوانها ندهید.\r\nاین تذکر هم بی فایده بود و رئیس مرتبه سوم با عصبانیت فریاد زد: بابا به چه زبونی باید بگم؟لطفا به این حیوانهای بی زبون خوراکی ندهید،چرا حرف حالیتون نمیشه؟\r\nنیم ساعت بعد رئیس دوباره رفت پشت بلندگو و با همان آرامش اولیه گفت:حیوانات عزیز، لطفا شما حرف منو گوش کنید و از دست انسانها خوراکی نگیرید!\r\n"},{"id":1012,"category_id":7,"category_code":"s7","source_id":182,"title":"علم بهتر است یا ثروت","content":"شيخ را گفتند : علم بهتر است يا ثروت ؟\r\nشيخ بی درنگ شمشير از ميان بيرون آورد و\r\nمانند جومونگ مريد بخت برگشته را به سه پاره ی نامساوی تقسيم نمود و\r\nگفت :سالهاست که هيچ خری بين دو راهی علم و ثروت گير نميکند! \r\nمريدان در حالی که انگشت به دندان گرفته و لرزشی وجودشان را فرا گرفت گفتند يا شيخ ما را دليلی عيان ساز تا جان فدا کنيم. \r\nشيخ گفت :در عنفوان جوانی مرا دوستی بود که با هم به مکتب می رفتيم ،\r\nدوستم ترک تحصيل کرد من معلم مکتب شدم\r\nحالا او پورشه دارد ، من پوشه...\r\nاو اوراق مشارکت دارد، و من اوراق امتحانی...\r\nاو عينک آفتابی من عينک ته استکانی...\r\nاو بيمه زندگانی ، من بيمه خدمات درمانی...\r\nاو سکه و ارز ، من سکته و قرض... \r\nسخن شيخ چون بدين جا رسيد مريدان نعره ای جانسوز برداشته و راهی کلاسهای آموزش اختلاس گشتندی\r\n"},{"id":1013,"category_id":7,"category_code":"s7","source_id":183,"title":"درد عشق","content":"در مکتب شیخ بحثی در گرفته بود و مریدان همچون مردان درون صف ارزاق از سر و کول هم بالا رفتندی ، یکی از مریدان میگفت : درد عشق از همه درد ها افزون تراست ، دیگری جفت پا وسط حرفش میپرید که ای نادان ، گرسنگی نکشیده ای که درد عشق از یاد بری... \r\nدیگری ابراز فضل میکرد که درد دندان بسی ازدو درد دیگر بدتر است ،و اندرین جمع هرکس دردی را بدترین میدانست ، از درد زایمان تابه تنگ آمدن از ش*ش در اتوبوس بین راهی... \r\nشیخ از دور بر این بحث عمیق نظاره مینمود . مریدی نالید که ای شیخ ، کدامیک را تائید مینمائی ؟\r\nشیخ گفت : هیچکدام ، زیرا تا به حال با مانتو و دامن و جوراب شلواري و چادر نرفته اي در مستراح كه نفهمي كدوم رو بالا بكشي، كدوم رو پايين كه در جا عاشقي از يادت برود ....\r\nمریدان جمله گریستند و نعره ها زدند تا بسر منزل مقصود دویدند.\r\n"},{"id":1014,"category_id":7,"category_code":"s7","source_id":184,"title":"یه بار خواستیم ورزش کنیم","content":"امروز صبح بعد از مدتها تصمیم گرفتم با دوستم بریم ورزش کنیم!\r\nگرمکن نارنجیمو پوشیدم و زدم بیرون.\r\nو حالا توجه کنید به تیکه‌های ملت :\r\n\r\nنارنگی! کجا میری؟\r\n پرتقال! بدو تا نخوردمت!\r\nهویج! مگه خرگوش دنبالت کرده؟\r\nته‌ سیگار!\r\nرفتگر! برو ۹ شب بیا بابا!\r\nچی‌توز موتوری!\r\nسن ایچ و دیگر هیچ!\r\nلینا توپی!! انقدر جون نده بابا!\r\nاسمارتیز! بقیه دوستات کجان؟\r\nبچه‌ها! بچه ها! گارفیلد!\r\nالان کدوم مسئول باید رسیدگی کنه؟\r\n"},{"id":1015,"category_id":7,"category_code":"s7","source_id":185,"title":"ذکاوت ایرانی","content":"سازمان بهداشت جهانی برای آزمایش یک واکسن خطرناک وجدید\r\nاحتیاج یه داوطلب داشت. از میان مراجعین فقط سه نفر\r\nواجد شرایط اعلام شدند:\r\nیک آلمانی ،یک فرانسوی و یک ایرانی\r\nقرار شد با تک تک آنان مصاحبه شود برای انتخاب نهایی\r\nمصاحبه از آلمانی پرسید: برای این کار چقدر پول میخواهید؟\r\nاو گفت من صد هزار دلار، این را میدهم به زنم که اگر از این واکسن مردم\r\nیا فلج شدم، زنم بی پول نماند\r\nمصاحبه گر او را مرخص کرد وهمین سوال را از فرانسوی نمود\r\nاو گفت من دویست هزار دلار میگیرم، صدهزار تا برای زنم و صد هزار تا برای معشوقه ام\r\nوفتی او هم رفت، ایرانی گفت من سیصد هزار دلار می خواهم\r\nصد هزار برای خودم\r\nصد هزار تا هم حق حساب شما\r\nصد هزار تاش هم میدیم به آلمانی که واکسن را بهش بزنیم !!!؟\r\n"},{"id":1016,"category_id":7,"category_code":"s7","source_id":186,"title":"پیری و معرکه گیری","content":"خانم میان سالی سکته قلبی کرد و سریعاً به بیمارستان منتقل شد. وقتی زیر تیغ جراح بود عملاً مرگ را تجربه کرد. زمانیکه بی هوش بود فرشته ای را دید.\r\nاز فرشته پرسید: آیا زمان مردنم فرا رسیده است؟\r\nفرشته پاسخ داد: نه، تو ۴۳ سال و ۲ ماه و ۸ روز دیگر فرصت خواهی داشت.\r\nبعد از به هوش آمدن برای بهبود کامل خانم تصمیم گرفت که در بیمارستان باقی بماند. چون به زندگی بیشتر امیدوار بود، چند عمل زیبایی انجام داد. جراحی پلاستیک، لیپساکشن، جراحی بینی، جراحی ابرو و … او حتی رنگ موی خود را تغییر داد.\r\nخلاصه از یک خانم میان سال به یک خانم جوان تبدیل شد!\r\nبعد از آخرین جراحی او از بیمارستان مرخص شد. وقتی برای عریمت به خانه داشت از خیابان عبور می کرد، با یک آمبولانس تصادف کرد و مرد!\r\nوقتی با فرشته مرگ روبرو شد بهش گفت: من فکر کردم که گفتی ۴۰ سال و اندی بعد مرگ من فرا می رسه؟ چرا من رو از جلوی آمبولانس نکشیدی کنار؟ چرا من مردم؟\r\n…\r\n…\r\n…\r\n…\r\nفرشته پاسخ داد؛ ببخشید، وقتی داشتی از خیابون رد می شدی نشناختمت....!\r\n"},{"id":1017,"category_id":7,"category_code":"s7","source_id":187,"title":"فرهاد جان...","content":"رفته بودم فروشگاه... \r\nيكي از اين فروشگاه بزرگا , اسم نميبرم تبليغ نشه براش \r\nيه پيرمرد با نوه اش اومده بود خريد، پسره هي زِر زٍر مي كرد. پيرمرد مي گفت: آروم باش فرهاد، آروم باش عزيزم!\r\nجلوي قفسه ي خوراكي ها، پسره خودشو زد زمين و داد و بيداد... \r\nپير مرده گفت: آروم فرهاد جان، ديگه چيزي نمونده خريد تموم بشه.\r\nدَم صندوق پسره چرخ دستي رو كشيد چنتا از جنسا افتاد رو زمين، پيرمرده باز گفت: فرهاد آروم! تموم شد، ديگه داريم ميريم بيرون!\r\nمن كف بُر شده بودم.\r\nبيرون رفتم بهش گفتم آقا شما خيلي كارت درسته اين همه اذيتت كرد فقط بهش گفتي فرهاد آروم باش!\r\nپيرمرده با اين قيافه :| منو نگاه كرد و گفت:\r\nعزيزم، فرهاد اسم مَنه! اون پدر سگ اسمش سيامكه!!\r\n"},{"id":1018,"category_id":7,"category_code":"s7","source_id":188,"title":"طلسم","content":"نمي دانم اسمش را چه واژه و لغتي بگذارم، چشم زدن، بدشانسي، قدم نحس و شوم، هنوز هم خودم پي نبرده ام. سال سوم راهنمايي بودم كه متوجه اين موضوع شدم. روزي كه به بغل دستي ام سركلاس رياضي گفتم: چه خودكار قشنگي داري! در همان لحظه از دستش افتاد و گويي كه از دماوند افتاده باشد، تكه تكه شد.\r\nدر بازي فوتبال در هر تيمي كه بازي مي كردم، هميشه باخت از آن ما بود و جالبتر اين كه طرفدار هر تيمي بودم يا مي باخت يا بازيكنانش به شدت مصدوم مي شدند.\r\nدر خدمت سربازي دسته اي كه من در آن بودم هميشه تنبيه مي شد. بعد از خدمت آثار اين موضوع وخيم تر شد.\r\nدر خيابان چند نفر ماشين هل مي دادند. من به كمك آنها رفتم. تا دستم بدنه ماشين را لمس كرد، سمت شاگرد ماشين كاملاً در جوي آب افتاد و در زاويه 45 درجه قرار گرفت. حتي نزديك بود كه واژگون شود!\r\nيك روز وقتي به خانه دايي ام رفتم، متوجه شدم كه يخچال فريزر زيبا و گرا نقيمتي خريده است. گفتم: مبارك باشد. تا دوشاخه آن را به پريز برق زدند، دود آبي رنگي از پشت يخچال بلند شد و بوي سوختگي خانه را فرا گرفت. همه چپ چپ نگاهم مي كردند، چون سوختن يخچال را از چشم من مي دانستند. دايي ام در حالي كه به زور جلوي عصبانيت خود را گرفته بود، به من نگاه غضبناك و خشني كرد و گفت: هنوز اولين قسط رو پرداخت نكرده ام، يخچال ناكار شد. و يا روزي كه به خانه عموي بزرگم رفتم، تا وارد شدم و بعد از سلام گفتم: زن عمو ناهار چي دارين؟ صداي تركيدن زودپز روي اجاق گاز، كه مانند انفجار بمب بود، همه را وحشت زده كرد. آشپزخانه با تمام وسايلش به كلي خسارت ديده بود. متوجه چرخيدن سر همه به طرف خودم شدم. زن عمويم كنترلش را از دست داد و درحالي كه دست مرا گرفته بود و به بيرون از خانه هدايت مي كرد، گفت: ديگه ناهار نداريم، شرّت رو كم كن!!\r\nو يا اين كه يك روز وقتي از خانه خارج شدم، متوجه دوستم شدم كه كاپوت ماشينش را نزديك خانه ما بالا زده و با موتور آن ور مي رفت. وقتي مرا ديد پشت ماشين خودش را مخفي كرد. اهميت ندادم و به طرفش رفتم. بعد ازتماشاي موتور به او گفتم كه موتور ايراد ندارد فقط سر باتري كثيف است. وقتي كه كارش تمام شد با اضطراب و دلهره ماشين را روشن كرد. لحظه اي كه صداي كاركردن روان و يكنواخت موتور را شنيد، با خوشحالي و تعجب فرياد كشيد: پسر، تو بالاخره طلسمو شكستي، ديگه قدمت نحس نيست! و به راه افتاد. هنوز چند متري را طي نكرده بود كه صداي تق و توق موتور بلند و ماشين در جايش ميخكوب شد. پياده شد و در حالي كه با هر دو دست بر سر خود مي كوبيد، به دنبال پيدا كردن سنگ بود كه به طرف من پرتاب كند. به ناچار فرار كردم. موتور ماشين ياتاق زده بود و هزينه اي گزاف به او تحميل شد.\r\nاز اين گونه اتفاقات نحس و شوم صدها خاطره دارم كه حتي يك رمان براي نوشتن آنها كم به نظر مي رسد. ديگر به اين نتيجه رسيده ام و يقين دارم كه نه تنها براي جامعه مفيد نيستم، بلكه مضر و خطرناكم. بعضي ها نامم را زلزله گذاشته اند وعده اي نيز ام الشرصدايم مي كنند. شهره خاص و عام شده ام. تا از خانه بيرون مي روم، كوچه و خيابان خلوت مي شود. برايم ثابت شده است كه براي حفظ آرامش و امنيت مردم بهتر است در خانه بمانم. اكنون چند ماه است كه كاملاً در خانه تنها هستم.\r\nگاه گاهي براي انجام كارهاي ضروري، شبانه از خانه خارج مي شوم.بعضي اوقات حتي از پنجره كه بيرون را تماشا مي كنم، باعث زمين خوردن افراد، يا افتادن وسايل از دستشان مي شوم. ديگر به پنجره هم نزديك نمي شوم. تلويزيون كهنه و سياه و سفيدي در اتاق تمام اوقات مرا پر كرده است واغلب مشغول تماشاي آن هستم. وقتي در سريا لها، عروسي يا نامزدي به هم مي خورد، يا تصادفي رخ مي دهد و يا در يك فيلم جنگي كساني كشته مي شوند، اين سؤال به ذهنم مي رسد كه آيا فيلم همين طور درست شده، يا به خاطر تماشاي من اين اتفاقات روي مي دهد. ديگر مي ترسم كسي را تماشا كنم و با فردي حرف بزنم، حتي خانواده ام. ترسم از اين است كه خسارات مالي جايش را با صدمات جاني عوض كند. صبحانه، ناهار و شام را از لاي در نيمه باز تحويل مي گيرم و ليست چيزهايي را كه لازم دارم روي كاغذ مي نويسم و از زيردر به بيرون مي فرستم.\r\nاين زندگي جديد من است و بايد خودم را با آن وفق دهم. شايد روزي اين طلسم شكسته شود و بتوانم با دنياي بيرون از اتاق دوباره ارتباط داشته باشم. الان شما كه اين مطالب را مي خوانيد، اميدوارم كه برايتان حادثه بدي رخ ندهد !\r\n"},{"id":1019,"category_id":7,"category_code":"s7","source_id":189,"title":"مزه کن","content":"حیف نون: ﺍﯾﻦ ﺳﻮﭖ ﺭﻭ ﻣﺰﻩ ﮐﻦ\r\nﮔﺎﺭﺳﻮﻥ: ﭼﯿﺰﯼ توشه؟\r\nحیف نون: ﻓﻘﻂ ﻣﺰﻩ ﮐﻦ\r\nﮔﺎﺭﺳﻮﻥ: ﺍﮔﻪ ﺳﺮﺩﻩ ﺑﮕﻢ ﻋﻮﺽ ﮐﻨﻦ\r\nحیف نون: ﺩﺍﺭﻡ ﺧﻮﺍﻫﺶ می کنم ﻓﻘﻂ ﻣﺰﻩ ﮐﻦ\r\nﮔﺎﺭﺳﻮﻥ: ﻣﻦ ﺩﺍﺭﻡ ﺧﻮﺍﻫﺶ می کنم ﺍﮔﻪ ﭼﯿﺰﯼ ﮐﻢ ﺩﺍﺭﻩ بگید\r\nحیف نون: ﺑﺮﺍﺩﺭ ﻣﻦ! می گم ﻣﺰﻩ ﮐﻦ، ﯾﻌﻨﯽ ﻣﺰﻩ ﮐﻦ! ﺑﻪ ﺣﺮﻓﻢ ﮔﻮﺵ ﺑﺪﻩ\r\nﮔﺎﺭﺳﻮﻥ: ﺑﺎﺷﻪ ﺍﻻﻥ می چشم… ﻗﺎﺷﻖ ﮐﺠﺎست؟\r\nحیف نون: آﻫﺎ! ﻗﺎﺷﻖ ﮐﺠﺎست ﻣﺮﺗﯿﮑﻪ؟\r\n"},{"id":1020,"category_id":7,"category_code":"s7","source_id":190,"title":"ایرانسل","content":"\r\nاز بس ایرانسل پیامک پیشواز فرستاده و من نگرفتم پیام داده: \r\nمشترک گرامی اگر وضعیت مالی شما تا این حد بد است\r\nبه شماره **** عدد ۵ را ارسال کنید تا به شما کمک مالی شود!\r\nبازم هیچی نفرستادم پیام داده : گدا به این شماره تک بزن قطع کن!\r\n"},{"id":1021,"category_id":7,"category_code":"s7","source_id":191,"title":"مرگ گربه","content":"حکیمی بر سر راهی می‌ گذشت . دید پسر بچه ‌ای گربه خود را در جوی آب می ‌شوید . \r\nگفت : گربه را نشور ، می ‌میرد ! \r\nبعد از ساعتی که از همان راه بر می‌ گشت دید که بعله ... ! \r\nگربه مرده و پسرک هم به عزای او نشسته . \r\nگفت : به تو نگفتم گربه را نشور ، می ‌میرد ؟\r\nپسرک گفت : برو بابا ، از شستن که نمرد ، موقع چلاندن مرد !\r\n"},{"id":1022,"category_id":7,"category_code":"s7","source_id":192,"title":"همه کس - یک کس - هر کس و هیچ کس","content":"چهار نفر بودند بنام های همه کس - یک کس - هر کس و هیچ کس\r\nیک کار مهم وجود داشت که میبایست انجام می شد و از همه کس خواسته شد آن را انجام دهد .\r\nهمه کس میدونست که یک کسی آن را انجام خواهد داد .\r\nهر کسی میتوانست آن را انجام دهد اما هیچ کس آن را انجام نداد .\r\nیک کسی از این موضوع عصبانی شد به خاطر اینکه این وظیفه همه کس بود .\r\nهمه کس فکر می کرد هر کسی نمی تواند آن را انجام دهد اما هیچ کس نفهمید که هر کسی آن را انجام نخواهد داد .\r\nسرانجام این شد که همه کس یک کسی را برای کاری که هر کسی نمی توانست انجام دهد و هیچ کس انجام نداد سرزنش کرد .\r\n"},{"id":1023,"category_id":7,"category_code":"s7","source_id":193,"title":"مراحل ازدواج","content":"\r\nگویند : پسری قصد ازدواج داشت .\r\nپدرش گفت : بدان ازدواج سه مرحله دارد . \r\nمرحله اول ماه عسل است که در آن تو صحبت می‌ کنی و زنت گوش می‌ دهد .\r\nمرحله دوم او صحبت می‌ کند و تو گوش می ‌کنی ،\r\nاما مرحله سوم که خطرناک ترین مراحل است\r\nو آن موقعی است که هر دو بلند بلند داد می‌ کشید و همسایه‌ ها گوش می‌ کنند !\r\n"},{"id":1024,"category_id":7,"category_code":"s7","source_id":194,"title":"شکایت شاکی","content":"در زمان آغا محمد خان قاجار ، شخصى از حاکم شهر خود که با صدر اعظم نسبت داشت ، نزد صدر اعظم شکایت برد .\r\nصدر اعظم دانست حق با شاکى است گفت : اشکالى ندارد ، مى توانى به اصفهان بروى .\r\nمرد گفت : اصفهان در اختیار پسر برادر شماست .\r\nگفت : پس به شیراز برو .\r\nاو گفت : شیراز هم در اختیار خواهر زاده شماست .\r\nگفت : پس به تبریز برو .\r\nگفت : آنجا هم در دست نوه شماست .\r\nصدر اعظم بلند شد و با عصبانیت فریاد زد : چه مى دانم برو به جهنم .\r\nمرد با خونسردى گفت : متاسفانه آنجا هم مرحوم پدر شما حضور دارد .\r\n"},{"id":1025,"category_id":7,"category_code":"s7","source_id":195,"title":"خیال خام","content":"شخصی در حال تنگدستی و بی پولی به زن خود گفت: اگر بخواهیم فردا شب پلو بخوریم و فردا بروم یک من برنج بگیرم، چه قدر روغن برای آن لازم است؟\r\nزن جواب داد: دومن روغن لازم دارد.\r\nمرد با تعجب گفت: چه طور یک من برنج، دو من روغن می خواهد؟\r\nزن گفت: حالا که ما با خیال پلو می پزیم لااقل بگذار چرب تر بخوریم.\r\n"},{"id":1026,"category_id":7,"category_code":"s7","source_id":196,"title":"کلاه آسیابان","content":"شخصی در آسیابی منزل کرد و به آسیابان گفت سحر مرا بیدار کن چون خوابش برد آسیابان کلاه او را برداشت و کلاه خودش را بر سر او گذاشت و سحر او را بیدار کرد.\r\nچون قدری راه آمد و روز روشن شد به لب جویی رسید نظر در آب کرد و دید که کلاه آسیابان بر سر اوست گفت: من به او گفتم که مرا بیدار کن او خودش را بیدار کرد مراجعت کرد و با آسیابان مخاصمه می کرد که چرا مرا بیدار نکردی.\r\n"},{"id":1027,"category_id":7,"category_code":"s7","source_id":197,"title":"ترس از شکر خدای","content":"شخصی می‌گفت: روزی به عیادت یکی از فضلا که بیمار بود رفتم و چون نزد او نشستم و پرسش احوال او کردم، به او گفتم خدا را شکر کن و حمد بجا بیاور. تبسم نمود و گفت: چگونه شکر کنم و حال آنکه خدای تعالی فرموده است: « و لئن شکرتم لازیدنکم» یعنی: شکر بکنید همانا زیاد می‌کنم برای شما ... و می‌ترسم اگر شکر او کنم بر بیماری من بیافزاید!"},{"id":1028,"category_id":7,"category_code":"s7","source_id":198,"title":"چه کسی بخیل است؟","content":"سائلی به گروهی رسید که طعام می خوردند، گفت: سلام بر شما ای بخیلان! گفتند: ما را بخیل چرا گفتی؟\r\nگفت: با تکه ای نان سخنم را تکذیب کنید!\r\n"},{"id":1029,"category_id":7,"category_code":"s7","source_id":199,"title":"آرزوی جوانی","content":"مردی از دوست خود پرسید: تا به حال که شصت سال از عمرت می گذرد، آیا به یکی از آرزوهای جوانی ات رسیده ای؟\r\nگفت: آری، فقط به یکی، هنگامی که پدرم در کودکی مرا تنبیه می کرد و موی سرم را می کشید، آرزو می کردم که به هیچ وجه مو نداشته باشم و امروز به این آرزو رسیده ام.\r\n"},{"id":1030,"category_id":7,"category_code":"s7","source_id":200,"title":"دعای غلام","content":"مردی از پشت در شنید که خدمتکارش بعد از ادای فریضه دست به آسمان برداشته دعا می کند و می گوید: خدایا صدهزار تومان پول به آقای من بده و بعد از او بگیر.\r\nمرد وارد اتاق شد و گفت: این چه دعایی است که می کنی؟\r\nغلام گفت: هیچ نگویید. بگذارید خدا صدهزار تومان را به شما بدهد آن وقت من شما را بهتر از همه می شناسم و می دانم که دیگر ممکن نیست احدی بتواند حتی یک شاهی از آن پول ها را از شما بگیرد.\r\n"},{"id":1031,"category_id":7,"category_code":"s7","source_id":201,"title":"فاضل و نادان","content":"فاضلی به یکی از دوستان نامه ای می نوشت تا راز خود را با او درمیان گذارد. شخصی پهلوی او نشسته بود و به گوشه چشم نامه او را می خواند.\r\nبر وی دشوار آمد. بنوشت: اگر در پهلوی من دزدی ننشسته بودی نوشته مرا نمی خواندی، همه اسرار خود بنوشتمی.\r\nآن شخص گفت: به خدا من نامه تو را نمی خواندم.\r\nفاضل گفت: ای نادان پس از کجا دانستی که یاد تو در نامه است.\r\n"},{"id":1032,"category_id":7,"category_code":"s7","source_id":202,"title":"دختر صد ساله","content":"جوان تحصیل کرده ای پیش یکی از ثروتمندان رفت تا دختر او را خواستگاری کند.همین که مرد چشمش به قیافه جوان افتاد از این که چنین داماد موقری داشته باشد بسیار خوشحال شد.لذا برای تطمیع وی گفت: من سه دختر دارم که هیچ یک ازدواج نکرده اند و می خواهم همه را به راحتی شوهر دهم از این رو تصمیم گرفته ام به هر یک از آن ها موقع عروسی به تناسب سنشان پولی دهم تا دست خالی به خانه شوهر نروند.\r\nبه عنوان مثال آن که هجده سال دارد هجده میلیون تومان و آن که بیست وپنج سال دارد بیست وپنج و دیگری که سی ودوسال دارد به همان مقدار وجه نقد دهم. حال شما به خواستگاری کدام یک آمده اید؟\r\nجوان کمی فکرکرد و پرسید: شما دختر صدساله ندارید؟!\r\n"},{"id":1033,"category_id":7,"category_code":"s7","source_id":203,"title":"موسسه ی لاغری","content":"مرد بخیلی به یک موسسه لاغری مراجعه کرد تا لاغر شود. منشی به او گفت بفرمایید در چه سطحی می خواهید ثبت نام کنید ؟ بخیل گفت : چه سطوحی دارید؟ منشی گفت : ما در اینجا در دو سطح ثبت نام می کنیم یکی در سطح ویک (ضعیف) و یکی در سطح پاور(قدرت) اگر سطح ویک را انتخاب کنید، مبلغ ثبت نام یک ساعت و یک دلار است و اگر سطح پاور را انتخایب کنید، 2 ساعت و سه دلار است. بخیل با خود اندیشید من که زیاد لاغر نیستم الکی چرا سه دلار بدهم؟ و سپس سطح ضعیف را انتخاب کرد.\r\nوی را به مکانی در بسته هدایت کردند. در آنجا دختر جوان و زیبایی ایستاده بود مسئول موسسه گفت: شما یک ساعت وقت دارید که این دختر را در این مکان بسته گیر بیاندازید. ضمن اینکه با این جست و خیز لاغر می شوید، اگر توانستید او را کمتر از یک ساعت بگیرید، باقی یک ساعت وی در اختیار شماست!\r\nپس بخیل بسیار خوشحال شد و بدنبال دختر دوید تا وی را بگیرد ولی دختر بسیار چابک بود و مرتب از دست وی فرار می کرد. تا اینکه بخیل در مکانی دختر را به چنگ انداخت! اما هنوز اقدامی نکرده بود که زنگ پایان یک ساعت به صدا درآمد!\r\nبخیل هر چه اصرار کرد که پول یک ساعت اضافی را می‌دهم، بگذارید اینجا باشم؛ افاقه نکرد و او را از آن مکان بیرون کردند. بخیل با خود گفت : فردا استثنائا خساست را کنار می‌گذارم و سطح پاور را انتخاب می‌کنم و دو ساعت آن مکان را کرایه می کنم تا یک ساعت را صرف گرفتن دختر کنم و یک ساعت را…\r\nپس روز بعد پیش منشی آن موسسه رفت و سه دلار زد بروی میز و گفت: سطح پاور لطفا!بخیل را به همان مکان دیروز هدایت کرده و در را نیز از آنطرف قفل کردند. اما بخیل اثری از دختر در آنجا ندید. ناگهان چشمش به مردی بسیار هیکلی و درشت اندام خورد! بخیل وحشت زده پرسید تو کیستی و آن دختر کجاست؟\r\nشخص هیکلی گفت: آن دختر مربوط به سطح ضعیف است و من مربوط به سطح پاور. حالا من دو ساعت دنبال تو می‌کنم و تو نیز دو ساعت وقت داری که خودت را از چنگ من نجات دهی و فرار کنی وگرنه…\r\n"},{"id":1034,"category_id":7,"category_code":"s7","source_id":204,"title":"آدرس اشتباهی","content":"روزی مردی به سفر میرود و به محض ورود به اتاق هتل ، متوجه میشود که هتل به کامپیوتر مجهز است . تصمیم میگیرد به همسرش ایمیل بزند . نامه را مینویسد اما در تایپ ادرس دچار اشتباه میشود و بدون اینکه متوجه شود نامه را میفرستد . در این ضمن در گوشه ای دیگر از این کره خاکی ، زنی که تازه از مراسم خاک سپاری همسرش به خانه باز گشته بود با این فکر که شاید تسلیتی از دوستان یا اشنایان داشته باشه به سراغ کامپیوتر میرود تا ایمیل های خود را چک کند . اما پس از خواندن اولین نامه غش میکند و بر زمین می افتد . پسر او با هول و هراس به سمت اتاق مادرش میرود و مادرش را بر نقش زمین میبیند و در همان حال چشمش به صفحه مانیتور می افتد: \r\n\r\nگیرنده : همسر عزیزم\r\nموضوع : من رسیدم \r\n\r\nمیدونم که از گرفتن این نامه حسابی غافلگیر شدی . راستش انها اینجا کامپیوتر دارند و هر کس به اینجا می اد میتونه برای عزیزانش نامه بفرسته . من همین الان رسیدم و همه چیز را چک کردم . همه چیز برای ورود تو رو به راهه . فردا میبینمت . امیدوارم سفر تو هم مثل سفر من بی خطر باشه . وای چه قدر اینجا گرمه !!\r\n"},{"id":1035,"category_id":7,"category_code":"s7","source_id":205,"title":"لقمه ی جانانه","content":"\r\nشخصی با پنج انگشت می خورد.\r\nاو را گفتند: چرا چنین می خوری؟گفت: اگر به سه انگشت لقمه برگیرم، دیگر انگشتانم را خشم آید.\r\nدیگری را گفتند: چرا با پنج انگشت لقمه برگیری؟\r\nگفت: چه کنم که بیش از اینم انگشت نباشد\r\n"},{"id":1036,"category_id":7,"category_code":"s7","source_id":206,"title":"گربه ی مزاحم","content":"ابلهی از دست گربه ای به ستوه آمده بود و هر چه او را از خانه بیرون می کرد و به جای دور می برد، باز به خانه باز می گشت. روزی گربه را در کیسه ضخیمی انداخته و به محل دوری می برد\r\nرفیقی از او پرسید: به کجا می روی؟\r\nگفت: فلان جا و نام محل را به اشتباه گفت.\r\nرفیقش گفت: ولی راه آن جا از این طرف نیست.مرد جواب داد: آهسته باش. خود هم می دانم این را به گربه می گویم.\r\n"},{"id":1037,"category_id":7,"category_code":"s7","source_id":207,"title":"شرط آزادی","content":"یکی از بزرگان به غلامش گفت: از مال خود گوشتی بستان و از آن طعامی ساز تا بخورم و تو را آزاد کنم. غلام شاد شد. گوشتی خرید و بریانی ساخت و پیش او آورد.\r\nخواجه خورد و گوشت را به غلام سپرد.\r\nدیگر روز گفت: بدان گوشت، آبگوشتی زعفرانی تهیه کن تا بخورم و تو را آزاد کنم. غلام فرمان برد. دوباره تکه گوشت را به غلام سپرد که کمی روغن بستان و با آن گوشت، طعامی برای دیگر روز فراهم کن تا بخورم و تو را آزاد سازم.\r\nغلام گفت: ای خواجه تو را به خدا بگذار من هم چنان غلام تو باشم و این تکه گوشت را آزاد کن!\r\n"},{"id":1038,"category_id":7,"category_code":"s7","source_id":208,"title":"شرح حال یک زندگی","content":"\r\nاز بدو تولد موفق بودم، وگرنه پام به این دنیا نمی رسید\r\nاز همون اول کم نیاوردم، با ضربه دکتر چنان گریه‌ای کردم که فهمید جواب «های»، «هوی» است.\r\nهیچ وقت نگذاشتم هیچ چیز شکستم بدهد، پی‌درپی شیر میخوردم و به درد دلم توجه نمی کردم!\r\nاین شد که وقتی رفتم مدرسه از همه هم سن و سالهای خودم بلندتر بودم و همه ازم حساب می‌بردند.\r\nهیچ وقت درس نخوندم، هر وقت نوبت من شد که برم پای تخته زنگ می‌خورد.\r\nهر صفحه‌ای از کتاب را که باز می کردم، جواب سوالی بود که معلمم از من می‌پرسید.\r\nاین بود که سال سوم، چهارم دبیرستان که بودم، معلمم که من را نابغه می‌دانست منو فرستاد المپیاد ریاضی!\r\nتو المپیاد مدال طلا بردم! آخه ورق من گم شده بود و یکی از ورقه‌ها بی اسم بود، منم گفتم اسممو یادم رفته بنویسم!\r\nبدون کنکور وارد دانشگاه شدم هنوز یک ترم نگذشته بود که توی راهروی دانشگاه یه دسته عینک پیدا کردم،\r\nاومدم بشکنمش که خانمی سراسیمه خودش را به من رسوند و از این که دسته عینکش رو پیدا کرده\r\nبودم حسابی تشکر کرد و گفت: نیازی به صاف کردنش نیست زحمت نکشید این شد که هر وقت\r\nچیزی از زمین برمی‌داشتم، یهو جلوم سبز می شد و از این که گمشده‌اش را پیدا کرده بودم حسابی تشکر می کرد.\r\nبعدا توی دانشگاه پیچید: دختر رئیس دانشگاه، عاشق ناجی‌اش شده، تازه فهمیدم که اون دختر کیه و اون ناجی کیه!\r\nیک روز که برای روز معلم برای یکی از استادام گل برده بودم یکی از بچه‌ها دسته گلم رو از پنجره شوت کرد بیرون،\r\nمنم سرک کشیدم ببینم کجاست که دیدم افتاده تو بغل اون دختره!\r\nخلاصه این شد ماجری خواستگاری ما\r\nو الان هم استاد شمام! کسی سوالی نداره!؟\r\n"},{"id":1039,"category_id":7,"category_code":"s7","source_id":209,"title":"کفن دزد اول","content":"آورده اند که کفن دزدی در بستر مرگ افتاده بود،پسر خویش را فراخواند، پسر به نزد پدر رفت گفت: ای پدر امرت چیست؟ پدر گفت: پسرم من تمام عمر به کفن دزدی مشغول بودم و همواره نفرین خلقی بدنبالم بود اکنون که در بستر مرگم و فرشتهء مرگ را نزدیک حس می کنم بار این نفرین بیش از پیش بردوشم سنگینی می کند. از تو میخواهم بعد از مرگم چنان کنی که خلایق مرا دعا کنند و از خدای یکتا مغفرت مرا خواهند. \r\n‫پسر گفت ای پدر چنان کنم که می خواهی و از این پس مرد و زن را به دعایت مشغول سازم. \r\n‫پدر همان دم جان به جان آفرین تسلیم کرد. \r\n‫از فردا پسر شغل پدر پیشه کرد با این تفاوت که کفن از مردگان خلایق می دزدید و چوبی به ماتحت آن مردگان فرو می نمود و از آن پس خلایق می گفتند خدا کفن دزد اول را بیامرزد که فقط می دزدید و چنین بر مردگان ما روا نمی داشت !\r\n"}];
